namespace Emberfall.DevHarness
{
    /// <summary>
    /// Runs the engine-free half of the game outside Unity: content validation, determinism
    /// checks, a save round-trip, a readable sample battle and a full campaign balance pass.
    /// Build with build.cmd, run the exe, read the report.
    /// </summary>
    internal static partial class Program
    {
        private static int _failures;

        private static int Main(string[] args)
        {
            bool solve = false;
            bool talentValue = false;
            bool fidelity = false;
            bool guildConditions = false;
            bool guildPath = false;
            bool guildTech = false;
            bool guildTalentThemes = false;
            bool momentSurvey = false;
            bool reconcile = false;
            int wallStudy = 0;
            bool lineCalibration = false;
            bool probeStudy = false;
            bool tempoStudy = false;
            string tempoMode = null;
            bool solvePrereqs = false;
            string solvePrereqsMode = null;
            bool parityStudy = false;
            string parityMode = null;
            string reconcileStage = null, reconcileLevels = null;
            string only = null;
            string contentDir = null;
            for (int i = 0; i < args.Length; i++)
            {
                if (args[i] == "--solve-recommended-power") { solve = true; continue; }
                if (args[i] == "--talents-worth-picking") { talentValue = true; continue; }
                if (args[i] == "--fidelity") { fidelity = true; continue; }
                if (args[i] == "--line-calibration") { lineCalibration = true; continue; }
                // Measurement only: the level search on its own, at the committed table. See
                // RunProbeStudy - it is how SolverMaxProbesPerStage is sized.
                if (args[i] == "--probe-study") { probeStudy = true; continue; }
                if (args[i] == "--wall-study")
                {
                    wallStudy = 20;
                    int n;
                    if (i + 1 < args.Length && int.TryParse(args[i + 1], out n)) { wallStudy = n; i++; }
                    continue;
                }
                // Measurement flags, not checks and not run by the gate: --wall-modes picks which players
                // --wall-study walks (a subset of "fuses,noconv,none"); --relevel is lever R2 of
                // Docs/ECONOMY-PROPOSAL-R4.md, see RunRelevel.
                if (args[i] == "--wall-modes" && i + 1 < args.Length) { _wallModes = args[++i]; continue; }
                if (args[i] == "--relevel" && i + 1 < args.Length) { _relevelSpec = args[++i]; continue; }
                if (args[i] == "--guild-conditions") { guildConditions = true; continue; }
                if (args[i] == "--guild-path") { guildPath = true; continue; }
                if (args[i] == "--guild-tech") { guildTech = true; continue; }
                if (args[i] == "--guild-talent-themes") { guildTalentThemes = true; continue; }
                if (args[i] == "--moment-survey") { momentSurvey = true; continue; }
                if (args[i] == "--tempo-study")
                {
                    tempoStudy = true;
                    if (i + 1 < args.Length && !args[i + 1].StartsWith("-") && !Directory.Exists(args[i + 1])) tempoMode = args[++i];
                    continue;
                }
                if (args[i] == "--solve-prereqs")
                {
                    solvePrereqs = true;
                    if (i + 1 < args.Length && !args[i + 1].StartsWith("-") && !Directory.Exists(args[i + 1])) solvePrereqsMode = args[++i];
                    continue;
                }
                // Measurement only: every economy walk in the run fields the role-blind line it had
                // before WantedLine, so the gate or a solve against a scratch copy of the content
                // can be read against the old reference player.
                if (args[i] == "--role-blind") { _walkRoleBlind = true; continue; }
                if (args[i] == "--parity-study")
                {
                    parityStudy = true;
                    if (i + 1 < args.Length && !args[i + 1].StartsWith("-") && !Directory.Exists(args[i + 1])) parityMode = args[++i];
                    continue;
                }
                if (args[i] == "--ceil-reconcile")
                {
                    reconcile = true;
                    if (i + 1 < args.Length && !args[i + 1].StartsWith("-") && args[i + 1].Contains("-")
                        && args[i + 1].Length <= 5) reconcileStage = args[++i];
                    if (reconcileStage != null && i + 1 < args.Length && args[i + 1].Contains("/")
                        && !Directory.Exists(args[i + 1])) reconcileLevels = args[++i];
                    continue;
                }
                if (args[i] == "--check" && i + 1 < args.Length) { only = args[++i]; continue; }
                if (contentDir == null) contentDir = args[i];
            }
            if (contentDir == null) contentDir = FindContentDir();

            // THE SOLVER IS NOT A CHECK, and it deliberately does not run beside them: it WRITES
            // campaign.json, so it returns before one check has read the file it is about to
            // change. The guards run on the NEXT build-check, against what it wrote.
            if (solve) return RunRecommendedPowerSolver(contentDir);
            // Also not a check, and not run by the gate: see RunCeilReconcile.
            if (reconcile) return RunCeilReconcile(contentDir, reconcileStage, reconcileLevels);
            if (wallStudy > 0) return RunWallStudy(contentDir, wallStudy);
            if (_relevelSpec != null) return RunRelevel(contentDir, _relevelSpec);
            if (lineCalibration) return RunLineCalibration(contentDir);
            // Nor this: the probe study measures the level search and writes nothing.
            if (probeStudy) return RunProbeStudy(contentDir);
            // Not a check either: the tempo study (TempoStudy.cs) measures and writes nothing.
            if (tempoStudy) return RunTempoStudy(contentDir, tempoMode);
            // Nor this: the solve's prerequisites (SolvePrereqs.cs) measure and write nothing.
            if (solvePrereqs) return RunSolvePrereqs(contentDir, solvePrereqsMode);
            // Nor the parity study (ParityStudy.cs): it measures and writes nothing.
            if (parityStudy) return RunParityStudy(contentDir, parityMode);

            Console.OutputEncoding = Encoding.UTF8;
            Line("EMBERFALL CORE HARNESS");
            Line("content: " + contentDir);
            Line("");

            ContentDatabase content = LoadContent(contentDir);
            if (content == null) return 1;

            // The talent-value table alone, for a talent pass that wants the reading without the
            // rest of the harness. It asserts exactly what it asserts inside the full run.
            if (talentValue)
            {
                CheckTalentsAreWorthPicking(content);
                return _failures == 0 ? 0 : 1;
            }

            // Named checks alone, for a pass iterating on one or two of them: --check A,B runs the
            // private static checks called A and B, handed the content where they take it. A
            // development aid; build-check.ps1 never passes it, so the gate always runs the lot.
            if (only != null)
            {
                string[] names = only.Split(',');
                for (int n = 0; n < names.Length; n++)
                {
                    System.Reflection.MethodInfo m = typeof(Program).GetMethod(names[n].Trim(),
                        System.Reflection.BindingFlags.NonPublic | System.Reflection.BindingFlags.Static);
                    if (m == null) { Check(false, "no check called " + names[n]); continue; }
                    System.Reflection.ParameterInfo[] ps = m.GetParameters();
                    m.Invoke(null, ps.Length == 0 ? new object[0]
                        : ps.Length == 2 ? new object[] { content, contentDir }
                        : new object[] { ps[0].ParameterType == typeof(string) ? (object)contentDir : content });
                }
                Line(_failures == 0 ? "RESULT: all checks passed" : "RESULT: " + _failures + " check(s) FAILED");
                return _failures == 0 ? 0 : 1;
            }

            // Not a check: which stage openings hold each juice moment (JuiceChecks.cs), for the capture plan.
            if (momentSurvey) return RunMomentSurvey(content);

            // The guild floor conditions' study (GuildDungeonChecks.RunConditionStudy). Not a check:
            // the instrument floor-conditions.json's pool, magnitudes and floor lists are read from.
            if (guildConditions) return GuildDungeonChecks.RunConditionStudy(content);
            // The Guild Path's study (GuildPathChecks.RunStudy). Not a check: the instrument
            // guild-path.json's pay and prices are derived from.
            if (guildPath) return GuildPathChecks.RunStudy(content);
            // The guild tech tree's study (GuildTechChecks.RunGuildTechStudy). Not a check either:
            // the instrument guild-tech.json's rung size, prices and level curve are derived from,
            // and where every guild talent is read at parity.
            if (guildTech) return RunGuildTechStudy(content, contentDir);
            // Every guild talent across the floor themes and conditions (GuildTalentThemes.cs), on
            // its own. The same reading --guild-tech ends with, split out because authoring a
            // family's three options is an iteration and the derivation above it does not move.
            if (guildTalentThemes)
            {
                Line("GUILD TALENTS ACROSS THE FLOOR THEMES - claude/DESIGN-GUILD-TECH.md G10");
                Line("");
                GuildTalentThemes(content, true);
                return 0;
            }

            // The fidelity pass and the star band alone, for a content pass that is moving kits
            // against their sentences and wants both readings without the rest of the harness.
            if (fidelity)
            {
                CheckFidelityPassTwo(content);
                CheckEngineGapsPassThree(content);
                CheckStarBandByRole(content);
                return _failures == 0 ? 0 : 1;
            }

            CheckContent(content);
            CheckSpriteDelivery(content, contentDir);
            CheckEveryDeliveredSheetIsPlayed(content, contentDir);
            CheckPortraitDelivery(content, contentDir);
            CheckHeroRoleOrdinals(content);
            CheckEnumParity(content);
            CheckTierFiveMechanics(content);
            CheckTierSixMechanics(content);
            CheckTierSevenMechanics(content);
            CheckTierEightMechanics(content);
            CheckAspectDirection(content);
            CheckNoAspectKeyedBehaviour(content);
            CheckOnKillPassive(content);
            CheckDispel(content);
            CheckAbilityPotency(content);
            CheckDeterminism(content);
            CheckLiveSession(content);
            CheckEffectHitResistNoOp(content);
            CheckEffectHitResistDirection(content);
            CheckBypassResist();
            CheckTeamSizeStructure(content);
            CheckProvokeTargeting(content);
            CheckStatusExpiry(content);
            CheckStatusAndStatBehavior(content);
            CheckHolyBlockControlImmunity(content);
            CheckResolveCounter(content);
            CheckPassivesAndTalents(content);
            CheckEffectConditions(content);
            CheckStatStatusesAndTargetModes(content);
            CheckTurnStatusAndEnemyTriggers(content);
            CheckMarksLimitsAndLedger(content);
            CheckHistoryAlliesAndCharges(content);
            CheckBatchThreeMechanics(content);
            CheckLastTargetAndTalentAppends(content);
            CheckFunnelBankingPrimitives(content);
            CheckBatchFiveEngineGaps(content);
            CheckLinkedTargeting(content);
            CheckNineGaps(content);
            CheckAllyDonorModes(content);
            CheckEngineGapsPass(content);
            CheckAuthoredHeroSweep(content);
            CheckNoAbilityHitsItsOwnCaster(content);
            CheckSweepFillerIsFlimsiest(content);
            CheckStarBandByRole(content);
            CheckPerTargetBudgetIsPerFiring();
            CheckSourceFilterFiresForItsCauser(content);
            CheckCyrraReserveLandsOnTheAlly(content);
            CheckMirethAppendsFindTheirHost(content);
            CheckTriggerContextParity();
            CheckNoContentReadsAnUnsetField(content);
            CheckPerTargetBudgetLandsWholeFirings(content);
            CheckTalentCompletionPrimitives();
            CheckNoTalentIsEmpty(content);
            CheckAbilityTextIsPlayerFacing(content);
            CheckTalentTargetsResolve(content);
            CheckTalentOverridesNameALiveField(content);
            CheckWhatOtherBranchesWrote(content);
            CheckTalentTrialConfidence(content);
            CheckKitDefects(content);
            CheckFidelityPassTwo(content);
            CheckEngineGapsPassThree(content);
            CheckDarkTalents(content);
            CheckAuthoredTalentSweep(content);
            // After the talent sweep, which asserts the talents' half of the matrix's coverage; this
            // is the basics', actives' and passives' half, read off the same measurement.
            CheckArenaMatrix(content);
            CheckTalentsAreWorthPicking(content);
            CheckAuthoredKitExercise(content);
            CheckEveryAuthoredActiveIsCast(content);
            CheckAbilityNumbersMatchTheSimulation(content);
            CheckAbilityCardTextIsComplete(content, contentDir);
            CheckAbilityFactsMatchTheSimulation(content, contentDir);
            CheckWallChestsContentAndCard(content, contentDir);
            CheckWallChestsPayOnce(content, contentDir);
            CheckWallChestsRollBack(content, contentDir);
            ReportTalentExercise();

            CheckDebrief();
            CheckDebriefRealVictories(content);
            CheckRelics(content);
            CheckEvents(content, contentDir);
            CheckRecital(content);
            CheckCampaignStructure(content);
            CheckWaveResolve(content);
            CheckWaveReplay(content);
            CheckBattleStats(content);
            CheckWaveDrip(content);
            CheckClearedStagesById(content, contentDir);
            CheckStageResumeAfterWaveResolve(content);
            CheckRegenClampOnLoad(content);
            CheckProving(content);
            CheckSaveRoundTrip(content);
            CheckOnboarding(content);
            CheckOnboardingSwitch(content, contentDir);
            CheckTelemetry(content, contentDir);
            CheckDailyLoop(content, contentDir);
            CheckSinks(content, contentDir);
            CheckSealed(content, contentDir);
            CheckQuartermaster(content, contentDir);
            CheckRelicEndgame(content, contentDir);
            CheckWayfarersRoad(content, contentDir);
            CheckAudio(content, contentDir);
            CheckJuice(content, contentDir);
            CheckCaptureWatchdog(content, contentDir);
            CheckFeatureUnlockGating(content, contentDir);
            CheckAccounts(content);
            _failures += CloudChecks.Run(content, contentDir);
            CheckGuilds(contentDir);
            // The guild dungeon's own checks live in GuildDungeonChecks.cs so the guild branch and
            // this file never edit the same lines; this is the one line that wires them in.
            _failures += GuildDungeonChecks.Run(content, contentDir);
            // The Guild Path (GuildPathChecks.cs): its numbers re-derived, the server's copy of
            // them, and the property it exists for - breadth, never power.
            _failures += GuildPathChecks.Run(content, contentDir);
            GuildTechGate(content, contentDir);
            CheckSummonPity(content);
            CheckRepeatCap(content);
            CheckRelicDust(content);
            CheckRelicInventoryModel(content);
            CheckArmor(content);
            PrintSampleBattle(content);
            CheckStageWinnability(content);
            CheckPinnedFiveBodyCurve(content);
            // Opt-in. The derivation is a tuning instrument that costs tens of thousands of
            // battles; the thing that GUARDS the definition afterwards is cheap and always runs.
            // Set EMBERFALL_DERIVE=1 to re-derive.
            if (Environment.GetEnvironmentVariable("EMBERFALL_DERIVE") == "1")
                ReportRecommendedPowerDerivation(content);
            CheckArmoredCurveDelta(content);
            CheckUnderlevelledLoses(content);
            CheckFusionEconomyDerivation(content);
            CheckFusionRules(content);
            EconomyRun economy = RunCampaignBalancePass(content);
            ReportPowerSources(content, economy);
            ReportQuartermasterGold(content, economy);
            // The band is graded on the REFERENCE player's walk, the one recommendedPower is derived
            // from: see CheckFusionNeverGates. The fusing walk above is what every other table reads.
            CheckCampaignPowerCurve(content, SimulateEconomyUnder(content, 1, false, false));
            ReportPaceTargets(economy);
            ReportFusionWalk(content, economy);
            ReportResolvesPerFirstClear(content, economy);
            ReportPaceAcrossSeeds(content);
            CheckFusionNeverGates(content);
            CheckEconomyRespondsToIncome(content);
            CheckWalksRespectUnlocks(content, economy);
            // After all of them, because it asserts on what they actually resolved
            // while running - the economy responsiveness probe included.
            CheckInstrumentsSeeTheWholeCurve(content);
            CheckSolverAndGateCompileOneList(contentDir);
            // The battle HUD's layout (BattleHudChecks.cs): every plate and pill placed through the
            // screen's own BattleHudLayout at three phone shapes, and none of them meet.
            CheckBattleHud(contentDir);
            // The R15 v2 stage look (StageChecks.cs): stand-ins, facing, scale and framing, from the real content and art.
            CheckStage(content, contentDir);
            PrintInstrumentComparison();

            Line("");
            if (_failures == 0) Line("RESULT: all checks passed");
            else Line("RESULT: " + _failures + " check(s) FAILED");
            return _failures == 0 ? 0 : 1;
        }

        // ---------------------------------------------------------------- helpers






        // ---------------------------------------------------------------- history, allies, charges

        private static readonly StatusKind[] FourthTierStatuses =
            { StatusKind.Covered, StatusKind.Provoked, StatusKind.Guard, StatusKind.Vulnerable };

        private static readonly EffectCondition[] HistoryConditions =
        {
            EffectCondition.SubjectActedThisRound, EffectCondition.SubjectHasNotActedThisRound,
            EffectCondition.SubjectDamagedSinceMyTurn, EffectCondition.SubjectIsMyPreviousTarget,
            EffectCondition.SubjectIsNotMyPreviousTarget, EffectCondition.CasterRepeatedActionType,
            EffectCondition.AlreadyDamagedSubjectThisRound
        };

        private static readonly PassiveTrigger[] AllyTriggers =
        {
            PassiveTrigger.OnAllyHpBelowThreshold, PassiveTrigger.OnAllyHealed,
            PassiveTrigger.OnAllyShielded, PassiveTrigger.OnAllyWouldDie
        };

        private static void CheckHistoryAlliesAndCharges(ContentDatabase live)
        {
            Line("HISTORY, ALLY TRIGGERS, CHARGES, REDIRECTION");
            CheckNothingShippedUsesTheFourthTier(live);
            CheckFourthTierOrdinalPins();
            CheckHistoryConditions();
            CheckAllyTriggers();
            CheckRedirectionAndProvoke();
            CheckChargesAndTargetHp();
            CheckVulnerable();
            Line("");
        }

        private static void CheckNothingShippedUsesTheFourthTier(ContentDatabase db)
        {
            List<UnitDef> units = new List<UnitDef>();
            for (int i = 0; i < db.Heroes.Count; i++) units.Add(db.Heroes[i]);
            for (int i = 0; i < db.Enemies.Count; i++) units.Add(db.Enemies[i]);

            int statuses = 0, conds = 0, trigs = 0, hpScaled = 0;
            List<string> charges = new List<string>();
            for (int i = 0; i < units.Count; i++)
            {
                UnitDef def = units[i];
                List<EffectDef> all = new List<EffectDef>();
                List<string> where = new List<string>();
                if (def.BasicAttack != null)
                    AddWithNames(all, where, def.Id + "/" + def.BasicAttack.Name, def.BasicAttack.Effects);
                if (def.Active != null)
                    AddWithNames(all, where, def.Id + "/" + def.Active.Name, def.Active.Effects);
                for (int pi = 0; pi < def.Passives.Count; pi++)
                {
                    AddWithNames(all, where, def.Id + "/" + def.Passives[pi].Name, def.Passives[pi].Effects);
                    for (int t = 0; t < AllyTriggers.Length; t++)
                        if (def.Passives[pi].Trigger == AllyTriggers[t]) trigs++;
                }
                for (int e = 0; e < all.Count; e++)
                {
                    EffectDef ef = all[e];
                    for (int k = 0; k < FourthTierStatuses.Length; k++)
                        if (ef.Status == FourthTierStatuses[k] || ef.ConditionStatus == FourthTierStatuses[k]
                            || ef.TargetStatus == FourthTierStatuses[k]) statuses++;
                    for (int c = 0; c < HistoryConditions.Length; c++)
                        if (ef.Condition == HistoryConditions[c]) conds++;
                    if (ef.Charges != 0) charges.Add(where[e]);
                    if (ef.TargetMaxHpRatio != 0f || ef.TargetCurrentHpRatio != 0f
                        || ef.TargetMissingHpRatio != 0f) hpScaled++;
                }
            }

            Check(statuses > 0, "no shipped effect names Covered, Provoked, Guard or Vulnerable (" + statuses + ")");
            Check(conds > 0, "no shipped effect uses a history condition (" + conds + ")");
            Check(trigs > 0, "no shipped passive listens on an ally trigger (" + trigs
                  + ") - so no broadcast reaches a passive and the death path is unchanged");
            Check(charges.Count > 0, "shipped content stamps charges on a status" + Used(charges));
            Check(hpScaled > 0, "and no shipped effect scales off the target's HP (" + hpScaled
                  + ") - so TargetHpTerm sums three zeroes for every effect the game resolves");
        }

        private static void CheckFourthTierOrdinalPins()
        {
            Check((int)StatusKind.Ledger == 32 && (int)StatusKind.Covered == 33
                  && (int)StatusKind.Vulnerable == 36,
                  "StatusKind keeps every earlier ordinal and the four new kinds are appended ("
                  + (int)StatusKind.Covered + ".." + (int)StatusKind.Vulnerable + ")");
            Check((int)EffectCondition.LedgerAtLeast == 10 && (int)EffectCondition.SubjectActedThisRound == 11,
                  "EffectCondition keeps its ordinals and the history members are appended");
            Check((int)PassiveTrigger.OnStatusExpired == 15 && (int)PassiveTrigger.OnAllyHpBelowThreshold == 16,
                  "PassiveTrigger keeps its ordinals and the ally members are appended");
            Check((int)BattleEventType.BattleEnd == 20,
                  "and BattleEventType's existing ordinals are untouched - BattleEnd is still 20. "
                  + "CastCancelled is appended at 21, which moves none of them and so moves no "
                  + "fingerprint field");
        }

        /// <summary>
        /// Each history condition proved true where it should be and false where it should not,
        /// read off the evaluator directly - a boundary like "has not acted yet" is far easier to
        /// set up here than to arrange inside a fight.
        /// </summary>
        private static void CheckHistoryConditions()
        {
            CombatUnit caster = new CombatUnit(); caster.Id = 1; caster.MaxHp = 100f; caster.Hp = 100f;
            CombatUnit foe = new CombatUnit(); foe.Id = 2; foe.MaxHp = 100f; foe.Hp = 100f;
            CombatUnit other = new CombatUnit(); other.Id = 3; other.MaxHp = 100f; other.Hp = 100f;

            Check(!CombatSimulation.ConditionMet(HistCond(EffectCondition.SubjectActedThisRound), caster, foe),
                  "SubjectActedThisRound is false for a unit that has not acted");
            foe.ActedThisRound = true;
            Check(CombatSimulation.ConditionMet(HistCond(EffectCondition.SubjectActedThisRound), caster, foe),
                  "and true once it has");
            Check(!CombatSimulation.ConditionMet(HistCond(EffectCondition.SubjectHasNotActedThisRound), caster, foe),
                  "and its mirror is the exact complement");

            caster.LastTurnRound = 3;
            foe.LastDamagedRound = 2;
            Check(!CombatSimulation.ConditionMet(HistCond(EffectCondition.SubjectDamagedSinceMyTurn), caster, foe),
                  "SubjectDamagedSinceMyTurn is false for damage older than the caster's last turn");
            foe.LastDamagedRound = 3;
            Check(CombatSimulation.ConditionMet(HistCond(EffectCondition.SubjectDamagedSinceMyTurn), caster, foe),
                  "and true for damage in that round or later");

            Check(!CombatSimulation.ConditionMet(HistCond(EffectCondition.SubjectIsNotMyPreviousTarget), caster, foe),
                  "with NO previous target, \"a different target\" is false rather than true - a hero that "
                  + "has attacked nobody has not switched");
            caster.PreviousTargetId = 3;
            Check(CombatSimulation.ConditionMet(HistCond(EffectCondition.SubjectIsNotMyPreviousTarget), caster, foe),
                  "and true once it has attacked somebody else");
            Check(CombatSimulation.ConditionMet(HistCond(EffectCondition.SubjectIsMyPreviousTarget), caster, other),
                  "and its mirror names the body actually attacked last");

            Check(!CombatSimulation.ConditionMet(HistCond(EffectCondition.CasterRepeatedActionType), caster, foe),
                  "CasterRepeatedActionType is false before two turns are on record");
            caster.ActionsTaken = 2; caster.LastActionWasActive = true; caster.PreviousActionWasActive = true;
            Check(CombatSimulation.ConditionMet(HistCond(EffectCondition.CasterRepeatedActionType), caster, foe),
                  "and true after two turns of the same kind");
            caster.PreviousActionWasActive = false;
            Check(!CombatSimulation.ConditionMet(HistCond(EffectCondition.CasterRepeatedActionType), caster, foe),
                  "and false again when the kind changed");

            Check(!CombatSimulation.ConditionMet(HistCond(EffectCondition.AlreadyDamagedSubjectThisRound), caster, foe),
                  "AlreadyDamagedSubjectThisRound is false before the caster has hit it");
            caster.DamagedThisRound.Add(foe.Id);
            Check(CombatSimulation.ConditionMet(HistCond(EffectCondition.AlreadyDamagedSubjectThisRound), caster, foe),
                  "and true after");
            Check(!CombatSimulation.ConditionMet(HistCond(EffectCondition.AlreadyDamagedSubjectThisRound), caster, other),
                  "and still false for a body it has not hit, so the record is per target");

            // And the history is really kept by a running battle, not only settable by hand.
            BattleResult r = RunHistoryArena();
            int switched = 0;
            if (r != null)
                for (int i = 0; i < r.Events.Count; i++)
                    if (r.Events[i].Type == BattleEventType.PassiveTrigger
                        && r.Events[i].AbilityId == "hist_passive") switched++;
            Check(switched > 0,
                  "and a real battle keeps the history: a passive conditioned on having damaged its "
                  + "target already this round fired " + switched + " time(s)");
        }

        private static EffectDef HistCond(EffectCondition kind)
        {
            EffectDef e = new EffectDef();
            e.Condition = kind;
            e.ConditionOn = ConditionSubject.Target;
            return e;
        }


        /// <summary>One hero hitting one foe twice a round, with a passive gated on having
        /// already damaged it - so the history has to be kept by the battle for it to fire.</summary>
        private static BattleResult RunHistoryArena()
        {
            string heroes = @"{
  ""heroes"": [
    { ""id"": ""hist_hero"", ""name"": ""Hist"", ""aspect"": ""Ember"", ""role"": ""Striker"", ""startingHero"": true,
      ""hp"": 1000000, ""attack"": 100, ""defense"": 0, ""speed"": 900, ""critChance"": 0, ""critDamage"": 1.5,
      ""basic"": { ""id"": ""hist_basic"", ""name"": ""Twice"",
        ""effects"": [ { ""kind"": ""Damage"", ""target"": ""FrontEnemy"", ""power"": 0.01 },
                       { ""kind"": ""Damage"", ""target"": ""FrontEnemy"", ""power"": 0.01,
                         ""condition"": ""AlreadyDamagedSubjectThisRound"", ""conditionOn"": ""Target"" } ] },
