        private static void Line(string text) { Console.WriteLine(text); }

        /// <summary>Walk up from the executable until Assets/Resources/Content shows up.</summary>
        private static string FindContentDir()
        {
            DirectoryInfo dir = new DirectoryInfo(AppDomain.CurrentDomain.BaseDirectory);
            for (int i = 0; i < 8 && dir != null; i++)
            {
                string candidate = Path.Combine(dir.FullName, Path.Combine("Assets", Path.Combine("Resources", "Content")));
                if (Directory.Exists(candidate)) return candidate;
                dir = dir.Parent;
            }
            return Path.Combine(AppDomain.CurrentDomain.BaseDirectory, "Content");
        }

        /// <summary>Set from EMBERFALL_DUMP_STAGE_FP, read once rather than 72 times.</summary>
        private static readonly bool _dumpStageFingerprints =
            !string.IsNullOrEmpty(Environment.GetEnvironmentVariable("EMBERFALL_DUMP_STAGE_FP"));

        private static void Check(bool condition, string label)
        {
            if (condition) { Line("  [ok]   " + label); return; }
            _failures++;
            Line("  [FAIL] " + label);
        }

        private static string Fmt(float v) { return v.ToString("0.##", CultureInfo.InvariantCulture); }
        /// <summary>Three decimals, for the solver's band middles. x1.025 rounds to "1.03" under
        /// Fmt, and a band middle printed to two decimals is a band middle nobody can check.</summary>
        private static string Fmt3(float v) { return v.ToString("0.###", CultureInfo.InvariantCulture); }
        private static string Pct(float v) { return (v * 100f).ToString("0.#", CultureInfo.InvariantCulture) + "%"; }

        // ---------------------------------------------------------------- sprite delivery

        /// <summary>
        /// WHICH UNITS HAVE ART, WHICH ARE WAITING FOR IT, AND WHICH ARE BROKEN.
        ///
        /// Most of the roster is undrawn, and that is not a fault - so the interesting question is
        /// not "how many files are missing" but "is any unit missing a file it CLAIMS to have".
        /// Those two used to be the same question, and the answer was always the same noise.
        ///
        /// The rule mirrors UnitRig.Build:
        ///
        ///   visual.sprite empty         procedural primitive body. No file is expected.
        ///   spriteStatus "pending"      the shared mannequin. No file is expected, and a file
        ///                               turning up means the key was left behind when art landed.
        ///   otherwise                   the unit's own art. The file must resolve, or this fails
        ///                               with the unit's name and the path it looked in.
        ///
        /// "Resolves" means either a plain {sprite}.png or an animated {sprite}_idle.png with its
        /// {sprite}_idle.json sidecar, because those are the two things BuildSprite will accept -
        /// SpriteAnimator.TryCreate first, BattleAssets.UnitSprite second.
        ///
        /// This runs outside Unity, so it reads the FOLDER rather than Resources. That is a
        /// feature: it fails on a build machine with no editor, before anyone opens a battle.
        /// </summary>
        private static void CheckSpriteDelivery(ContentDatabase db, string contentDir)
        {
            Line("");
            Line("SPRITE DELIVERY");

            string parent = Path.GetDirectoryName(contentDir.TrimEnd(Path.DirectorySeparatorChar));
            string units = Path.Combine(parent, Path.Combine("Sprites", "Units"));
            if (!Directory.Exists(units))
            {
                Check(false, "the unit sprite folder exists at " + units);
                return;
            }

            Check(File.Exists(Path.Combine(units, PlaceholderSpriteId + ".png")),
                  "the one placeholder mannequin exists (Sprites/Units/" + PlaceholderSpriteId
                  + ".png) - every undrawn hero renders it");

            List<string> heroArt = new List<string>();
            List<string> heroPending = new List<string>();
            List<string> broken = new List<string>();
            List<string> stale = new List<string>();

            for (int i = 0; i < db.Heroes.Count; i++)
                Classify(db.Heroes[i], units, heroArt, heroPending, broken, stale);

            List<string> enemyArt = new List<string>();
            List<string> enemyPending = new List<string>();
            List<string> enemyProcedural = new List<string>();
            for (int i = 0; i < db.Enemies.Count; i++)
            {
                EnemyDef e = db.Enemies[i];
                if (string.IsNullOrEmpty(e.Visual.Sprite)) { enemyProcedural.Add(e.Id); continue; }
                Classify(e, units, enemyArt, enemyPending, broken, stale);
            }

            Line("  heroes:  " + db.Heroes.Count + " total, " + heroArt.Count + " with art, "
                 + heroPending.Count + " on the placeholder mannequin");
            Line("  enemies: " + db.Enemies.Count + " total, " + enemyArt.Count + " with art, "
                 + enemyPending.Count + " on the mannequin, " + enemyProcedural.Count
                 + " procedural (no sprite named)");

            Line("");
            Line("  HEROES WITH ART (" + heroArt.Count + "):");
            PrintIdColumns(heroArt);
            Line("  ENEMIES WITH ART (" + enemyArt.Count + "): " + string.Join(", ", enemyArt.ToArray()));
            Line("");
            Line("  HEROES ON THE MANNEQUIN (" + heroPending.Count + "):");
            PrintIdColumns(heroPending);
            Line("");

            for (int i = 0; i < broken.Count; i++) Line("  BROKEN: " + broken[i]);
            for (int i = 0; i < stale.Count; i++) Line("  STALE:  " + stale[i]);

            Check(broken.Count == 0,
                  "every unit that declares art has it - a unit listed BROKEN above is missing a file it says it owns");
            Check(stale.Count == 0,
                  "no unit is still marked pending after its art landed");
            Check(heroArt.Count + heroPending.Count == db.Heroes.Count,
                  "every hero is exactly one of: has art, or declared pending (none falls between)");

            CheckTheBrokenDetectorActuallyFires(units);
        }

        /// <summary>Must match BattleAssets.DummySpriteId. Repeated rather than referenced because
        /// that constant lives in the Unity assembly, which this harness deliberately cannot see -
        /// so the check above asserts the file is there under the name the engine will ask for.</summary>
        private const string PlaceholderSpriteId = "placeholder_dummy";

        private static void Classify(UnitDef def, string units, List<string> art, List<string> pending,
                                     List<string> broken, List<string> stale)
        {
            string sprite = def.Visual.Sprite;
            bool resolves = SpriteResolves(units, sprite);

            if (def.Visual.SpritePending)
            {
                if (resolves)
                    stale.Add(def.Name + " (" + def.Id + ") is marked pending but "
                              + WhichFile(units, sprite) + " exists - drop the spriteStatus key");
                else pending.Add(def.Id);
                return;
            }

            if (resolves) { art.Add(def.Id); return; }

            broken.Add(def.Name + " (" + def.Id + ") declares sprite \"" + sprite
                       + "\" but neither Sprites/Units/" + sprite + ".png nor Sprites/Units/"
                       + sprite + "_idle.png + .json exists");
        }

        /// <summary>The two shapes UnitRig.BuildSprite will accept, in the order it tries them.</summary>
        private static bool SpriteResolves(string units, string sprite)
        {
            if (string.IsNullOrEmpty(sprite)) return false;
            if (File.Exists(Path.Combine(units, sprite + "_idle.png"))
                && File.Exists(Path.Combine(units, sprite + "_idle.json"))) return true;
            return File.Exists(Path.Combine(units, sprite + ".png"));
        }

        private static string WhichFile(string units, string sprite)
        {
            if (File.Exists(Path.Combine(units, sprite + "_idle.png"))) return sprite + "_idle.png";
            return sprite + ".png";
        }

        /// <summary>
        /// A DELIBERATE BROKEN UNIT, so the check above is known to be capable of failing.
        ///
        /// Everything else here reports "no broken sprites", and a detector that has never fired is
        /// indistinguishable from one that cannot. This builds a hero whose art is declared and
        /// absent - the exact shape of the bug - and asserts it lands in the broken list and not in
        /// pending. Then it does the mirror case, the same hero marked pending, and asserts it
        /// lands in pending and not in broken. The pair is the point: it proves the two are told
        /// apart by the DECLARATION rather than by the missing file they both share.
        ///
        /// It fabricates a HeroDef rather than editing heroes.json, so it cannot leave residue and
        /// cannot be broken by content changing underneath it.
        /// </summary>
        private static void CheckTheBrokenDetectorActuallyFires(string units)
        {
            HeroDef ghost = new HeroDef();
            ghost.Id = "harness_missing_art_probe";
            ghost.Name = "Harness Probe";
            ghost.Visual.Sprite = "a_file_that_does_not_exist_on_purpose";

            List<string> art = new List<string>();
            List<string> pending = new List<string>();
            List<string> broken = new List<string>();
            List<string> stale = new List<string>();
            Classify(ghost, units, art, pending, broken, stale);

            Check(broken.Count == 1 && pending.Count == 0 && art.Count == 0,
                  "a hero pointed at a nonexistent sprite IS reported broken (the detector fires)");
            Check(broken.Count == 1 && broken[0].Contains("a_file_that_does_not_exist_on_purpose")
                  && broken[0].Contains("Harness Probe"),
                  "and the report names the hero and the path it looked in");

            ghost.Visual.SpriteStatus = VisualDef.StatusPending;
            art.Clear(); pending.Clear(); broken.Clear(); stale.Clear();
            Classify(ghost, units, art, pending, broken, stale);

            Check(pending.Count == 1 && broken.Count == 0,
                  "the SAME missing file, declared pending, is silent - the two cases are told apart"
                  + " by the declaration, not by the failed load");
        }

        // ---------------------------------------------------------------- sheet reachability

        /// <summary>
        /// Sheets that are delivered and deliberately played by nothing, each with the reason. A
        /// pin that no longer matches a file fails, so this list cannot outlive what it excuses.
        /// </summary>
        private static readonly Dictionary<string, string> KnownUnplayedSheets = new Dictionary<string, string>
        {
            { "rheia_the_revision_scribe_idle2",
              "delivered where her skill should be; no battle beat plays a second idle, and playing it as her"
              + " skill would put a standing loop on her cast. Docs/PINOY-LIST.md asks for the skill sheet" },
        };

        /// <summary>
        /// Clips that no call site names directly, and the BattleClips helper that returns them.
        /// basic2 is only ever reached through BasicClipFor, so that call is what has to exist.
        /// </summary>
        private static readonly Dictionary<string, string> ReachedThroughHelper = new Dictionary<string, string>
        {
            { BattleClips.Basic2, "BattleClips.BasicClipFor" },
        };

        /// <summary>
        /// EVERY DELIVERED SHEET IS PLAYED BY SOME BATTLE BEAT, so a delivery cannot sit in the
        /// project unused again without this saying so.
        ///
        /// That is how 49 sheets sat unplayed: 24 basic2 and 25 controlled were imported beside
        /// every other clip, the loader would have found them, and no line of the battle ever
        /// asked for them. Nothing failed, because asking for a clip nobody ships is silent by
        /// design and so is shipping a clip nobody asks for.
        ///
        /// Three halves, because a sheet is reachable only if all three hold:
        ///
        ///   1. its clip name is one BattleClips.Played lists - the vocabulary the battle requests;
        ///   2. every entry in that list is actually requested by runtime code outside
        ///      BattleClips.cs, so the list cannot claim a clip nothing plays;
        ///   3. the .png and its .json sidecar are both there, which is what BattleAssets.UnitAnimClip
        ///      needs to load either.
        ///
        /// Reads the folder, like CheckSpriteDelivery, and compiles BattleClips.cs itself beside the
        /// core, so the list checked here is the list the battle uses rather than a copy of it.
        /// </summary>
        private static void CheckEveryDeliveredSheetIsPlayed(ContentDatabase db, string contentDir)
        {
            Line("");
            Line("SHEET REACHABILITY");

            string resources = Path.GetDirectoryName(contentDir.TrimEnd(Path.DirectorySeparatorChar));
            string units = Path.Combine(resources, Path.Combine("Sprites", "Units"));
            string scripts = Path.Combine(Path.GetDirectoryName(resources), "Scripts");
            if (!Directory.Exists(units) || !Directory.Exists(scripts))
            {
                Check(false, "the unit sprite folder and the scripts folder exist beside the content");
                return;
            }

            List<string> sprites = new List<string>();
            for (int i = 0; i < db.Heroes.Count; i++) AddSprite(sprites, db.Heroes[i].Visual.Sprite);
            for (int i = 0; i < db.Enemies.Count; i++) AddSprite(sprites, db.Enemies[i].Visual.Sprite);

            List<string> unplayed = new List<string>();
            List<string> halves = new List<string>();
            Dictionary<string, int> perClip = new Dictionary<string, int>();
            HashSet<string> pinsSeen = new HashSet<string>();
            FindUnreachableSheets(units, sprites, KnownUnplayedSheets, unplayed, halves, perClip, pinsSeen);

            string counts = "";
            for (int i = 0; i < BattleClips.Played.Length; i++)
            {
                int n;
                perClip.TryGetValue(BattleClips.Played[i], out n);
                counts += (i > 0 ? ", " : "") + BattleClips.Played[i] + " " + n;
            }
            Line("  delivered sheets by clip: " + counts);
            foreach (KeyValuePair<string, string> pin in KnownUnplayedSheets)
                if (pinsSeen.Contains(pin.Key)) Line("  pinned unplayed: " + pin.Key + " - " + pin.Value);
            for (int i = 0; i < unplayed.Count; i++) Line("  UNPLAYED: " + unplayed[i]);
            for (int i = 0; i < halves.Count; i++) Line("  HALF:     " + halves[i]);

            Check(unplayed.Count == 0,
                  "every delivered sheet is a clip some battle beat requests (BattleClips.Played) - a sheet listed"
                  + " UNPLAYED above is in the project and nothing will ever show it");
            Check(halves.Count == 0,
                  "every delivered sheet has both its .png and its .json sidecar - the loader needs both");
            List<string> stalePins = new List<string>();
            foreach (string key in KnownUnplayedSheets.Keys) if (!pinsSeen.Contains(key)) stalePins.Add(key);
            Check(stalePins.Count == 0,
                  "every pinned unplayed sheet still exists"
                  + (stalePins.Count > 0 ? " (stale: " + string.Join(", ", stalePins.ToArray()) + ")" : ""));

            List<string> unrequested = UnrequestedClips(scripts);
            Check(unrequested.Count == 0,
                  "every clip in BattleClips.Played is requested by runtime code outside BattleClips.cs"
                  + (unrequested.Count > 0 ? " (nothing asks for: " + string.Join(", ", unrequested.ToArray()) + ")" : ""));

            CheckTheUnplayedDetectorActuallyFires();
        }

        private static void AddSprite(List<string> sprites, string sprite)
        {
            if (!string.IsNullOrEmpty(sprite) && !sprites.Contains(sprite)) sprites.Add(sprite);
        }

        /// <summary>
        /// Walks one folder. A file belongs to the LONGEST declared sprite id it starts with plus an
        /// underscore, so an id that happens to prefix another cannot claim the other's sheets;
        /// files that belong to no declared unit are out of scope here (they are orphans, not
        /// unplayed clips).
        /// </summary>
        private static void FindUnreachableSheets(string units, List<string> sprites, Dictionary<string, string> pins,
                                                  List<string> unplayed, List<string> halves,
                                                  Dictionary<string, int> perClip, HashSet<string> pinsSeen)
        {
            HashSet<string> stems = new HashSet<string>();
            foreach (string file in Directory.GetFiles(units))
            {
                string ext = Path.GetExtension(file).ToLowerInvariant();
                if (ext == ".png" || ext == ".json") stems.Add(Path.GetFileNameWithoutExtension(file));
            }

            List<string> sorted = new List<string>(stems);
            sorted.Sort(StringComparer.Ordinal);
            foreach (string stem in sorted)
            {
                string owner = null;
                for (int i = 0; i < sprites.Count; i++)
                    if (stem.StartsWith(sprites[i] + "_", StringComparison.Ordinal)
                        && (owner == null || sprites[i].Length > owner.Length)) owner = sprites[i];
                if (owner == null) continue;
                if (pins.ContainsKey(stem)) { pinsSeen.Add(stem); continue; }

                string clip = stem.Substring(owner.Length + 1);
                if (Array.IndexOf(BattleClips.Played, clip) < 0)
                {
                    unplayed.Add(stem + " (clip \"" + clip + "\" is not one BattleClips.Played lists)");
                    continue;
                }
                bool png = File.Exists(Path.Combine(units, stem + ".png"));
                bool json = File.Exists(Path.Combine(units, stem + ".json"));
                if (!png || !json)
                {
                    halves.Add(stem + " has " + (png ? ".png without .json" : ".json without .png"));
                    continue;
                }
                int n;
                perClip.TryGetValue(clip, out n);
                perClip[clip] = n + 1;
            }
        }

        /// <summary>Every Played clip whose constant, or the helper that returns it, is named by no
        /// runtime file other than BattleClips.cs. Dev Arena and Core files do not count: a clip the
        /// battle itself never asks for is exactly what this looks for.</summary>
        private static List<string> UnrequestedClips(string scripts)
        {
            StringBuilder runtime = new StringBuilder();
            foreach (string file in Directory.GetFiles(scripts, "*.cs", SearchOption.AllDirectories))
            {
                string rel = file.Substring(scripts.Length).Replace(Path.DirectorySeparatorChar, '/');
                if (rel.StartsWith("/Core/") || rel.StartsWith("/Dev/") || rel.EndsWith("/BattleClips.cs")) continue;
                runtime.Append(File.ReadAllText(file)).Append('\n');
            }
            string text = runtime.ToString();

            List<string> missing = new List<string>();
            foreach (System.Reflection.FieldInfo f in typeof(BattleClips).GetFields())
            {
                if (!f.IsLiteral || f.FieldType != typeof(string)) continue;
                string clip = (string)f.GetRawConstantValue();
                if (Array.IndexOf(BattleClips.Played, clip) < 0) continue;
                string helper;
                bool named = System.Text.RegularExpressions.Regex.IsMatch(text, @"\bBattleClips\." + f.Name + @"\b");
                bool viaHelper = ReachedThroughHelper.TryGetValue(clip, out helper) && text.Contains(helper);
                if (!named && !viaHelper) missing.Add(clip);
            }
            return missing;
        }

        /// <summary>
        /// A deliberate unreachable delivery, so the check above is known to be able to fail: a
        /// probe unit with a basic3 sheet, a basic2 with no sidecar and a complete skill, written to
        /// a temp folder and removed again.
        /// </summary>
        private static void CheckTheUnplayedDetectorActuallyFires()
        {
            string dir = Path.Combine(Path.GetTempPath(), "emberfall_sheet_probe_" + Guid.NewGuid().ToString("N"));
            Directory.CreateDirectory(dir);
            try
            {
                const string probe = "harness_sheet_probe";
                File.WriteAllText(Path.Combine(dir, probe + "_basic3.png"), "");
                File.WriteAllText(Path.Combine(dir, probe + "_basic3.json"), "{}");
                File.WriteAllText(Path.Combine(dir, probe + "_basic2.png"), "");
                File.WriteAllText(Path.Combine(dir, probe + "_skill.png"), "");
                File.WriteAllText(Path.Combine(dir, probe + "_skill.json"), "{}");

                List<string> unplayed = new List<string>();
                List<string> halves = new List<string>();
                Dictionary<string, int> perClip = new Dictionary<string, int>();
                HashSet<string> pinsSeen = new HashSet<string>();
                FindUnreachableSheets(dir, new List<string> { probe }, new Dictionary<string, string>(),
                                      unplayed, halves, perClip, pinsSeen);

                Check(unplayed.Count == 1 && unplayed[0].Contains("basic3"),
                      "a delivered sheet under a clip name no beat requests IS reported unplayed (the detector fires)");
                Check(halves.Count == 1 && halves[0].Contains("basic2") && !perClip.ContainsKey("basic2")
                      && perClip.ContainsKey("skill"),
                      "a sheet with no sidecar IS reported, and a complete one beside it is not");
            }
            finally
            {
                Directory.Delete(dir, true);
            }
        }

        // ---------------------------------------------------------------- portrait delivery

        /// <summary>
        /// WHICH UNITS HAVE A PROFILE BADGE, AND WHICH CLAIM ONE THEY DO NOT HAVE.
        ///
        /// The same question CheckSpriteDelivery asks about battle art, asked about the menu-side
        /// badge, and deliberately the same shape of answer - because the failure it guards
        /// against is the same one. A hero with no badge draws its initial, which is correct and
        /// silent. A hero that DECLARES a badge and has no file also draws its initial, which
        /// looks identical and is a bug. Nothing in a screenshot can tell those apart, so this is
        /// what tells them apart.
        ///
        /// The rule mirrors Widgets.DeclaredBadge:
        ///
        ///   visual.portrait empty   no badge claimed. The hero draws its initial, the enemy its
        ///                           sigil. No file is expected.
        ///   otherwise               Sprites/Portraits/{portrait}.png must exist, or this fails
        ///                           with the unit's name and the path it looked in.
        ///
        /// There is no "pending" state here and there should not be, which is the one place this
        /// differs from the sprite check. Battle art needs one because an empty visual.sprite
        /// already means "build the procedural body", so "not drawn yet" had to be said in a
        /// second key. An empty portrait has no such occupant, so absence IS "not delivered" and
        /// a third state would be a distinction with no difference behind it.
        ///
        /// Runs outside Unity and reads the FOLDER rather than Resources, for the same reason:
        /// it fails on a build machine with no editor, before anyone opens a screen.
        /// </summary>
        private static void CheckPortraitDelivery(ContentDatabase db, string contentDir)
        {
            Line("");
            Line("PORTRAIT DELIVERY");

            string parent = Path.GetDirectoryName(contentDir.TrimEnd(Path.DirectorySeparatorChar));
            string portraits = Path.Combine(parent, Path.Combine("Sprites", "Portraits"));
            if (!Directory.Exists(portraits))
            {
                Check(false, "the portrait folder exists at " + portraits);
                return;
            }

            List<string> withBadge = new List<string>();
            List<string> withoutBadge = new List<string>();
            List<string> broken = new List<string>();

            for (int i = 0; i < db.Heroes.Count; i++)
                ClassifyPortrait(db.Heroes[i], portraits, withBadge, withoutBadge, broken);

            List<string> enemyBadge = new List<string>();
            List<string> enemyNone = new List<string>();
            for (int i = 0; i < db.Enemies.Count; i++)
                ClassifyPortrait(db.Enemies[i], portraits, enemyBadge, enemyNone, broken);

            Line("  heroes:  " + db.Heroes.Count + " total, " + withBadge.Count + " with a badge, "
                 + withoutBadge.Count + " on the initial placeholder");
            Line("  enemies: " + db.Enemies.Count + " total, " + enemyBadge.Count + " with a badge, "
                 + enemyNone.Count + " on the sigil");

            if (withoutBadge.Count > 0)
            {
                Line("");
                Line("  HEROES ON THE INITIAL (" + withoutBadge.Count + "):");
                PrintIdColumns(withoutBadge);
            }

            Line("");
            for (int i = 0; i < broken.Count; i++) Line("  BROKEN: " + broken[i]);

            Check(broken.Count == 0,
                  "every unit that declares a portrait has it - a unit listed BROKEN above is missing"
                  + " a file it says it owns");
            Check(withBadge.Count + withoutBadge.Count == db.Heroes.Count,
                  "every hero is exactly one of: has a badge, or has none declared");

            // Every loose file is accounted for, in both directions. The check above catches a
            // declaration with no file; this catches a file no hero declares, which is the same
            // delivery going wrong the other way round - an icon landed under a name nothing in
            // content asks for, so it ships in the APK and is never drawn.
            List<string> orphans = new List<string>();
            string[] files = Directory.GetFiles(portraits, "*.png");
            for (int i = 0; i < files.Length; i++)
            {
                string stem = Path.GetFileNameWithoutExtension(files[i]);
                bool claimed = false;
                for (int h = 0; h < db.Heroes.Count && !claimed; h++)
                    claimed = db.Heroes[h].Visual.Portrait == stem;
                for (int e = 0; e < db.Enemies.Count && !claimed; e++)
                    claimed = db.Enemies[e].Visual.Portrait == stem;
                if (!claimed) orphans.Add(stem);
            }
            for (int i = 0; i < orphans.Count; i++)
                Line("  ORPHAN: Sprites/Portraits/" + orphans[i] + ".png is declared by no unit");
            Check(orphans.Count == 0,
                  "no portrait file sits in the folder unclaimed by any unit");

            CheckThePortraitDetectorActuallyFires(portraits);
        }

        private static void ClassifyPortrait(UnitDef def, string portraits, List<string> withBadge,
                                             List<string> withoutBadge, List<string> broken)
        {
            string portrait = def.Visual.Portrait;
            if (string.IsNullOrEmpty(portrait)) { withoutBadge.Add(def.Id); return; }
            if (File.Exists(Path.Combine(portraits, portrait + ".png"))) { withBadge.Add(def.Id); return; }

            broken.Add(def.Name + " (" + def.Id + ") declares portrait \"" + portrait
                       + "\" but Sprites/Portraits/" + portrait + ".png does not exist");
        }

        /// <summary>
        /// A DELIBERATE BROKEN UNIT, so the check above is known to be capable of failing - the
        /// same argument CheckTheBrokenDetectorActuallyFires makes for the sprite check, and worth
        /// making twice, because a portrait check that reports clean on a fully delivered roster
        /// is exactly the one nobody would notice had stopped working.
        ///
        /// Both directions are asserted: a declared-and-absent badge is reported, and an
        /// undeclared unit with the same absent file is silent. That pair is what proves the two
        /// are told apart by the DECLARATION rather than by the failed load they share.
        /// </summary>
        private static void CheckThePortraitDetectorActuallyFires(string portraits)
        {
            HeroDef ghost = new HeroDef();
            ghost.Id = "harness_missing_portrait_probe";
            ghost.Name = "Harness Probe";
            ghost.Visual.Portrait = "a_badge_that_does_not_exist_on_purpose";

            List<string> withBadge = new List<string>();
            List<string> withoutBadge = new List<string>();
            List<string> broken = new List<string>();
            ClassifyPortrait(ghost, portraits, withBadge, withoutBadge, broken);

            Check(broken.Count == 1 && withBadge.Count == 0 && withoutBadge.Count == 0,
                  "a hero pointed at a nonexistent portrait IS reported broken (the detector fires)");
            Check(broken.Count == 1 && broken[0].Contains("a_badge_that_does_not_exist_on_purpose")
                  && broken[0].Contains("Harness Probe"),
                  "and the report names the hero and the path it looked in");

            ghost.Visual.Portrait = "";
            withBadge.Clear(); withoutBadge.Clear(); broken.Clear();
            ClassifyPortrait(ghost, portraits, withBadge, withoutBadge, broken);

            Check(withoutBadge.Count == 1 && broken.Count == 0,
                  "the SAME hero with no portrait declared is silent - the two cases are told apart"
                  + " by the declaration, not by the failed load");
        }

        /// <summary>Ids three to a line, so a 63-entry list stays readable in a log.</summary>
        private static void PrintIdColumns(List<string> ids)
        {
            ids.Sort(StringComparer.Ordinal);
            for (int i = 0; i < ids.Count; i += 3)
            {
                StringBuilder sb = new StringBuilder("    ");
                for (int k = i; k < i + 3 && k < ids.Count; k++) sb.Append(ids[k].PadRight(36));
                Line(sb.ToString().TrimEnd());
            }
        }

        /// <summary>The content in dir. eventsOverride, when given, stands in for events.json's
        /// text, so a check can load the game under a retuned event without writing the file.</summary>
        private static ContentDatabase LoadContent(string dir, string eventsOverride = null, string campaignOverride = null, string relicsOverride = null)
        {
            try
            {
                string heroes = File.ReadAllText(Path.Combine(dir, "heroes.json"));
                string enemies = File.ReadAllText(Path.Combine(dir, "enemies.json"));
                string campaign = campaignOverride ?? File.ReadAllText(Path.Combine(dir, "campaign.json"));
                string balance = File.ReadAllText(Path.Combine(dir, "balance.json"));
                string relicsPath = Path.Combine(dir, "relics.json");
                string relics = relicsOverride ?? (File.Exists(relicsPath) ? File.ReadAllText(relicsPath) : null);
                string eventsPath = Path.Combine(dir, "events.json");
                string events = eventsOverride ?? (File.Exists(eventsPath) ? File.ReadAllText(eventsPath) : null);
                string armorPath = Path.Combine(dir, "armor.json");
                string armor = File.Exists(armorPath) ? File.ReadAllText(armorPath) : null;
                string conditionsPath = Path.Combine(dir, "floor-conditions.json");
                string conditions = File.Exists(conditionsPath) ? File.ReadAllText(conditionsPath) : null;
                ContentDatabase db = ContentDatabase.Load(heroes, enemies, campaign, balance, relics, events, armor, conditions);
                string pathPath = Path.Combine(dir, "guild-path.json");
                db.LoadGuildPath(File.Exists(pathPath) ? File.ReadAllText(pathPath) : null);
                string techPath = Path.Combine(dir, "guild-tech.json");
                db.LoadGuildTech(File.Exists(techPath) ? File.ReadAllText(techPath) : null);
                string onboardingPath = Path.Combine(dir, "onboarding.json");
                db.LoadOnboarding(File.Exists(onboardingPath) ? File.ReadAllText(onboardingPath) : null);
                string ordersPath = Path.Combine(dir, "orders.json");
                db.LoadOrders(File.Exists(ordersPath) ? File.ReadAllText(ordersPath) : null);
                string sinksPath = Path.Combine(dir, "sinks.json");
                db.LoadSinks(File.Exists(sinksPath) ? File.ReadAllText(sinksPath) : null);
                string quartermasterPath = Path.Combine(dir, "quartermaster.json");
                db.LoadQuartermaster(File.Exists(quartermasterPath) ? File.ReadAllText(quartermasterPath) : null);
                string relicShopPath = Path.Combine(dir, "relic-shop.json");
                db.LoadRelicShop(File.Exists(relicShopPath) ? File.ReadAllText(relicShopPath) : null);
                string wayfarersPath = Path.Combine(dir, "wayfarers-road.json");
                db.LoadWayfarersRoad(File.Exists(wayfarersPath) ? File.ReadAllText(wayfarersPath) : null);
                return db;
            }
            catch (Exception ex)
            {
                _failures++;
                Line("  [FAIL] could not read content: " + ex.Message);
                return null;
            }
        }

        // ---------------------------------------------------------------- checks

        private static void CheckContent(ContentDatabase db)
        {
            Line("CONTENT");
            for (int i = 0; i < db.Warnings.Count; i++) Line("  warning: " + db.Warnings[i]);
            Check(db.Warnings.Count == 0, "content parses with no warnings");
            Check(db.Heroes.Count >= db.Balance.MaxTeamSize,
                  "at least MaxTeamSize heroes loaded (" + db.Heroes.Count + " >= " + db.Balance.MaxTeamSize + ")");
            Check(db.Enemies.Count >= 6, "enemies loaded (got " + db.Enemies.Count + ")");
            Check(db.AllStages.Count >= 10, "campaign stages loaded (got " + db.AllStages.Count + ")");
            Check(db.StartingHeroes.Count == 3, "3 starting heroes (got " + db.StartingHeroes.Count + ")");

            // LEFT FAILING ON PURPOSE while the roster swap is half done, and failing WIDER now
            // than it did.
            //
            // Deleting the six placeholders took the roster's only Bulwark, Warden and Stalker with
            // them. Widening HeroRole from seven members to the ten the incoming roster is authored
            // against then added Vanguard, Binder, Marksman and Tinkerer, and re-roled two of the
            // five survivors onto two of those, so the gap is five roles of ten rather than three
            // of seven. Both halves are genuine content gaps rather than artefacts of this check,
            // and the number getting worse is the honest reading of a taxonomy that grew while the
            // roster did not. It goes green when a hero exists for every role, which is the import
            // and nothing short of it.
            List<string> missingRoles = new List<string>();
            foreach (HeroRole role in Enum.GetValues(typeof(HeroRole)))
            {
                bool found = false;
                for (int i = 0; i < db.Heroes.Count; i++) if (db.Heroes[i].Role == role) found = true;
                if (!found) missingRoles.Add(role.ToString());
            }
            Check(missingRoles.Count == 0,
                  "every combat role has a hero"
                  + (missingRoles.Count == 0 ? "" : " (" + missingRoles.Count + " of "
                     + Enum.GetValues(typeof(HeroRole)).Length + ") - EMPTY: "
                     + string.Join(", ", missingRoles.ToArray())
                     + ". Expected while the roster swap is half done: the six deleted placeholders held"
                     + " three of these, and the other two are roles the widened taxonomy added that no"
                     + " current hero fills. The import that replaces them closes this."));

            // ---- per-tier reporting ----
            int[] tierCounts = new int[6];
            for (int i = 0; i < db.Heroes.Count; i++)
            {
                int s = db.Heroes[i].Stars;
                if (s >= 1 && s <= 5) tierCounts[s]++;
            }
            Line("  roster shape (" + db.Heroes.Count + " heroes):");
            for (int t = 1; t <= 5; t++)
                Line("    " + t + "-star: " + tierCounts[t]);

            Line("  per aspect:");
            foreach (Aspect asp in Enum.GetValues(typeof(Aspect)))
            {
                int count = 0;
                for (int i = 0; i < db.Heroes.Count; i++)
                    if (db.Heroes[i].Aspect == asp) count++;
                Line("    " + asp + ": " + count);
            }

            Line("  per role:");
            foreach (HeroRole role in Enum.GetValues(typeof(HeroRole)))
            {
                int count = 0;
                for (int i = 0; i < db.Heroes.Count; i++)
                    if (db.Heroes[i].Role == role) count++;
                Line("    " + role + ": " + count);
            }

            // ---- star contract: basicAttack and active ----
            // BasicAttack is always present (engine creates DefaultBasicAttack if null).
            // Active is required at 3 stars and above, must be absent below 3.
            bool kitOk = true;
            for (int i = 0; i < db.Heroes.Count; i++)
            {
                HeroDef h = db.Heroes[i];
                if (h.BasicAttack == null)
                {
                    kitOk = false;
                    Line("  " + h.Id + " (star " + h.Stars + "): missing basic attack");
                }
                if (h.Stars >= 3 && h.Active == null)
                {
                    kitOk = false;
                    Line("  " + h.Id + " (star " + h.Stars + "): star " + h.Stars + " requires an active");
                }
                if (h.Stars < 3 && h.Active != null)
                {
                    kitOk = false;
                    Line("  " + h.Id + " (star " + h.Stars + "): star " + h.Stars + " should not have an active");
                }
            }
            Check(kitOk, "every hero's active matches its star contract (active at 3+, absent below)");

            // ---- star contract: passive ----
            // Passive (= passive1 in the import format) is required at 2 stars and above.
            // passive2 and talents exist in the import schema but not in the engine model
            // (HeroDef has a Passives list), so they cannot be checked here.
            // Reported rather than capped â€” the old "at most two" cap was written for 11 heroes.
            int passiveless = 0;
            int passiveViolations = 0;
            for (int i = 0; i < db.Heroes.Count; i++)
            {
                HeroDef h = db.Heroes[i];
                if (h.Passives.Count == 0)
                {
                    passiveless++;
                    if (h.Stars >= 2)
                    {
                        passiveViolations++;
                        Line("  " + h.Id + " (star " + h.Stars + "): star " + h.Stars + " requires a passive");
                    }
                }
            }
            Line("  " + passiveless + " hero(es) have no passive"
                 + (passiveViolations > 0
                    ? " (" + passiveViolations + " violate the star contract: passive required at 2+)"
                    : ""));

            // ---- stat-range sanity bands (94-hero import) ----
            bool rangeOk = true;
            for (int i = 0; i < db.Heroes.Count; i++)
            {
                HeroDef h = db.Heroes[i];
                if (h.BaseHp < 500 || h.BaseHp > 3000)
                { rangeOk = false; Line("  " + h.Id + " hp " + h.BaseHp + " outside [500, 3000]"); }
                if (h.BaseAttack < 50 || h.BaseAttack > 400)
                { rangeOk = false; Line("  " + h.Id + " attack " + h.BaseAttack + " outside [50, 400]"); }
                if (h.BaseDefense < 20 || h.BaseDefense > 150)
                { rangeOk = false; Line("  " + h.Id + " defense " + h.BaseDefense + " outside [20, 150]"); }
                if (h.BaseSpeed < 50 || h.BaseSpeed > 200)
                { rangeOk = false; Line("  " + h.Id + " speed " + h.BaseSpeed + " outside [50, 200]"); }
                if (h.CritChance < 0f || h.CritChance > 0.5f)
                { rangeOk = false; Line("  " + h.Id + " critChance " + h.CritChance + " outside [0, 0.5]"); }
                if (h.CritDamage < 1f || h.CritDamage > 3f)
                { rangeOk = false; Line("  " + h.Id + " critDamage " + h.CritDamage + " outside [1, 3]"); }
            }
            Check(rangeOk, "every hero's base stats fall within sanity bands");
            Line("");
        }


        /// <summary>
        /// HeroRole's ordinals, and the one claim that made widening it safe.
        ///
        /// The enum went from seven members to ten to match the taxonomy the incoming roster is
        /// authored against. Six of the seven survive at their original ordinals and four are
        /// appended, which is the same append-only discipline StatusKind, TargetMode, EffectKind
        /// and PassiveTrigger are each pinned to.
        ///
        /// RANGER WAS REMOVED, which none of those enums has ever done, and the pin below is what
        /// pays for it. Two facts make it safe and both are asserted rather than argued: it was the
        /// LAST member, so nothing declared before it renumbers, and a role reaches no persisted
        /// record, so no stored byte anywhere means "6, Ranger" and would now read "6, Vanguard".
        /// The second fact is the load-bearing one, and it is checked by serialising a real profile
        /// and looking for a role in the output rather than by reading SaveSerializer and trusting
        /// the reading. The day a role does get written to a save, this fails and the reuse of
        /// ordinal 6 has to be answered properly.
        /// </summary>
        private static void CheckHeroRoleOrdinals(ContentDatabase db)
        {
            Line("HERO ROLES");

            Check((int)HeroRole.Bulwark == 0 && (int)HeroRole.Striker == 1 && (int)HeroRole.Breaker == 2
                  && (int)HeroRole.Mender == 3 && (int)HeroRole.Warden == 4 && (int)HeroRole.Stalker == 5,
                  "the six roles that survived the widening keep their ordinals (0-5)");
            Check((int)HeroRole.Vanguard == 6 && (int)HeroRole.Binder == 7
                  && (int)HeroRole.Marksman == 8 && (int)HeroRole.Tinkerer == 9,
                  "the four new roles are appended at 6-9, not inserted");
            Check(Enum.GetValues(typeof(HeroRole)).Length == 10,
                  "HeroRole has exactly the ten members the incoming roster uses (got "
                  + Enum.GetValues(typeof(HeroRole)).Length + ")");

            // The precondition for reusing ordinal 6. A profile is serialised and every role name
            // is looked for in the text - names rather than numbers, because that is the shape a
            // role would take if anyone ever wrote one, and a bare 6 is unsearchable.
            PlayerProfile profile = GameSession.CreateNewProfile(db, 0);
            string saved = SaveSerializer.Serialize(profile);
            List<string> leaked = new List<string>();
            foreach (HeroRole role in Enum.GetValues(typeof(HeroRole)))
                if (saved.IndexOf("\"" + role + "\"", StringComparison.OrdinalIgnoreCase) >= 0)
                    leaked.Add(role.ToString());
            Check(leaked.Count == 0,
                  "no role reaches the save format, which is what makes removing the last member and"
                  + " reusing its ordinal safe (" + (leaked.Count == 0 ? "none found"
                     : "FOUND: " + string.Join(", ", leaked.ToArray())) + ")");

            // EnumUtil.Parse falls back to Striker rather than throwing, so a role this enum does
            // not know is not a load error - it is a hero that quietly becomes a Striker and a
            // roster that looks fine. Read the authored strings back out of the JSON and check each
            // one survives the trip, because the parsed def can no longer tell you it was wrong.
            List<KeyValuePair<string, string>> authoredRoles = AuthoredHeroRoles();
            List<string> unknown = new List<string>();
            int matched = 0;
            for (int i = 0; i < authoredRoles.Count; i++)
            {
                HeroDef def = db.GetHero(authoredRoles[i].Key);
                if (def == null) continue;
                matched++;
                if (!string.Equals(def.Role.ToString(), authoredRoles[i].Value, StringComparison.OrdinalIgnoreCase))
                    unknown.Add(authoredRoles[i].Key + " authors \"" + authoredRoles[i].Value
                                + "\", parsed as " + def.Role);
            }
            // Counted, because this check failed silently once already: an earlier version paired
            // each role with the wrong id after the first hero, found nothing to compare, and
            // passed. A guard against a silent fallback that can itself go quiet is worth nothing,
            // so the sample size is asserted before the verdict is.
            Check(matched == db.Heroes.Count,
                  "the authored-role scan actually read every hero (" + matched + " of "
                  + db.Heroes.Count + ") - a scan that pairs nothing passes for the wrong reason");
            Check(unknown.Count == 0,
                  "every role heroes.json authors round-trips through HeroRole instead of silently"
                  + " falling back to Striker" + (unknown.Count == 0 ? ""
                     : " - " + string.Join(" | ", unknown.ToArray())));

            // Content, reported rather than asserted: which of the ten are filled today. The
            // coverage check in CONTENT above is the one that fails on a gap; this prints the shape
            // so the failure there reads as a roster fact rather than a bare list.
            Dictionary<HeroRole, int> filled = new Dictionary<HeroRole, int>();
            foreach (HeroRole role in Enum.GetValues(typeof(HeroRole))) filled[role] = 0;
            for (int i = 0; i < db.Heroes.Count; i++) filled[db.Heroes[i].Role]++;
            List<string> shape = new List<string>();
            foreach (HeroRole role in Enum.GetValues(typeof(HeroRole)))
                shape.Add(role + " " + filled[role]);
            Line("  [note] roster by role: " + string.Join(", ", shape.ToArray()));

            Line("");
        }

        /// <summary>
        /// The `role` string each hero authors, read straight out of heroes.json rather than off
        /// the parsed def. The parsed def cannot answer "what did the file say" once EnumUtil.Parse
        /// has replaced an unknown value with the fallback, which is the whole point of reading it
        /// twice. Deliberately a flat scan rather than a JSON parse: it needs the raw text, and the
        /// harness already proves the file parses everywhere else.
        /// </summary>
        private static List<KeyValuePair<string, string>> AuthoredHeroRoles()
        {
            List<KeyValuePair<string, string>> pairs = new List<KeyValuePair<string, string>>();
            string path = Path.Combine(FindContentDir(), "heroes.json");
            if (!File.Exists(path)) return pairs;

            // The most recent id line wins, rather than the first unconsumed one. A hero block
            // opens with its own id and reaches "role" four lines later, before any ability block
            // introduces an id of its own, so "nearest id above" is always the hero. The first
            // version of this held the first id until a role consumed it, which meant every hero
            // after the first paired a role with an ABILITY id, resolved to no HeroDef, and was
            // skipped - the scan checked exactly one hero and reported nothing wrong.
            string lastId = null;
            foreach (string raw in File.ReadAllLines(path))
            {
                string line = raw.Trim();
                string got = FieldValue(line, "id");
                if (got != null) { lastId = got; continue; }
                string role = FieldValue(line, "role");
                if (role != null && lastId != null) pairs.Add(new KeyValuePair<string, string>(lastId, role));
            }
            return pairs;
        }

        /// <summary>The value of a `"name": "value",` pair on one line, or null if this line is not
        /// that field. Matches the whole key so `"id"` does not also match `"defId"`.</summary>
        private static string FieldValue(string line, string field)
        {
            string key = "\"" + field + "\":";
            int at = line.IndexOf(key, StringComparison.Ordinal);
            if (at != 0) return null;
            int open = line.IndexOf('"', key.Length);
            if (open < 0) return null;
            int close = line.IndexOf('"', open + 1);
            if (close < 0) return null;
            return line.Substring(open + 1, close - open - 1);
        }


        // ---------------------------------------------------------------- tier five

        /// <summary>
        /// The six mechanics of the tier-five pass, each proved to fire and each guarded against
        /// shipped content reaching it.
        ///
        /// The guards come FIRST and are the half that matters. Every check below builds synthetic
        /// content to make a mechanic happen, which proves the code works and proves nothing about
        /// whether the game changed; the claim that no existing battle moved rests on the content
        /// guards plus the 678-fingerprint sweep, not on any arena.
        /// </summary>
        private static void CheckTierFiveMechanics(ContentDatabase live)
        {
            Line("TIER FIVE (turn progress, round ordinals, concealment, per-target limits, records, defeat)");

            CheckNoShippedContentReachesTierFive(live);
            CheckTierFiveOrdinals();
            CheckTurnProgressQuantity();
            CheckPerRoundStatusUses();
            CheckConcealment();
            CheckPerTargetLimits();
            CheckNonNumericLedger();
            CheckDefeatDispatch();

            Line("");
        }

        /// <summary>
        /// SIX CONFIRMATIONS IN ONE SWEEP: every mechanic this pass added is reached by shipped
        /// content, and each line names the abilities that reach it.
        ///
        /// All six opened as dormancy tripwires - "no unit in shipped content authors this" - and
        /// all six have now fired, which is what authoring the roster means. They are flipped
        /// rather than deleted: see <see cref="Used"/> for why a retired tripwire is still the only
        /// guard its mechanic has.
        ///
        /// Still one walk over every ability of every hero and enemy, asking six questions rather
        /// than six walks asking one each, because the thing being asserted is a single property of
        /// the content and splitting it into six would let five pass while the sixth quietly
        /// stopped being checked.
        /// </summary>
        private static void CheckNoShippedContentReachesTierFive(ContentDatabase db)
        {
            List<UnitDef> units = new List<UnitDef>();
            for (int i = 0; i < db.Heroes.Count; i++) units.Add(db.Heroes[i]);
            for (int i = 0; i < db.Enemies.Count; i++) units.Add(db.Enemies[i]);

            List<string> progress = new List<string>(), uses = new List<string>(), conceal = new List<string>();
            List<string> perTarget = new List<string>(), records = new List<string>(), defeat = new List<string>();

            for (int u = 0; u < units.Count; u++)
            {
                UnitDef def = units[u];
                for (int p = 0; p < def.Passives.Count; p++)
                {
                    PassiveDef passive = def.Passives[p];
                    if (passive == null) continue;
                    if (passive.PerTargetLimit > 0) perTarget.Add(def.Id + "/" + passive.Name);
                    if (passive.Trigger == PassiveTrigger.OnEnemyDefeated
                        || passive.Trigger == PassiveTrigger.OnAllyDefeated
                        || passive.Trigger == PassiveTrigger.OnTurnDebtRepaid)
                        defeat.Add(def.Id + "/" + passive.Name + " (" + passive.Trigger + ")");
                }

                List<AbilityDef> abilities = AllAbilitiesOf(def);
                for (int a = 0; a < abilities.Count; a++)
                {
                    for (int e = 0; e < abilities[a].Effects.Count; e++)
                    {
                        EffectDef eff = abilities[a].Effects[e];
                        string where = def.Id + "/" + abilities[a].Name;

                        if (eff.Condition == EffectCondition.TurnProgressAbove
                            || eff.Condition == EffectCondition.TurnProgressBelow
                            || eff.Condition == EffectCondition.CasterActsBeforeSubject
                            || eff.ShiftBanksAs != StatusKind.None
                            || eff.Status == StatusKind.TurnDebt)
                            progress.Add(where);

                        if (eff.UsesPerRound > 0 || eff.Condition == EffectCondition.StatusUseAvailable)
                            uses.Add(where);

                        if (eff.Status == StatusKind.Stealth || eff.ConditionStatus == StatusKind.Stealth)
                            conceal.Add(where);

                        if (eff.Kind == EffectKind.RecordFact || eff.Record != RecordKind.None
                            || eff.Condition == EffectCondition.StoredStatusMatches
                            || eff.Condition == EffectCondition.StoredActionMatches
                            || eff.Condition == EffectCondition.StoredRoleMatches
                            || eff.Condition == EffectCondition.SubjectAboveStoredMin)
                            records.Add(where);

                        if (eff.Target == TargetMode.DefeatedUnit
                            || eff.SecondaryTarget == TargetMode.DefeatedUnit
                            || eff.ConditionOn == ConditionSubject.Defeated)
                            defeat.Add(where);
                    }
                }
            }

            Check(progress.Count > 0, "no shipped content reads turn progress as a quantity or banks a Turn Debt"
                  + Detail(progress));
            Check(uses.Count > 0, "shipped content carries a per-round use budget" + Used(uses));
            Check(conceal.Count > 0, "shipped content applies or reads Stealth, so concealment is reachable"
                  + Used(conceal));
            Check(perTarget.Count > 0, "no shipped passive sets a per-target limit" + Detail(perTarget));
            Check(records.Count > 0, "shipped content writes or reads a non-numeric record" + Used(records));
            Check(defeat.Count > 0, "no shipped content listens for a defeat or names the defeated unit"
                  + Detail(defeat));
        }

        private static string Detail(List<string> offenders)
        {
            return offenders.Count == 0 ? "" : " - FOUND: " + string.Join(", ", offenders.ToArray());
        }

        /// <summary>
        /// THE CONFIRMATION COUNTERPART OF <see cref="Detail"/>, and the reason a retired dormancy
        /// tripwire is flipped rather than deleted.
        ///
        /// A dormancy tripwire says "nothing shipped reaches this yet" and goes red the day
        /// something does. That day arrives exactly once per mechanic, and deleting the line at
        /// that point throws away the only guard the mechanic will ever have: nothing would then
        /// notice the usage being authored away again, and the engine path behind it would go quiet
        /// with no line anywhere saying so. Flipped, the same check asserts the opposite fact - the
        /// mechanic IS reached, by these named abilities - and goes red if that stops being true.
        ///
        /// "(none)" is deliberately what a broken confirmation prints. Check() shows one label for
        /// both verdicts, so the FAIL line has to carry its own evidence, and an empty list behind
        /// a claim of use is the whole finding stated in one word.
        /// </summary>
        private static string Used(List<string> users)
        {
            return users.Count == 0
                ? " - used by: (none)"
                : " - used by: " + string.Join(", ", users.ToArray());
        }

        /// <summary>
        /// Appends an ability's effects to a flat scan list while recording, in a parallel list,
        /// which "unit/ability" each one came from.
        ///
        /// The flat list is what the standing guards walk; the labels are what a CONFIRMATION needs
        /// and a dormancy tripwire never did. A tripwire that is passing has nothing to name, so
        /// every one of these scans used to flatten the effects and drop the owner on the floor.
        /// </summary>
        private static void AddWithNames(List<EffectDef> into, List<string> labels, string where,
                                         List<EffectDef> effects)
        {
            if (effects == null) return;
            for (int i = 0; i < effects.Count; i++) { into.Add(effects[i]); labels.Add(where); }
        }

        /// <summary>Basic, active and every passive of a unit, as one list.</summary>
        private static List<AbilityDef> AllAbilitiesOf(UnitDef def)
        {
            List<AbilityDef> list = new List<AbilityDef>();
            if (def.BasicAttack != null) list.Add(def.BasicAttack);
            if (def.Active != null) list.Add(def.Active);
            for (int p = 0; p < def.Passives.Count; p++)
            {
                if (def.Passives[p] == null) continue;
                AbilityDef wrapper = new AbilityDef();
                wrapper.Name = def.Passives[p].Name;
                wrapper.Effects = def.Passives[p].Effects;
                list.Add(wrapper);
            }
            return list;
        }

        /// <summary>
        /// The ordinal pins, extended to the five enums this pass appends to.
        ///
        /// Same standard every earlier pass held: `BattleEvent.Status` carries a StatusKind ordinal
        /// into the permanent record of every battle, so renumbering one rewrites what a past
        /// battle said with no simulation change at all. TargetMode, EffectKind, EffectCondition
        /// and PassiveTrigger are pinned for the weaker reason that content names them by string
        /// and an insertion would silently re-point every authored value.
        /// </summary>
        private static void CheckTierFiveOrdinals()
        {
            Check((int)StatusKind.Vulnerable == 36 && (int)StatusKind.TurnDebt == 37,
                  "StatusKind keeps its ordinals and TurnDebt is appended at " + (int)StatusKind.TurnDebt);
            Check((int)EffectKind.LedgerRelease == 15 && (int)EffectKind.RecordFact == 16,
                  "EffectKind keeps its ordinals and RecordFact is appended at " + (int)EffectKind.RecordFact);
            Check((int)TargetMode.EnemyWithMyMark == 20 && (int)TargetMode.DefeatedUnit == 21,
                  "TargetMode keeps its ordinals and DefeatedUnit is appended at " + (int)TargetMode.DefeatedUnit);
            Check((int)ConditionSubject.Target == 0 && (int)ConditionSubject.Caster == 1
                  && (int)ConditionSubject.Defeated == 2,
                  "ConditionSubject keeps Target and Caster and appends Defeated");
            Check((int)EffectCondition.AlreadyDamagedSubjectThisRound == 17
                  && (int)EffectCondition.TurnProgressAbove == 18
                  && (int)EffectCondition.StatusUseAvailable == 25,
                  "EffectCondition keeps its ordinals and the eight new members are appended at 18-25");
            Check((int)PassiveTrigger.OnAllyWouldDie == 19 && (int)PassiveTrigger.OnEnemyDefeated == 20
                  && (int)PassiveTrigger.OnTurnDebtRepaid == 22,
                  "PassiveTrigger keeps its ordinals and the three new triggers are appended at 20-22");
        }

        // =====================================================================
        // TIER SIX
        // =====================================================================

        private static void CheckTierSixMechanics(ContentDatabase live)
        {
            Line("TIER SIX (accuracy/miss, splash, guaranteed crit, buff suppression, interrupt, stat comparison, action-type history, extend, energy intercept)");

            CheckNoShippedContentReachesTierSix(live);
            CheckTierSixOrdinals();
            CheckAccuracyAndMiss();
            CheckSplash();
            CheckGuaranteedCrit();
            CheckBuffSuppression();
            CheckInterrupt();
            CheckCrossUnitStatComparison();
            CheckActionTypeHistory();
            CheckExtendStatus();
            CheckDisruptedIntercept();
            CheckMomentumBreaker();

            Line("");
        }

        /// <summary>
        /// FOURTEEN STANDING LINES OVER THE MECHANICS TIER SIX ADDS. One walk, fourteen questions,
        /// and each question is asked in whichever direction is currently true: a mechanic no
        /// shipped unit reaches is guarded as dormant, and one the roster has since authored is
        /// confirmed as used and names its users. Flipping rather than deleting is what keeps a
        /// mechanic from going quietly unreached again - see <see cref="Used"/>.
        /// </summary>
        private static void CheckNoShippedContentReachesTierSix(ContentDatabase db)
        {
            List<UnitDef> units = new List<UnitDef>();
            for (int i = 0; i < db.Heroes.Count; i++) units.Add(db.Heroes[i]);
            for (int i = 0; i < db.Enemies.Count; i++) units.Add(db.Enemies[i]);

            List<string> evasion = new List<string>(), accuracy = new List<string>();
            List<string> gcrit = new List<string>(), suppress = new List<string>();
            List<string> interrupt = new List<string>(), splash = new List<string>();
            List<string> statCmp = new List<string>(), actionHist = new List<string>();
            List<string> dodge = new List<string>(), extend = new List<string>();
            List<string> disrupted = new List<string>(), consumeDebt = new List<string>();
            List<string> thresholdTrig = new List<string>(), thresholdTarget = new List<string>();

            for (int u = 0; u < units.Count; u++)
            {
                UnitDef def = units[u];
                for (int p = 0; p < def.Passives.Count; p++)
                {
                    PassiveDef passive = def.Passives[p];
                    if (passive == null) continue;
                    if (passive.Trigger == PassiveTrigger.OnDodge)
                        dodge.Add(def.Id + "/" + passive.Name);
                    if (passive.Trigger == PassiveTrigger.OnEnemyEnergyThreshold)
                        thresholdTrig.Add(def.Id + "/" + passive.Name);
                }

                List<AbilityDef> abilities = AllAbilitiesOf(def);
                for (int a = 0; a < abilities.Count; a++)
                {
                    for (int e = 0; e < abilities[a].Effects.Count; e++)
                    {
                        EffectDef eff = abilities[a].Effects[e];
                        string where = def.Id + "/" + abilities[a].Name;

                        if (eff.Status == StatusKind.EvasionUp || eff.ConditionStatus == StatusKind.EvasionUp)
                            evasion.Add(where);
                        if (eff.Status == StatusKind.AccuracyDown || eff.ConditionStatus == StatusKind.AccuracyDown)
                            accuracy.Add(where);
                        if (eff.Status == StatusKind.GuaranteedCrit || eff.ConditionStatus == StatusKind.GuaranteedCrit)
                            gcrit.Add(where);
                        if (eff.Status == StatusKind.BuffSuppression || eff.ConditionStatus == StatusKind.BuffSuppression)
                            suppress.Add(where);
                        if (eff.Kind == EffectKind.Interrupt)
                            interrupt.Add(where);
                        if (eff.Kind == EffectKind.ExtendStatus)
                            extend.Add(where);
                        if (eff.Kind == EffectKind.ConsumeTurnDebt)
                            consumeDebt.Add(where);
                        if (eff.Splash)
                            splash.Add(where);
                        if (eff.Status == StatusKind.Disrupted || eff.ConditionStatus == StatusKind.Disrupted)
                            disrupted.Add(where);
                        if (eff.Target == TargetMode.ThresholdUnit || eff.SecondaryTarget == TargetMode.ThresholdUnit)
                            thresholdTarget.Add(where);

                        if (eff.Condition == EffectCondition.CasterStatAboveTarget
                            || eff.Condition == EffectCondition.CasterStatBelowTarget)
                            statCmp.Add(where);
                        if (eff.Condition == EffectCondition.SubjectLastActionWasBasic
                            || eff.Condition == EffectCondition.SubjectLastActionWasActive
                            || eff.Condition == EffectCondition.SubjectChangedActionType
                            || eff.Condition == EffectCondition.SubjectRepeatedActionType)
                            actionHist.Add(where);
                    }
                }
            }

            Check(evasion.Count == 0, "no shipped content applies or reads EvasionUp" + Detail(evasion));
            // FLIPPED by the first 3-star batch. Adric's Mapcase Bash is the first shipped content
            // to apply AccuracyDown, so the miss check has a real occupant and the tripwire has
            // fired once. It is now the opposite claim, and goes red the day Lost Route stops
            // being an accuracy clause. See Used() for why that is not a deletion.
            Check(accuracy.Count > 0, "shipped content applies or reads AccuracyDown" + Used(accuracy));
            // FLIPPED by the third 4-star batch. Maera's Watch the Water is the first shipped
            // content to apply GuaranteedCrit, so the tripwire has fired once and is now the
            // opposite claim - the mechanic IS reached, by this named passive - and goes red the
            // day that stops being true. See Used() for why that is not a deletion.
            Check(gcrit.Count > 0, "shipped content applies or reads GuaranteedCrit" + Used(gcrit));
            Check(suppress.Count > 0, "no shipped content applies or reads BuffSuppression" + Detail(suppress));
            Check(interrupt.Count == 0, "no shipped content uses Interrupt" + Detail(interrupt));
            // FLIPPED by the first 3-star batch, and by two kits rather than one: Aster's
            // Shatterproof spreads Fracture into the bodies beside its target and Cal's Ricochet
            // Mark and Corner Shot carry damage into them.
            Check(splash.Count > 0, "shipped content marks an effect Splash" + Used(splash));
            Check(statCmp.Count > 0, "shipped content compares stats across units" + Used(statCmp));
            Check(actionHist.Count > 0, "no shipped content reads action-type history" + Detail(actionHist));
            // FLIPPED by the first 3-star batch. Adric's No Return Mark is the first shipped
            // passive to listen on a miss, and it is the other half of the AccuracyDown line
            // above: the status that creates misses and the passive that answers one landed in
            // the same kit, which is why both turn over together.
            Check(dodge.Count > 0, "a shipped passive triggers on OnDodge" + Used(dodge));
            Check(extend.Count > 0, "no shipped content uses ExtendStatus" + Detail(extend));
            Check(disrupted.Count > 0, "shipped content applies or reads Disrupted" + Used(disrupted));
            Check(consumeDebt.Count > 0, "no shipped content uses ConsumeTurnDebt" + Detail(consumeDebt));
            Check(thresholdTrig.Count > 0, "no shipped passive triggers on OnEnemyEnergyThreshold" + Detail(thresholdTrig));
            Check(thresholdTarget.Count > 0, "no shipped content targets ThresholdUnit" + Detail(thresholdTarget));
        }

        private static void CheckTierSixOrdinals()
        {
            Check((int)StatusKind.EvasionUp == 38 && (int)StatusKind.AccuracyDown == 39
                  && (int)StatusKind.GuaranteedCrit == 40 && (int)StatusKind.BuffSuppression == 41
                  && (int)StatusKind.Disrupted == 42,
                  "StatusKind tier-six members keep ordinals 38-42 (got "
                  + (int)StatusKind.EvasionUp + ", " + (int)StatusKind.AccuracyDown + ", "
                  + (int)StatusKind.GuaranteedCrit + ", " + (int)StatusKind.BuffSuppression
                  + ", " + (int)StatusKind.Disrupted + ")");
            Check((int)EffectKind.Interrupt == 17 && (int)EffectKind.ExtendStatus == 18
                  && (int)EffectKind.ConsumeTurnDebt == 19,
                  "EffectKind tier-six members are appended at 17-19 (got "
                  + (int)EffectKind.Interrupt + ", " + (int)EffectKind.ExtendStatus
                  + ", " + (int)EffectKind.ConsumeTurnDebt + ")");
            Check((int)EffectCondition.CasterStatAboveTarget == 26
                  && (int)EffectCondition.SubjectRepeatedActionType == 31,
                  "EffectCondition tier-six members are appended at 26-31 (got "
                  + (int)EffectCondition.CasterStatAboveTarget + ".." + (int)EffectCondition.SubjectRepeatedActionType + ")");
            Check((int)PassiveTrigger.OnDodge == 23 && (int)PassiveTrigger.OnEnemyEnergyThreshold == 24,
                  "PassiveTrigger.OnDodge at 23, OnEnemyEnergyThreshold at 24 (got "
                  + (int)PassiveTrigger.OnDodge + ", " + (int)PassiveTrigger.OnEnemyEnergyThreshold + ")");
        }

        // ---- Accuracy / Miss ----

        private static void CheckAccuracyAndMiss()
        {
            BattleResult withEvasion = RunAccuracyArena(true);
            BattleResult without = RunAccuracyArena(false);
            if (withEvasion == null || without == null) { Check(false, "the accuracy arena builds"); return; }

            int hitsWith = CountEvents(withEvasion, BattleEventType.Damage);
            int hitsWithout = CountEvents(without, BattleEventType.Damage);
            Check(hitsWithout > 0, "the control lands damage (" + hitsWithout + ")");
            Check(hitsWith < hitsWithout,
                  "EvasionUp causes some attacks to miss (" + hitsWith + " vs " + hitsWithout + " hits)");
        }

        /// <summary>
        /// A hero with high EvasionUp attacked by an enemy. With evasion, fewer hits land.
        /// </summary>
        private static BattleResult RunAccuracyArena(bool giveEvasion)
        {
            string evasionEffect = giveEvasion
                ? @", { ""kind"": ""ApplyStatus"", ""target"": ""Self"", ""status"": ""EvasionUp"", ""magnitude"": 0.9, ""duration"": 99, ""chance"": 1 }"
                : "";
            string heroesJson = @"{
  ""heroes"": [
    { ""id"": ""t6_hero"", ""name"": ""Dodger"", ""aspect"": ""Ember"", ""role"": ""Striker"", ""startingHero"": true,
      ""hp"": 100000, ""attack"": 100, ""defense"": 0, ""speed"": 100, ""critChance"": 0, ""critDamage"": 1.5, ""startEnergy"": 0,
      ""basic"": { ""id"": ""t6_basic"", ""name"": ""Hit"",
        ""effects"": [ { ""kind"": ""Damage"", ""target"": ""FrontEnemy"", ""power"": 0.001 }" + evasionEffect + @" ] } }
  ]
}";
            string enemiesJson = @"{
  ""enemies"": [
    { ""id"": ""t6_enemy"", ""name"": ""Swinger"", ""aspect"": ""Ember"",
      ""hp"": 100000, ""attack"": 100, ""defense"": 0, ""speed"": 110, ""critChance"": 0, ""critDamage"": 1.5, ""startEnergy"": 0,
      ""basic"": { ""id"": ""t6e_basic"", ""name"": ""Swing"", ""effects"": [ { ""kind"": ""Damage"", ""target"": ""FrontEnemy"", ""power"": 0.001 } ] } }
  ]
}";
            string campaignJson = @"{
  ""chapters"": [ { ""id"": ""t6_acc_ch"", ""name"": ""Acc"", ""stages"": [
    { ""id"": ""t6_acc"", ""index"": 1, ""enemies"": [ { ""id"": ""t6_enemy"", ""level"": 1 } ] } ] } ]
}";
            string balanceJson = @"{
  ""defenseConstant"": 300, ""defensePerLevel"": 0, ""damageVariance"": 0, ""speedVariance"": 0,
  ""minDamage"": 1, ""maxRounds"": 10, ""energyMax"": 100, ""energyPerBasicAttack"": 0, ""energyOnDamaged"": 0, ""maxTeamSize"": 5
}";
            ContentDatabase db = LoadSyntheticContent(heroesJson, enemiesJson, campaignJson, balanceJson, "accuracy");
            if (db == null) return null;
            List<HeroInstance> team = new List<HeroInstance>();
            HeroDef h = db.GetHero("t6_hero");
            if (h != null) team.Add(MakeInstance(h, 1));
            return RunWith(db, db.GetStage("t6_acc"), 42, team);
        }

        // ---- Splash ----

        private static void CheckSplash()
        {
            BattleResult withSplash = RunSplashArena(true);
            BattleResult without = RunSplashArena(false);
            if (withSplash == null || without == null) { Check(false, "the splash arena builds"); return; }

            List<string> hitSplash = DamagedNames(withSplash);
            List<string> hitNoSplash = DamagedNames(without);
            Check(hitSplash.Count > hitNoSplash.Count,
                  "splash hits MORE distinct enemies than the same effect without splash ("
                  + hitSplash.Count + " vs " + hitNoSplash.Count + ")");
        }

