    { ""id"": ""t6_e0"", ""name"": ""E0"", ""aspect"": ""Ember"",
      ""hp"": 100000, ""attack"": 1, ""defense"": 0, ""speed"": 100, ""critChance"": 0, ""critDamage"": 1.5, ""startEnergy"": 0,
      ""basic"": { ""id"": ""t6e0_b"", ""name"": ""Tap"", ""effects"": [ { ""kind"": ""Damage"", ""target"": ""FrontEnemy"", ""power"": 0.001 } ] } },
