            ContentDatabase db = LoadSyntheticContent(heroesJson, enemiesJson, campaignJson, balanceJson, "momentum");
            if (db == null) return null;
            List<HeroInstance> team = new List<HeroInstance>();
            HeroDef h1 = db.GetHero("mb_debtor_hero");
