        /// <summary>Beneficial statuses removed by somebody other than their carrier. SourceId equal
        /// to TargetId is a natural duration expiry, which is not a removal by anyone.</summary>
        private static int CountBeneficialRemovals(BattleResult r)
        {
            int n = 0;
            for (int i = 0; i < r.Events.Count; i++)
            {
                BattleEvent e = r.Events[i];
                if (e.Type != BattleEventType.StatusExpired) continue;
                if (e.SourceId == e.TargetId) continue;
                if (!StatusInfo.IsHarmful(e.Status)) n++;
            }
            return n;
        }

        private static BattleResult RunWith(ContentDatabase db, StageDef stage, int seed, List<HeroInstance> team)
        {
            BattleRequest request = new BattleRequest();
            request.Content = db;
            request.Stage = stage;
            request.Seed = seed;
            request.Team = team;
            return CombatSimulation.Run(request);
        }

        /// <summary>
        /// A fabricated owned hero for a study. FULLY ASCENDED, because every talent slot has to be
        /// reachable on it: the ascension gate (DESIGN-TALENTS T6, HeroInstance.TalentSlotsUnlocked)
        /// means a tier-0 body can only run talent 1, and an instrument that could only read the
        /// first of three would be measuring the gate instead of the talent.
        ///
        /// It is also the honest tier for these bodies. balance.json caps a 5-star at level 9 at
        /// tier 0 and at 27 at tier 1, so the level-10, level-40 and level-60 subjects the studies
        /// fabricate are heroes no tier below the top could be. Nothing else in the fight reads the
        /// field - StatMath.ForHero builds the stat line from Level alone - so setting it moves no
        /// number and no fingerprint anywhere; it only makes the talent reachable.
        /// </summary>
        private static HeroInstance MakeInstance(HeroDef def, int level)
        {
            HeroInstance h = new HeroInstance();
            h.Uid = def.Id;
            h.DefId = def.Id;
            h.Level = level;
            h.Copies = 1;
            h.Ascension = HeroDef.MaxTalents - 1;
            h.Def = def;
            return h;
        }

        private static void CheckDeterminism(ContentDatabase db)
        {
            Line("DETERMINISM");
            GameSession session = new GameSession(db, GameSession.CreateNewProfile(db, 0));
            StageDef stage = db.AllStages[0];

            string a = BattleFingerprint(session, stage, 12345);
            string b = BattleFingerprint(session, stage, 12345);
            string c = BattleFingerprint(session, stage, 999);

            Check(a == b, "same seed produces an identical battle");
            Check(a != c, "different seeds produce different battles");

            BattleResult r = CombatSimulation.Run(session.BuildBattleRequest(Opening(stage), 12345));
            Check(r.Events.Count > 10, "battle produced an event stream (" + r.Events.Count + " events)");
            // Team size is no longer a fixed 3v3: unit count is deploys plus spawns, both capped
            // by MaxTeamSize. A fresh profile deploys its 3 starters against whatever stage 1 spawns.
            int expectedUnits = Math.Min(session.Profile.TeamHeroes().Count, db.Balance.MaxTeamSize)
                              + Math.Min(stage.Enemies.Count, db.Balance.MaxTeamSize);
            Check(r.Units.Count == expectedUnits, "battle built deploys + spawns = " + expectedUnits + " units (got " + r.Units.Count + ")");
            Check(r.Rounds >= 1 && r.Rounds <= db.Balance.MaxRounds, "battle finished within the round limit (" + r.Rounds + ")");
            Line("");
        }

        /// <summary>
        /// Effect Hit / Effect Resist, phase A only (DESIGN-BUILD-ORDER task 7): the stats exist and
        /// are wired into the ApplyStatus landing gate, but nothing in heroes.json or enemies.json
        /// authors a non-zero value yet, so every battle in the game must be provably unchanged.
        /// Two separate proofs, not one. The first is exhaustive rather than sampled: it calls
        /// CombatSimulation.ResolveLandingChance directly for every StatusKind and a spread of
        /// chance values with both stats at zero, and asserts the result is bit-for-bit the
        /// authored chance - this is the actual no-op guarantee DESIGN-COMBAT-STATS asks for, and
        /// it needs no battle to run at all. It also checks the exact boundary case that made the
        /// guarantee possible: Nyx's Hollowing is the one ApplyStatus in shipped content with no
        /// authored "chance", defaulting to 1.0, which is why DeterministicRng.Chance draws nothing
        /// for it today. The second proof fingerprints all campaign stages at several seeds each
        /// and confirms same-seed reproducibility still holds everywhere, not just stage 1-1
        /// (CheckDeterminism above only samples that one stage). This does not diff against a
        /// pre-patch baseline - nothing in this run environment could compile one to diff against -
        /// so it is a project-wide determinism regression guard, not independent proof of no
        /// behavioural change. The formula-level check above is that proof.
        /// </summary>
        private static void CheckEffectHitResistNoOp(ContentDatabase db)
        {
            Line("EFFECT HIT / EFFECT RESIST (phase A - zero default, must be a no-op)");

            bool bypassOk = true;
            StatusKind[] statuses = (StatusKind[])Enum.GetValues(typeof(StatusKind));
            float[] chances = { 0f, 0.05f, 0.35f, 0.6f, 0.7f, 0.85f, 0.9f, 1f };
            for (int s = 0; s < statuses.Length; s++)
            {
                for (int c = 0; c < chances.Length; c++)
                {
                    float landing = CombatSimulation.ResolveLandingChance(chances[c], statuses[s], 0f, 0f);
                    if (landing != chances[c])
                    {
                        bypassOk = false;
                        Line("  [FAIL] " + statuses[s] + " at chance " + Fmt(chances[c]) + " resolved to " + Fmt(landing)
                             + " instead of the authored value, with both stats at zero");
                    }
                }
            }
            Check(bypassOk, "the landing formula returns the authored chance unchanged, for every status, when both stats are zero");

            float hollowing = CombatSimulation.ResolveLandingChance(1f, StatusKind.DefenseDown, 0f, 0f);
            Check(hollowing == 1f, "Hollowing's unauthored 1.0 chance still resolves to exactly 1.0 - DeterministicRng.Chance still draws nothing for it");

            Check(db.AllStages.Count > 0, db.AllStages.Count + " stage(s) to fingerprint across all chapters");

            bool fingerprintsStable = true;
            List<string> stageLines = new List<string>();
            GameSession session = new GameSession(db, GameSession.CreateNewProfile(db, 0));
            for (int s = 0; s < db.AllStages.Count; s++)
            {
                StageDef stage = db.AllStages[s];
                for (int seed = 1; seed <= 3; seed++)
                {
                    int actualSeed = 3000000 + s * 13 + seed;
                    string a = BattleFingerprint(session, stage, actualSeed);
                    string b = BattleFingerprint(session, stage, actualSeed);
                    // THE 72 FINGERPRINTS, DUMPED ON REQUEST. EMBERFALL_DUMP_STAGE_FP=1 prints the
                    // whole event stream for each, which is what you want when a line HAS moved and
                    // the question is what moved in it. The short hash below is what gets pinned.
                    if (_dumpStageFingerprints) Line("  [fp] " + stage.DisplayCode + "|" + actualSeed + "|" + a);
                    stageLines.Add(stage.DisplayCode + "|" + actualSeed + "|" + StageFingerprintHash(a));
                    if (a != b)
                    {
                        fingerprintsStable = false;
                        Line("  [FAIL] " + stage.DisplayCode + " seed " + actualSeed + " did not reproduce its own fingerprint");
                    }
                }
            }
            Check(fingerprintsStable, "every one of the " + db.AllStages.Count + " stage(s) still produces a stable, reproducible fingerprint across sampled seeds");
            CheckStageFingerprintBaseline(stageLines);
            Line("");
        }

        private const string StageFingerprintBaselineFile = "stage-fingerprint-baseline.txt";

        /// <summary>FNV-1a over the whole event stream the fingerprint already spells out, so a
        /// pinned line is 16 characters rather than 40 kilobytes. The stream itself is still what
        /// EMBERFALL_DUMP_STAGE_FP prints - this only shortens what gets committed.</summary>
        private static string StageFingerprintHash(string fingerprint)
        {
            ulong hash = 14695981039346656037UL;
            for (int i = 0; i < fingerprint.Length; i++)
            {
                hash ^= fingerprint[i];
                hash *= 1099511628211UL;
            }
            return hash.ToString("x16");
        }

        /// <summary>
        /// THE 72 STAGE FINGERPRINTS, PINNED TO A FILE rather than to a recollection.
        ///
        /// Every engine pass in this project reports "72 of 72 unmoved", and until now producing
        /// that number meant dumping the stream on both sides of a change by hand - a procedure
        /// nobody else could repeat and nobody could audit. The file makes it a diff, and makes the
        /// opposite claim auditable too: the campaign-curve pass MOVED all 72, because it re-derived
        /// every stage's authored enemy levels, and the file says so stage by stage.
        ///
        /// A moved line is a content change in that stage's opening battle. It needs a stated
        /// reason in the commit that moves it, NOT a regenerate. Regenerate deliberately with
        /// EMBERFALL_REGEN_STAGE_FP=1.
        /// </summary>
        private static void CheckStageFingerprintBaseline(List<string> lines)
        {
            string dir = FindToolDir("DevHarness");
            string path = dir == null ? null : Path.Combine(dir, StageFingerprintBaselineFile);
            bool regen = !string.IsNullOrEmpty(Environment.GetEnvironmentVariable("EMBERFALL_REGEN_STAGE_FP"));
            if (path == null)
            {
                Line("  [note] Tools/DevHarness not found next to this binary, so the stage fingerprints"
                     + " could not be compared against their baseline.");
                return;
            }
            if (regen || !File.Exists(path))
            {
                WriteStageFingerprintBaseline(path, lines);
                Line("  [note] " + (regen ? "EMBERFALL_REGEN_STAGE_FP is set" : "no baseline existed")
                     + " - wrote " + lines.Count + " stage fingerprints to " + StageFingerprintBaselineFile
                     + ". A regenerate is a CLAIM that every moved line was intended.");
                return;
            }

            Dictionary<string, string> baseline = new Dictionary<string, string>();
            string[] raw = File.ReadAllLines(path);
            for (int i = 0; i < raw.Length; i++)
            {
                string t = raw[i].Trim();
                if (t.Length == 0 || t[0] == '#') continue;
                int cut = t.LastIndexOf('|');
                if (cut <= 0) continue;
                baseline[t.Substring(0, cut)] = t.Substring(cut + 1);
            }

            List<string> moved = new List<string>();
            List<string> added = new List<string>();
            Dictionary<string, bool> seen = new Dictionary<string, bool>();
            for (int i = 0; i < lines.Count; i++)
            {
                int cut = lines[i].LastIndexOf('|');
                string key = lines[i].Substring(0, cut);
                string hash = lines[i].Substring(cut + 1);
                seen[key] = true;
                string was;
                if (!baseline.TryGetValue(key, out was)) { added.Add(key); continue; }
                if (was != hash) moved.Add(key);
            }
            List<string> gone = new List<string>();
            foreach (KeyValuePair<string, string> kv in baseline)
                if (!seen.ContainsKey(kv.Key)) gone.Add(kv.Key);

            Check(moved.Count == 0,
                  moved.Count == 0
                    ? "all " + lines.Count + " stage fingerprints match " + StageFingerprintBaselineFile
                    : moved.Count + " of " + lines.Count + " stage fingerprints MOVED: "
                      + string.Join(", ", moved.ToArray()));
            Check(added.Count == 0,
                  added.Count == 0
                    ? "no stage fingerprint is missing from the baseline"
                    : added.Count + " stage fingerprint(s) are not in the baseline: "
                      + string.Join(", ", added.ToArray()));
            Check(gone.Count == 0,
                  gone.Count == 0
                    ? "no baseline entry has lost its stage"
                    : gone.Count + " baseline entr(ies) no longer resolve to a shipped stage: "
                      + string.Join(", ", gone.ToArray()));
        }

        private static void WriteStageFingerprintBaseline(string path, List<string> lines)
        {
            List<string> outp = new List<string>();
            outp.Add("# Emberfall stage fingerprint baseline.");
            outp.Add("#");
            outp.Add("# One line per shipped campaign stage per sampled seed:");
            outp.Add("#   <stage>|<seed>|<fnv1a-64 of the battle's whole event stream>.");
            outp.Add("# The battle is the stage's OPENING one, fought by a fresh profile's starting");
            outp.Add("# three, so a line moves when that stage's authored roster or levels move, or");
            outp.Add("# when the engine or a starter's kit changes under it.");
            outp.Add("#");
            outp.Add("# A MOVED LINE IS A CONTENT OR BEHAVIOUR CHANGE. It needs a stated reason in the");
            outp.Add("# commit that moves it. Regenerating to make a surprise go away is how a guard");
            outp.Add("# stops guarding.");
            outp.Add("#");
            outp.Add("# The whole event stream behind a hash:  EMBERFALL_DUMP_STAGE_FP=1");
            outp.Add("# Regenerate deliberately:               EMBERFALL_REGEN_STAGE_FP=1");
            for (int i = 0; i < lines.Count; i++) outp.Add(lines[i]);
            File.WriteAllLines(path, outp.ToArray());
        }

        /// <summary>
        /// Effect Hit / Effect Resist, phase B: the landing formula moves in the direction it
        /// claims to, and the authored content is shaped the way the design says. Pure arithmetic
        /// against ResolveLandingChance and the content database, mirroring CheckAspectDirection.
        /// No battle is simulated, so nothing here can be confounded by RNG or by team size.
        ///
        /// This is a direction check, deliberately not a balance check. It asserts that more
        /// Effect Hit lands more often and more Effect Resist lands less often; it asserts nothing
        /// about whether the authored numbers are correctly tuned, because they are not tuned at
        /// all yet. Task 14 is the retune.
        /// </summary>
        private static void CheckEffectHitResistDirection(ContentDatabase db)
        {
            Line("EFFECT HIT / EFFECT RESIST (phase B - direction and authored shape)");

            const StatusKind Harmful = StatusKind.Burn;
            const StatusKind Benign = StatusKind.AttackUp;

            // more Effect Hit lands more often, against an identical target
            bool hitMonotonic = true;
            float[] bases = { 0.35f, 0.6f, 0.7f, 0.85f };
            float[] hits = { 0f, 0.05f, 0.1f, 0.15f, 0.2f, 0.3f };
            for (int b = 0; b < bases.Length; b++)
            {
                for (int h = 1; h < hits.Length; h++)
                {
                    float lo = CombatSimulation.ResolveLandingChance(bases[b], Harmful, hits[h - 1], 0.1f);
                    float hi = CombatSimulation.ResolveLandingChance(bases[b], Harmful, hits[h], 0.1f);
                    if (hi <= lo)
                    {
                        hitMonotonic = false;
                        Line("  [FAIL] base " + Fmt(bases[b]) + ": Effect Hit " + Fmt(hits[h]) + " landed " + Fmt(hi)
                             + ", no better than " + Fmt(hits[h - 1]) + " at " + Fmt(lo));
                    }
                }
            }
            Check(hitMonotonic, "a higher Effect Hit source lands more often than a lower one against the same target");

            // more Effect Resist lands less often, from an identical source
            bool resistMonotonic = true;
            float[] resists = { 0f, 0.05f, 0.08f, 0.12f, 0.15f, 0.25f, 0.3f };
            for (int b = 0; b < bases.Length; b++)
            {
                for (int rr = 1; rr < resists.Length; rr++)
                {
                    float lo = CombatSimulation.ResolveLandingChance(bases[b], Harmful, 0.1f, resists[rr - 1]);
                    float hi = CombatSimulation.ResolveLandingChance(bases[b], Harmful, 0.1f, resists[rr]);
                    if (hi >= lo)
                    {
                        resistMonotonic = false;
                        Line("  [FAIL] base " + Fmt(bases[b]) + ": Effect Resist " + Fmt(resists[rr]) + " allowed " + Fmt(hi)
                             + ", no less than " + Fmt(resists[rr - 1]) + " at " + Fmt(lo));
                    }
                }
            }
            Check(resistMonotonic, "Effect Resist reduces how often the same source lands the same affliction");

            // additive on the authored base, not multiplicative, wherever the clamp is not involved
            float additive = CombatSimulation.ResolveLandingChance(0.6f, Harmful, 0.2f, 0.05f);
            Check(Math.Abs(additive - 0.75f) < 0.0001f,
                  "the formula is additive on the authored chance (0.6 + 0.2 - 0.05 resolved to " + Fmt(additive) + ")");

            // clamp, both ends
            float floored = CombatSimulation.ResolveLandingChance(0.35f, Harmful, 0f, 0.95f);
            Check(floored == 0.05f, "an overwhelming Effect Resist floors at 0.05 rather than going to zero (got " + Fmt(floored) + ")");
            float ceiled = CombatSimulation.ResolveLandingChance(0.9f, Harmful, 0.9f, 0f);
            Check(ceiled == 1f, "an overwhelming Effect Hit ceilings at exactly 1.0 (got " + Fmt(ceiled) + ")");

            // beneficial statuses are never contested, from either side
            bool benignUntouched = true;
            for (int b = 0; b < bases.Length; b++)
            {
                float v = CombatSimulation.ResolveLandingChance(bases[b], Benign, 0.3f, 0.3f);
                if (v != bases[b])
                {
                    benignUntouched = false;
                    Line("  [FAIL] beneficial status at base " + Fmt(bases[b]) + " resolved to " + Fmt(v));
                }
            }
            Check(benignUntouched, "beneficial statuses ignore both stats entirely and apply at their authored chance");

            // authored content: every unit has a value in a sane band, and Nyx is the specialist
            float bestHit = -1f, bestResist = -1f;
            string bestHitId = "", bestResistId = "";
            bool banded = true;
            List<UnitDef> all = new List<UnitDef>();
            for (int i = 0; i < db.Heroes.Count; i++) all.Add(db.Heroes[i]);
            for (int i = 0; i < db.Enemies.Count; i++) all.Add(db.Enemies[i]);
            for (int i = 0; i < all.Count; i++)
            {
                UnitDef u = all[i];
                if (u.EffectHit < 0f || u.EffectHit > 0.5f || u.EffectResist < 0f || u.EffectResist > 0.5f)
                {
                    banded = false;
                    Line("  [FAIL] " + u.Id + " has out-of-band effectHit " + Fmt(u.EffectHit) + " / effectResist " + Fmt(u.EffectResist));
                }
                if (u.EffectHit > bestHit) { bestHit = u.EffectHit; bestHitId = u.Id; }
                if (u.EffectResist > bestResist) { bestResist = u.EffectResist; bestResistId = u.Id; }
            }
            Check(banded, "every authored Effect Hit and Effect Resist sits inside a sane 0 to 0.5 band");

            // THIS USED TO NAME A HERO, AND CANNOT ANY MORE.
            //
            // It asserted that Nyx Serrow held the roster's highest Effect Hit, so that Hollowing
            // landing on everything was a stat doing its job rather than a field nobody filled in.
            // Nyx was deleted with the placeholder roster and the five heroes left have no Effect
            // Hit specialist at all - the highest hero value is 0.15, below four enemies. The
            // assertion is not re-pointed at whoever happens to be top, because "somebody is
            // highest" is true of any list and proves nothing. It is reported instead, loudly, and
            // the property it was guarding is restated below against content rather than a name.
            Line("  [note] roster's highest Effect Hit is " + bestHitId + " at " + Fmt(bestHit)
                 + ", highest Effect Resist is " + bestResistId + " at " + Fmt(bestResist)
                 + ". No HERO is the Effect Hit specialist any more - Nyx Serrow was, and she is"
                 + " deleted. The 94-hero import decides who takes that place.");

            // Known trap 4, restated against content instead of against one hero.
            //
            // The trap: an ApplyStatus with no authored "chance" defaults to 1.0, and
            // ResolveLandingChance then computes 1f + hit - resist. When hit and resist are equal
            // that evaluates to 0.99999994 in float, which fails DeterministicRng.Chance's >= 1f
            // short-circuit and silently turns a certainty into a draw.
            //
            // Effects marked BypassResist skip the resist formula entirely at runtime, so
            // CollectCertainHarmfulStatuses excludes them. The check guards the remaining effects
            // that go through ResolveLandingChance with an authored chance >= 1.0.
            List<string> certainHarmful = new List<string>();
            List<string> brokenCertainty = new List<string>();
            for (int i = 0; i < db.Heroes.Count; i++)
                CollectCertainHarmfulStatuses(db, db.Heroes[i], certainHarmful, brokenCertainty);
            for (int i = 0; i < db.Enemies.Count; i++)
                CollectCertainHarmfulStatuses(db, db.Enemies[i], certainHarmful, brokenCertainty);

            if (certainHarmful.Count == 0)
                Line("  [note] no harmful status in shipped content is authored at an implicit 1.0 chance,"
                     + " so Known trap 4 has nothing to bite on right now. This is a gap in coverage, not a"
                     + " guarantee - re-read it when the roster lands.");
            Check(brokenCertainty.Count == 0,
                  "every harmful status authored at an implicit 1.0 chance still resolves to exactly 1.0"
                  + " against every authored enemy (" + certainHarmful.Count + " such status(es): "
                  + (certainHarmful.Count == 0 ? "none" : string.Join(", ", certainHarmful.ToArray())) + ")"
                  + (brokenCertainty.Count == 0 ? "" : " - BROKEN: " + string.Join(" | ", brokenCertainty.ToArray())));

            Line("  Authored values are UNTUNED. Every win rate below moves because of them; task 14 is the retune.");
            Line("");
        }

        /// <summary>
        /// BypassResist: a per-effect flag that skips the Effect Resist formula entirely.
        /// Proven in a synthetic arena where the same Vulnerable application lands against a
        /// high-resist enemy with the flag and is resisted without it. Count-based.
        /// </summary>
        private static void CheckBypassResist()
        {
            Line("BYPASS RESIST");

            ContentDatabase arena = BuildBypassResistTestContent();
            if (arena == null) { Line(""); return; }

            // Battle 1: hero with bypassResist true â€” status must always land
            HeroDef bypassDef = arena.GetHero("br_bypass");
            List<HeroInstance> bypassTeam = new List<HeroInstance>();
            bypassTeam.Add(MakeInstance(bypassDef, 1));
            BattleResult r1 = RunWith(arena, arena.GetStage("br_arena"), 4242, bypassTeam);

            int applied1 = 0, resisted1 = 0;
            for (int i = 0; i < r1.Events.Count; i++)
            {
                if (r1.Events[i].Type == BattleEventType.StatusApplied && r1.Events[i].Status == StatusKind.Vulnerable)
                    applied1++;
                if (r1.Events[i].Type == BattleEventType.StatusResisted && r1.Events[i].Status == StatusKind.Vulnerable)
                    resisted1++;
            }

            // Battle 2: hero WITHOUT bypassResist â€” status must be resisted at least once
            HeroDef normalDef = arena.GetHero("br_normal");
            List<HeroInstance> normalTeam = new List<HeroInstance>();
            normalTeam.Add(MakeInstance(normalDef, 1));
            BattleResult r2 = RunWith(arena, arena.GetStage("br_arena"), 4242, normalTeam);

            int applied2 = 0, resisted2 = 0;
            for (int i = 0; i < r2.Events.Count; i++)
            {
                if (r2.Events[i].Type == BattleEventType.StatusApplied && r2.Events[i].Status == StatusKind.Vulnerable)
                    applied2++;
                if (r2.Events[i].Type == BattleEventType.StatusResisted && r2.Events[i].Status == StatusKind.Vulnerable)
                    resisted2++;
            }

            Check(applied1 > 0, "BypassResist Vulnerable lands against a high-resist enemy (" + applied1 + " applied)");
            Check(resisted1 == 0, "BypassResist Vulnerable is never resisted (" + resisted1 + " resisted)");
            Check(resisted2 > 0, "same Vulnerable WITHOUT BypassResist is resisted by the same enemy (" + resisted2 + " resisted)");

            Line("");
        }

