            List<HeroInstance> team = new List<HeroInstance>();
            team.Add(MakeInstance(db.GetHero("fb_conv_hero"), 1));
            BattleResult r = RunWith(db, db.GetStage("fbc_arena"), 8484, team);
            if (r == null) { Check(false, "heal convert arena ran"); return; }

