        // ---- synthetic arena: stack-threshold auto-trigger ----

        private static void CheckStackThresholdTrigger()
        {
            // Hero gains 1 Resolve per basic attack (MaxStacks=9). A passive with
            // OnStackThreshold at 3 stacks fires a Damage effect when 3 stacks accumulate.
            // After 3 basics, the threshold fires and consumes the 3 stacks. Count-based.
            string heroes = @"{
  ""heroes"": [
    { ""id"": ""fb_st_hero"", ""name"": ""StackTrigger"", ""aspect"": ""Ember"", ""role"": ""Striker"",
      ""startingHero"": true,
      ""hp"": 100000, ""attack"": 200, ""defense"": 0, ""speed"": 900, ""critChance"": 0, ""critDamage"": 1.0,
      ""startEnergy"": 0,
      ""basic"": { ""id"": ""fbst_basic"", ""name"": ""Stack And Poke"",
        ""effects"": [
          { ""kind"": ""Damage"", ""target"": ""FrontEnemy"", ""power"": 0.001 },
          { ""kind"": ""GainResolve"", ""target"": ""Self"", ""maxStacks"": 9, ""duration"": 99 }
        ] },
      ""active"": { ""id"": ""fbst_active"", ""name"": ""Noop"", ""energyCost"": 9999,
        ""effects"": [ { ""kind"": ""Damage"", ""target"": ""FrontEnemy"", ""power"": 0.001 } ] },
      ""passive1"": { ""id"": ""fbst_threshold"", ""name"": ""Threshold Burst"",
        ""trigger"": ""OnStackThreshold"", ""oncePerBattle"": false,
        ""stackThresholdStatus"": ""Resolve"", ""stackThresholdCount"": 3,
        ""effects"": [
          { ""kind"": ""Damage"", ""target"": ""FrontEnemy"", ""power"": 1.0 }
        ] } }
  ]
}";
            string enemies = @"{
  ""enemies"": [
    { ""id"": ""fb_st_foe"", ""name"": ""Dummy"", ""aspect"": ""Ember"",
      ""hp"": 999999, ""attack"": 1, ""defense"": 0, ""speed"": 5, ""critChance"": 0, ""critDamage"": 1.0,
      ""basic"": { ""id"": ""fbstf"", ""name"": ""Tap"",
        ""effects"": [ { ""kind"": ""Damage"", ""target"": ""FrontEnemy"", ""power"": 0.001 } ] } }
  ]
}";
            string campaign = @"{
  ""chapters"": [ { ""id"": ""fbst_ch"", ""name"": ""StackThresh"", ""stages"": [
    { ""id"": ""fbst_arena"", ""index"": 1, ""enemies"": [ { ""id"": ""fb_st_foe"", ""level"": 1 } ] } ] } ]
}";
            ContentDatabase db = LoadSyntheticContent(heroes, enemies, campaign, ZeroVarianceBalance(10), "StackThreshold");
            if (db == null) { Check(false, "stack threshold arena built"); return; }
            List<HeroInstance> team = new List<HeroInstance>();
            team.Add(MakeInstance(db.GetHero("fb_st_hero"), 1));
            BattleResult r = RunWith(db, db.GetStage("fbst_arena"), 8585, team);
            if (r == null) { Check(false, "stack threshold arena ran"); return; }

            // Count how many times the threshold passive fired (PassiveTrigger events named
            // "Threshold Burst") and how many total GainResolve stacks were gained.
            int thresholdFirings = 0;
            int totalStacks = 0;
            for (int i = 0; i < r.Events.Count; i++)
            {
                BattleEvent e = r.Events[i];
                if (e.Type == BattleEventType.PassiveTrigger && e.AbilityName == "Threshold Burst")
                    thresholdFirings++;
                if (e.Type == BattleEventType.StatusApplied && e.Status == StatusKind.Resolve)
                    totalStacks++;
            }
            // With 10 rounds, the hero acts ~10 times, gaining ~10 stacks total. Every 3 stacks
            // consumed = 1 firing, so expect at least 3 firings (9 stacks / 3 = 3).
            Check(thresholdFirings >= 2,
                  "stack threshold: passive fired at least twice (" + thresholdFirings + " times from "
                  + totalStacks + " total stacks)");
            // Each firing consumes 3 stacks. Verify by checking that the total stacks gained exceeds
            // threshold firings * 3 (stacks are consumed, not just counted).
            Check(totalStacks >= thresholdFirings * 3,
                  "stack threshold: enough stacks were gained to account for all firings ("
                  + totalStacks + " gained, " + thresholdFirings + " firings x3 = "
                  + (thresholdFirings * 3) + ")");
        }

        // ================================================================ BATCH-FIVE ENGINE GAPS

        private static void CheckBatchFiveEngineGaps(ContentDatabase live)
        {
            Line("BATCH-FIVE ENGINE GAPS (4 broadcasts, cross-unit shield banking, same-side expiry counter)");
            CheckBatchFiveOrdinalPins();
            CheckBatchFiveNoShippedUsage(live);
            CheckBatchFiveEnumParity();
            CheckOnAllyShieldBreakArena();
            CheckOnAllyLedgerBankedArena();
            CheckOnEnemyHealedArena();
            CheckOnFunnelConvertFiredArena();
            CheckCrossUnitShieldBanking();
            CheckOnAppliedAllyStatusExpiredArena();
            Line("");
        }

        private static void CheckBatchFiveOrdinalPins()
        {
            Check((int)PassiveTrigger.OnAllyShieldBreak == 34,
                  "PassiveTrigger.OnAllyShieldBreak at 34 (got " + (int)PassiveTrigger.OnAllyShieldBreak + ")");
            Check((int)PassiveTrigger.OnAllyLedgerBanked == 35,
                  "PassiveTrigger.OnAllyLedgerBanked at 35 (got " + (int)PassiveTrigger.OnAllyLedgerBanked + ")");
            Check((int)PassiveTrigger.OnEnemyHealed == 36,
                  "PassiveTrigger.OnEnemyHealed at 36 (got " + (int)PassiveTrigger.OnEnemyHealed + ")");
            Check((int)PassiveTrigger.OnFunnelConvertFired == 37,
                  "PassiveTrigger.OnFunnelConvertFired at 37 (got " + (int)PassiveTrigger.OnFunnelConvertFired + ")");
            Check((int)PassiveTrigger.OnAppliedAllyStatusExpired == 38,
                  "PassiveTrigger.OnAppliedAllyStatusExpired at 38 (got " + (int)PassiveTrigger.OnAppliedAllyStatusExpired + ")");
            Check((int)PassiveTrigger.OnStackThreshold == 33,
                  "PassiveTrigger.OnStackThreshold still at 33 (got " + (int)PassiveTrigger.OnStackThreshold + ")");
        }

        private static void CheckBatchFiveNoShippedUsage(ContentDatabase db)
        {
            List<string> allyShieldBreak = new List<string>(), allyLedgerBanked = new List<string>();
            List<string> enemyHealed = new List<string>(), appliedAllyExpired = new List<string>();
            List<string> scaleByBanked = new List<string>();
            List<string> funnelConvertFired = new List<string>();

            List<UnitDef> units = new List<UnitDef>();
            for (int i = 0; i < db.Heroes.Count; i++) units.Add(db.Heroes[i]);
            for (int i = 0; i < db.Enemies.Count; i++) units.Add(db.Enemies[i]);

            for (int i = 0; i < units.Count; i++)
            {
                UnitDef def = units[i];
                List<EffectDef> all = new List<EffectDef>();
                List<string> where = new List<string>();
                if (def.BasicAttack != null)
                    AddWithNames(all, where, def.Id + "/" + def.BasicAttack.Name, def.BasicAttack.Effects);
                if (def.Active != null)
                    AddWithNames(all, where, def.Id + "/" + def.Active.Name, def.Active.Effects);
                for (int pi = 0; pi < def.Passives.Count; pi++)
                {
                    PassiveTrigger t = def.Passives[pi].Trigger;
                    string host = def.Id + "/" + def.Passives[pi].Name;
                    if (t == PassiveTrigger.OnAllyShieldBreak) allyShieldBreak.Add(host);
                    if (t == PassiveTrigger.OnAllyLedgerBanked) allyLedgerBanked.Add(host);
                    if (t == PassiveTrigger.OnEnemyHealed) enemyHealed.Add(host);
                    if (t == PassiveTrigger.OnFunnelConvertFired) funnelConvertFired.Add(host);
                    if (t == PassiveTrigger.OnAppliedAllyStatusExpired) appliedAllyExpired.Add(host);
                    AddWithNames(all, where, host, def.Passives[pi].Effects);
                }
                HeroDef hero = def as HeroDef;
                if (hero != null)
                {
                    for (int ti = 0; ti < hero.Talents.Count; ti++)
                    {
                        PassiveTrigger t = hero.Talents[ti].Trigger;
                        string host = def.Id + "/" + hero.Talents[ti].Name;
                        if (t == PassiveTrigger.OnAllyShieldBreak) allyShieldBreak.Add(host);
                        if (t == PassiveTrigger.OnAllyLedgerBanked) allyLedgerBanked.Add(host);
                        if (t == PassiveTrigger.OnEnemyHealed) enemyHealed.Add(host);
                        if (t == PassiveTrigger.OnFunnelConvertFired) funnelConvertFired.Add(host);
                        if (t == PassiveTrigger.OnAppliedAllyStatusExpired) appliedAllyExpired.Add(host);
                        AddWithNames(all, where, host, hero.Talents[ti].Effects);
                    }
                }
                for (int e = 0; e < all.Count; e++)
                {
                    if (all[e].ScaleByLastBanked) scaleByBanked.Add(where[e]);
                }
            }

            Check(allyShieldBreak.Count > 0,
                  "shipped content triggers a passive on OnAllyShieldBreak" + Used(allyShieldBreak));
            Check(allyLedgerBanked.Count > 0,
                  "shipped content triggers a passive on OnAllyLedgerBanked" + Used(allyLedgerBanked));
            Check(enemyHealed.Count > 0,
                  "shipped content triggers a passive on OnEnemyHealed" + Used(enemyHealed));
            // FLIPPED by ENGINE-GAPS pass 3. Velis's Remnant and her Starve the Light both say
            // "whenever Hollowed converts healing into damage", which is this trigger by name; they
            // had been answering OnEnemyHealed gated on the Ledger, and once Hollowed spends its one
            // conversion that reading pays on every later heal the conversion never touched.
            Check(funnelConvertFired.Count > 0,
                  "shipped content triggers a passive on OnFunnelConvertFired" + Used(funnelConvertFired));
            Check(appliedAllyExpired.Count > 0,
                  "shipped content triggers a passive on OnAppliedAllyStatusExpired"
                  + Used(appliedAllyExpired));
            Check(scaleByBanked.Count > 0,
                  "shipped content uses ScaleByLastBanked" + Used(scaleByBanked));
        }

        private static void CheckBatchFiveEnumParity()
        {
            bool ok = CheckEnumSet("PassiveTrigger",
                new string[] {
                    "None", "BattleStart", "TurnStart", "AfterBasicAttack", "OnCriticalHit",
                    "OnKill", "OnHpBelowThreshold", "OnDamaged", "OnBlock",
                    "OnEnemyActive", "OnEnemyBuffGained", "OnEnemyDamagedAlly", "OnTurnDelayed",
                    "OnHealApplied", "OnStatusRemoved", "OnStatusExpired",
                    "OnAllyHpBelowThreshold", "OnAllyHealed", "OnAllyShielded", "OnAllyWouldDie",
                    "OnEnemyDefeated", "OnAllyDefeated", "OnTurnDebtRepaid",
                    "OnDodge", "OnEnemyEnergyThreshold",
                    "OnAppliedStatusExpired", "OnAppliedDoTTick",
                    "OnAllyTurnEnd", "OnEnemyTurnEnd",
                    "OnLedgerCapped", "OnTurnDebtThreshold",
                    "OnShieldBreak", "OnEnemyHpBelowThreshold", "OnStackThreshold",
                    "OnAllyShieldBreak", "OnAllyLedgerBanked", "OnEnemyHealed",
                    "OnFunnelConvertFired", "OnAppliedAllyStatusExpired",
                    // Extended by the linked-targeting pass rather than answered by a second list
                    // of its own. This is the one place PassiveTrigger's membership is asserted,
                    // and two full copies of the same enum would be two things to keep in step -
                    // which is the argument this codebase has already made about
                    // AllEnemiesWithStatus and about the mark bank.
                    "OnLinkedUnitTargeted", "OnLinkedUnitHit",
                    // Extended again by the nine-gap pass, for the same reason: one list.
                    "OnTargeted", "OnStatusGained", "OnEchoFired", "OnRedirectReceived",
                    "OnRedirectSent",
                    // batch eight: the round's own boundary, and the far end of an enemy cast.
                    "RoundStart", "OnEnemyActiveResolved",
                    // cast cancellation: the declaration window, open to both sides
                    "OnCastDeclared",
                    // the displaced primitives: a unit turning on a different body
                    "OnEnemyChangedTarget",
                    // and the drain heard on the unit that caused it
                    "OnEnemyEnergyDrained",
                    // the far side of a unit's own Active
                    "AfterActiveCast",
                    // the engine-gaps pass, group 9: an ally receiving Energy, a Guard charge
                    // doing its job, and a unit attempting a debuff.
                    "OnAllyEnergyGained", "OnGuardPrevented", "OnEnemyAppliedStatus",
                    // group 14: the mirror RoundStart never had.
                    "RoundEnd",
                    // pass 2: the enemy side hearing a Ward land.
                    "OnEnemyShielded",
                    // pass 3: the moment "at the start of their next turn" names, for an ally.
                    "OnAllyTurnStart"
                },
                Enum.GetNames(typeof(PassiveTrigger)));
            Check(ok, "PassiveTrigger enum parity (" + Enum.GetNames(typeof(PassiveTrigger)).Length + " members)");
        }

        // ---- synthetic arena: OnAllyShieldBreak ----

        private static void CheckOnAllyShieldBreakArena()
        {
            // H1 (front tank) has a small shield at BattleStart. H2 has OnAllyShieldBreak passive.
            // Enemy breaks H1's shield â†’ H2's passive fires.
            string heroes = @"{
  ""heroes"": [
    { ""id"": ""b5_tank"", ""name"": ""Tank"", ""aspect"": ""Ember"", ""role"": ""Bulwark"",
      ""startingHero"": true,
      ""hp"": 100000, ""attack"": 100, ""defense"": 0, ""speed"": 50, ""critChance"": 0, ""critDamage"": 1.0,
      ""startEnergy"": 0,
      ""basic"": { ""id"": ""b5t_basic"", ""name"": ""Poke"",
        ""effects"": [ { ""kind"": ""Damage"", ""target"": ""FrontEnemy"", ""power"": 0.001 } ] },
      ""active"": { ""id"": ""b5t_active"", ""name"": ""Noop"", ""energyCost"": 9999,
        ""effects"": [ { ""kind"": ""Damage"", ""target"": ""FrontEnemy"", ""power"": 0.001 } ] },
      ""passive1"": { ""id"": ""b5t_setup"", ""name"": ""Small Shield"", ""trigger"": ""BattleStart"",
        ""effects"": [
