            // run. In the second she attacks it, which is the case the ally filter has to exclude.
            string watcherBasic = watcherAttacks
                ? @"{ ""kind"": ""Damage"", ""target"": ""FrontEnemy"", ""power"": 0.01 }"
                : @"{ ""kind"": ""Heal"", ""target"": ""Self"", ""flat"": 1 }";

