        ""oncePerBattle"": false, ""triggerSourceIsAlly"": true,
        ""effects"": [
          { ""kind"": ""ApplyStatus"", ""target"": ""Self"", ""status"": ""AttackUp"",
            ""magnitude"": 0, ""duration"": 2, ""chance"": 1 }
