        private static ContentDatabase _darkArena, _darkArenaSlow;

        private static ContentDatabase DarkArena(bool slow)
        {
            if (slow && _darkArenaSlow != null) return _darkArenaSlow;
            if (!slow && _darkArena != null) return _darkArena;

            string dir = FindContentDirForSweep();
            if (dir == null) return null;
            string heroes;
            try { heroes = File.ReadAllText(Path.Combine(dir, "heroes.json")); }
            catch (Exception) { return null; }

            ContentDatabase db = LoadSyntheticContent(heroes, DarkEnemies, DarkCampaign,
                                                      slow ? DarkSlowBalance : DarkBalance,
                                                      slow ? "dark-talent (slow clock)" : "dark-talent");
            if (slow) _darkArenaSlow = db; else _darkArena = db;
            return db;
        }

        /// <summary>
        /// One battle, reduced to the handful of totals the checks below assert on.
        ///
        /// Read off the EVENT LIST and nothing else, which is the same discipline the battle screen
        /// works under: if a talent's effect is not in the record, the talent did not happen, and a
        /// check that inspected wiring instead would pass on a talent that never fires.
        /// </summary>
        private sealed class DarkProbe
        {
            public int Events, Rounds;
            public bool Victory;
            public int SubjectId = -1;
            public float SubjectMaxHp;
            public int SubjectDamage, SubjectHeal, SubjectShield;
            /// <summary>How many damage EVENTS the subject produced, which is the
            /// only way to see a talent that appends a blow whose size is bounded.
            /// Hale II adds one capped rider per cast: two extra events against a
            /// battle-long total that the shifted RNG stream swamps.</summary>
            public int SubjectHits;
            public int HealToOthers, BiggestHealToOther;
            public int SubjectEnergyGain, AllyEnergyGain, EnemyEnergyLoss;
            public int BuffsStripped, ResolveSpent;
            public int AllyShifts, EnemyShifts;
            public int AllyShiftTarget = -1, AllyEnergyTarget = -1;
            public int Spreads, MarkOnBiggestEnemy;
            public int SubjectCasts;
            public readonly Dictionary<StatusKind, int> Applied = new Dictionary<StatusKind, int>();
            public readonly Dictionary<string, int> Fired = new Dictionary<string, int>();

            /// <summary>
            /// HOW MANY TIMES A UNIT'S ENERGY MOVED BY EXACTLY THIS MUCH, and it is the only way
            /// several of these talents can be measured at all. An energy bar is CAPPED, so a
            /// battle-long total silently swallows every grant that arrived at a full bar - Merek's
            /// six 5-Energy payments summed to zero extra Energy over thirty rounds. A count of
            /// exact deltas cannot be swallowed, and "+5 six times" is also the sentence the
            /// talent's own text says.
            /// </summary>
            public readonly Dictionary<int, int> SubjectDeltas = new Dictionary<int, int>();
            public readonly Dictionary<int, int> AllyDeltas = new Dictionary<int, int>();
            public readonly Dictionary<int, int> EnemyDeltas = new Dictionary<int, int>();

            public int Fires(string abilityId) { int n; Fired.TryGetValue(abilityId, out n); return n; }
            public int Count(StatusKind k) { int n; Applied.TryGetValue(k, out n); return n; }
            public int SubjectPlus(int d) { int n; SubjectDeltas.TryGetValue(d, out n); return n; }
            public int AllyPlus(int d) { int n; AllyDeltas.TryGetValue(d, out n); return n; }
            public int EnemyMinus(int d) { int n; EnemyDeltas.TryGetValue(-d, out n); return n; }
        }

        private static DarkProbe RunDark(string heroId, int talent, string stageId, string allies,
                                         int seed, bool slow)
        {
            ContentDatabase db = DarkArena(slow);
            if (db == null) return null;
            HeroDef subject = db.GetHero(heroId);
            StageDef stage = db.GetStage(stageId);
            if (subject == null || stage == null) return null;

            List<HeroInstance> team = new List<HeroInstance>();
            HeroInstance me = MakeInstance(subject, 40);
            me.SelectedTalent = talent;
            team.Add(me);
            if (!string.IsNullOrEmpty(allies))
            {
                string[] ids = allies.Split(',');
                for (int i = 0; i < ids.Length; i++)
                {
                    HeroDef d = db.GetHero(ids[i].Trim());
                    if (d == null) return null;
                    team.Add(MakeInstance(d, 40));
                }
            }

            BattleResult r = RunWith(db, stage, seed, team);
            if (r == null) return null;

            DarkProbe p = new DarkProbe();
            p.Events = r.Events.Count;
            p.Rounds = r.Rounds;
            p.Victory = r.Victory;

            int biggestEnemy = -1;
            float biggestHp = -1f;
            Dictionary<int, int> energy = new Dictionary<int, int>();
            for (int i = 0; i < r.Units.Count; i++)
            {
                UnitSnapshot u = r.Units[i];
                if (u.DefId == subject.Id && p.SubjectId < 0) { p.SubjectId = u.Id; p.SubjectMaxHp = u.MaxHp; }
                if (!u.IsPlayer && u.MaxHp > biggestHp) { biggestHp = u.MaxHp; biggestEnemy = u.Id; }
                energy[u.Id] = u.StartEnergy;
            }

            for (int i = 0; i < r.Events.Count; i++)
            {
                BattleEvent e = r.Events[i];
                UnitSnapshot tgt = r.FindUnit(e.TargetId);
                switch (e.Type)
                {
                    case BattleEventType.PassiveTrigger:
                    {
                        string id = e.AbilityId == null ? "" : e.AbilityId;
                        int n; p.Fired.TryGetValue(id, out n); p.Fired[id] = n + 1;
                        break;
                    }
                    case BattleEventType.AbilityCast:
                        if (e.SourceId == p.SubjectId) p.SubjectCasts++;
                        break;
                    case BattleEventType.Damage:
                        if (e.SourceId == p.SubjectId) { p.SubjectDamage += e.Value; p.SubjectHits++; }
                        break;
                    case BattleEventType.Heal:
                        if (e.SourceId == p.SubjectId)
                        {
                            p.SubjectHeal += e.Value;
                            if (e.TargetId != p.SubjectId)
                            {
                                p.HealToOthers += e.Value;
                                if (e.Value > p.BiggestHealToOther) p.BiggestHealToOther = e.Value;
                            }
                        }
                        break;
                    case BattleEventType.ShieldGain:
                        if (e.SourceId == p.SubjectId) p.SubjectShield += e.Value;
                        break;
                    case BattleEventType.StatusApplied:
                    {
                        int n; p.Applied.TryGetValue(e.Status, out n); p.Applied[e.Status] = n + 1;
                        if (e.Status == StatusKind.Mark && e.TargetId == biggestEnemy
                            && e.SourceId == p.SubjectId) p.MarkOnBiggestEnemy++;
                        break;
                    }
                    case BattleEventType.StatusExpired:
                        // Mark and MarkAlt are excluded on purpose: they are bookkeeping rather
                        // than buffs, several kits strip their own, and counting them would make
                        // this number say "a status left an enemy" instead of "a buff was taken".
                        if (e.SourceId == p.SubjectId && tgt != null && !tgt.IsPlayer
                            && !StatusInfo.IsHarmful(e.Status)
                            && e.Status != StatusKind.Mark && e.Status != StatusKind.MarkAlt)
                            p.BuffsStripped++;
                        if (e.TargetId == p.SubjectId && e.Status == StatusKind.Resolve) p.ResolveSpent++;
                        break;
                    case BattleEventType.StatusSpread:
                        p.Spreads++;
                        break;
                    case BattleEventType.TurnOrderShift:
                        if (tgt == null) break;
                        if (tgt.IsPlayer) { p.AllyShifts++; if (p.AllyShiftTarget < 0) p.AllyShiftTarget = e.TargetId; }
                        else p.EnemyShifts++;
                        break;
                    case BattleEventType.EnergyChanged:
                    {
                        int was;
                        if (!energy.TryGetValue(e.TargetId, out was)) was = 0;
                        int delta = e.Value - was;
                        energy[e.TargetId] = e.Value;
                        if (tgt == null) break;
                        if (tgt.IsPlayer && e.TargetId == p.SubjectId)
                        {
                            if (delta > 0) p.SubjectEnergyGain += delta;
                            Bump(p.SubjectDeltas, delta);
                        }
                        if (tgt.IsPlayer && e.TargetId != p.SubjectId)
                        {
                            if (delta > 0)
                            {
                                p.AllyEnergyGain += delta;
                                if (p.AllyEnergyTarget < 0) p.AllyEnergyTarget = e.TargetId;
                            }
                            Bump(p.AllyDeltas, delta);
                        }
                        if (!tgt.IsPlayer)
                        {
                            if (delta < 0) p.EnemyEnergyLoss += -delta;
                            Bump(p.EnemyDeltas, delta);
                        }
                        break;
                    }
                }
            }
            return p;
        }

        private static void Bump(Dictionary<int, int> into, int key)
        {
            int n; into.TryGetValue(key, out n); into[key] = n + 1;
        }

        private static bool DarkPair(string hero, int talent, string stage, string allies, int seed,
                                     bool slow, out DarkProbe without, out DarkProbe with)
        {
            without = RunDark(hero, 0, stage, allies, seed, slow);
            with = RunDark(hero, talent, stage, allies, seed, slow);
            return without != null && with != null;
        }

        /// <summary>The four squads the checks below field, named so a stage line reads as one idea.</summary>
        private const string DarkStrikers =
            "talren_the_wayfinder,oris_the_unwritten_path,arden_the_precise_measure,merek_the_sequence_thief";
        private const string DarkFive =
            "isara_the_second_chance,brenna_the_remaining_wall,kael_the_unyielding,darian_the_hidden_bulwark";
        private const string DarkWall =
            "kael_the_unyielding,darian_the_hidden_bulwark,isara_the_second_chance";
        private const string DarkPairUp = "brenna_the_remaining_wall,kael_the_unyielding";
        /// <summary>Brenna I's room: the squad beside her where her Lasting Guard's cap binds. See
        /// the Brenna I check for why it is not DarkFive, which already holds her.</summary>
        private const string DarkBrennaCap =
            "darian_the_hidden_bulwark,nereia_the_field_medic,rovan_the_adaptive_commander";

        /// <summary>
        /// EVERY DARK TALENT THIS ARENA CAN REACH, PROVED ONE AT A TIME.
        ///
        /// The sweep above asks whether a talent does ANYTHING in one shared arena and answers with
        /// a fingerprint. That is the right instrument for 90 talents and the wrong one for a
        /// repair: a fingerprint that moved says the fight changed, not that the fight changed in
        /// the direction the talent's own text describes. Each check here asserts the DIRECTION and
        /// the AMOUNT, against the same hero with no talent selected on the same seed - so a talent
        /// that starts doing the wrong thing fails even though its fingerprint still moves.
        ///
        /// Five of these were BROKEN rather than dark, and all five by one defect: an appended
        /// effect lands at the end of its host's effect list, and the host had already stripped or
        /// spent the thing the appended effect's condition reads. They are named in the commit that
        /// repaired them; what the checks below pin is the repaired behaviour.
        ///
        /// THE FOUR THAT USED TO BE ABSENT ARE HERE NOW, and each needed a repair rather than a
        /// better arena - which was the finding their absence recorded:
        ///   - Elyra III and Edrin III waited on a stack their own host could never accumulate,
        ///     because `ConditionSubject.LastTarget` reads `_lastTarget` and `ResolveAbility`
        ///     cleared that field for the wrapper ability a passive's effects run inside. The clear
        ///     is gated on depth 0 now. Edrin's Record also carried no duration, so his stacks
        ///     expired two rounds after they landed and four could never be held at once; his
        ///     description names a ceiling and no timer, and the authoring now says so.
        ///   - Hale II was an OR branch on a clause that was already true: its host read
        ///     SubjectDamagedSinceMyTurn, `LastTurnRound` is stamped as the turn OPENS, and the
        ///     ability's own first effect damages the target. The host asks
        ///     SubjectDamagedByOtherSinceMyTurn now, which is the "if any ALLY attacked it" its
        ///     own text names, so the talent has something left to decide.
        ///   - Kael II re-applied a Mark to enemies that already carried one, which is a duration
        ///     refresh rather than the application its text describes. It reads
        ///     SubjectLostStatusThisFiring now - a condition that did not exist.
        /// </summary>
        /// <summary>
        /// Every (hero, talent) pair THE DARK TALENTS section fields, in the form the talent sweep
        /// names them, and the room it is fielded in: the stage, the squad beside the subject, the
        /// seed and which clock. The note under that sweep counts its overlap with this list rather
        /// than carrying a number somebody has to remember to move, and TALENTS WORTH PICKING
        /// measures each pair's value in the same room, because for a talent the sweep leaves dark
        /// this room is the only place a player's pick of it shows up at all.
        ///
        /// One room per pair. Nysera III is fielded twice above; this names the armoured room,
        /// because that is the one about her damage rather than about a second concealment.
        /// </summary>
        private sealed class TalentRoom
        {
            public readonly string Pair, Stage, Allies;
            public readonly int Seed;
            public readonly bool Slow;
            public TalentRoom(string pair, string stage, string allies, int seed, bool slow)
            { Pair = pair; Stage = stage; Allies = allies; Seed = seed; Slow = slow; }
        }

        private static readonly TalentRoom[] DarkTalentRooms = {
            new TalentRoom("kiva_the_forsaken_oath II", "s_soft_mid_big", "", 1, false),
            new TalentRoom("kiva_the_forsaken_oath III", "s_soft_mid_big", "", 1, false),
            new TalentRoom("aeron_the_unbroken_stride II", "s_caster_tail", DarkFive, 1, false),
            new TalentRoom("merek_the_sequence_thief I", "s_caster_tail", "", 1, false),
            new TalentRoom("nysera_the_missing_arrow I", "s_buffer", "", 1, false),
            new TalentRoom("nysera_the_missing_arrow III", "s_cloaker_armored", "", 1, false),
            new TalentRoom("vaelis_the_unfixed_blade I", "s_soft_soft_big", "isara_the_second_chance", 2, false),
            new TalentRoom("vaelis_the_unfixed_blade II", "s_soft4_triple", "", 4, false),
            new TalentRoom("vaelis_the_unfixed_blade III", "s_soft_soft_big", "isara_the_second_chance", 2, false),
            new TalentRoom("dahlia_the_wayward_hymn II", "s_caster_bruiser_tail", DarkFive, 1, false),
            new TalentRoom("brenna_the_remaining_wall I", "s_caster_bruiser_tail", DarkBrennaCap, 1, false),
            new TalentRoom("altheon_the_first_witness III", "s_buffer_tail", DarkStrikers, 1, false),
            new TalentRoom("isolde_the_slow_fading III", "s_buffer", "", 1, false),
            // Mireth I has a room since C13: the sweep no longer raises The Missing Page, so without
            // one the value check would read her trap as "changes nothing" and drop it off the list.
            new TalentRoom("mireth_the_erased_name I", "s_buffer", "", 1, false),
            new TalentRoom("mireth_the_erased_name II", "s_buffer", "", 1, false),
            new TalentRoom("mireth_the_erased_name III", "s_soft_big", DarkPairUp, 1, false),
            new TalentRoom("rheia_the_revision_scribe I", "s_selfdown", DarkStrikers, 1, false),
            new TalentRoom("rheia_the_revision_scribe II", "s_selfdown", DarkStrikers, 1, false),
            new TalentRoom("rheia_the_revision_scribe III", "s_selfdown", DarkStrikers, 1, false),
            new TalentRoom("rovan_the_adaptive_commander II", "s_bruiser", "isara_the_second_chance", 1, false),
            new TalentRoom("seraphine_the_closed_volume I", "s_soft_big", DarkStrikers, 1, false),
            new TalentRoom("seraphine_the_closed_volume II", "s_buffer", DarkStrikers, 1, true),
            new TalentRoom("seraphine_the_closed_volume III", "s_buffer_tail", DarkStrikers, 1, false),
            new TalentRoom("sylven_the_unfading_blade III", "s_triple", "", 1, false),
            // Velis II and III used to be read in s_mender and are not any more, because both
            // now move the sweep and that room cannot weigh them. Every clause either of them
            // carries shortens a fight against a body that mends itself - HealSuppression and a
            // Vulnerable both do - and a shorter fight is fewer blows, so the room reads a
            // talent doing exactly what it says as a LOSS of total output. THE DARK TALENTS
            // still fields Velis III there and still proves the clause lands; what is dropped
            // is a second output reading whose sign is decided by the room rather than by the
            // talent.
            new TalentRoom("isara_the_second_chance II", "s_wash", "darian_the_hidden_bulwark,kael_the_unyielding", 2, true),
            new TalentRoom("elyra_the_patient_warden III", "s_buffer", DarkFive, 1, false),
            new TalentRoom("edrin_the_distant_bell III", "s_buffer", DarkFive, 1, false),
            new TalentRoom("hale_the_relentless_hunter II", "s_buffer", "", 1, false),
            new TalentRoom("kael_the_unyielding II", "s_triple", "", 1, false) };

        private static TalentRoom DarkRoomFor(string pair)
        {
            for (int i = 0; i < DarkTalentRooms.Length; i++)
                if (DarkTalentRooms[i].Pair == pair) return DarkTalentRooms[i];
            return null;
        }

        private static void CheckDarkTalents(ContentDatabase live)
        {
            Line("THE DARK TALENTS (each in the smallest arena that raises what it was waiting on)");

            DarkProbe a, b;

            // ---- Kiva II: a body is brought low, and the biggest one inherits the mark.
            //
            // IT USED TO ANSWER OnKill, AND THE KILLING BLOW IS RARELY HERS: it fired nowhere in
            // the sweep and read an exact zero. It answers OnEnemyHpBelowThreshold now, once per
            // enemy, which is a thing a fight reaches - and it is the roster's only listener on
            // that trigger since Caldus III stopped waiting on a Declared Target falling under a
            // third of its HP once a battle. She hunts what is already hurt, so the trigger fits
            // her better than it fitted him. THE ROOM MOVED WITH THE TRIGGER, off s_soft_mid_big,
            // where no body ever crosses half its HP and the new clause therefore read 0 against
            // 0. s_soft_big has one that does.
            if (!DarkPair("kiva_the_forsaken_oath", 2, "s_soft_big", "", 1, false, out a, out b))
                Check(false, "kiva II arena built");
            else
                Check(b.MarkOnBiggestEnemy > a.MarkOnBiggestEnemy
                      && b.Count(StatusKind.DefenseDown) > a.Count(StatusKind.DefenseDown)
                      && a.Count(StatusKind.DefenseDown) == 0,
                      "Kiva II puts Forsaken on the highest-HP enemy when a body is brought low, and"
                      + " breaks the whole line's guard with it ("
                      + b.MarkOnBiggestEnemy + " mark(s) on the biggest body against "
                      + a.MarkOnBiggestEnemy + ", " + b.Count(StatusKind.DefenseDown)
                      + " guard(s) broken against " + a.Count(StatusKind.DefenseDown)
                      + ") - the broken guard is the clean signal here: her own basic reaches the"
                      + " biggest body in this room often enough that the mark alone is close either"
                      + " way, and nothing else in her kit breaks a guard at all");

            // ---- Kiva III: a body falls, and what it pays out with no Broken Link asked for.
            //
            // THIS CHECK ASSERTS A SHIELD AGAIN. It stopped being able to when Severance Paid was
            // repaired, and the reason was a rate rather than a bug: Severance Paid was inert -
            // both of its clauses and both of her active's copies of them gated on
            // StatusStacksAtLeast with no status named, which answers false unconditionally - so
            // nothing in her kit ever SPENT a Broken Link and Unclaimed Victory found two of them
            // banked at the kill. With those four gates repaired the spend is live and the rates
            // leave no remainder: Abandoned Support banks at most one link a round and Severance
            // Paid consumes one on every basic against a Forsaken body, the same basic whose own
            // Mark banked it, so she opens most turns at zero and a kill found nothing to consume.
            // A talent that pays exactly zero for structural reasons is not a talent.
            //
            // The repair is content: the FIRST Shield clause is ungated, and a link-gated one sits
            // on top of it and spends every link she holds. The talent-value pass then moved the
            // trigger off OnKill, because the killing blow is rarely hers, to OnEnemyDefeated, and
            // took the Forsaken gate off with it, so it answers any enemy falling now. Two clauses,
            // not three: the clause that needed two links held at once went with that pass. The
            // third check pins the ungated clause itself rather than the total, so a talent that
            // came to pay only when a link happened to be held would fail here even though it
            // still pays something.
            if (!DarkPair("kiva_the_forsaken_oath", 3, "s_soft_mid_big", "", 1, false, out a, out b))
                Check(false, "kiva III arena built");
            else
            {
                Check(b.Fires("kiva_unclaimed_victory") > 0 && a.Fires("kiva_unclaimed_victory") == 0,
                      "Kiva III fires when an enemy falls (" + b.Fires("kiva_unclaimed_victory")
                      + " against " + a.Fires("kiva_unclaimed_victory") + ")");
                Check(b.SubjectShield > a.SubjectShield && a.SubjectShield == 0,
                      "and PAYS on it (" + b.SubjectShield + " Shield against " + a.SubjectShield
                      + " with no talent selected)");
                PassiveDef uv = live.GetHero("kiva_the_forsaken_oath").TalentAt(3);
                EffectDef ungated = uv != null && uv.Effects.Count > 0 ? uv.Effects[0] : null;
                int floorPerFire = ungated == null ? 0
                    : (int)Math.Round(b.SubjectMaxHp * ungated.SelfHpRatio, MidpointRounding.AwayFromZero);
                Check(ungated != null && ungated.Kind == EffectKind.Shield
                      && ungated.Condition == EffectCondition.None && floorPerFire > 0
                      && b.SubjectShield >= b.Fires("kiva_unclaimed_victory") * floorPerFire,
                      "and its first clause asks for no Broken Link: every firing paid at least "
                      + floorPerFire + " Shield ("
                      + ((ungated == null ? 0f : ungated.SelfHpRatio) * 100f).ToString("0", CultureInfo.InvariantCulture)
                      + "% of her " + b.SubjectMaxHp.ToString("0", CultureInfo.InvariantCulture) + " Max HP), " + b.SubjectShield + " over "
                      + b.Fires("kiva_unclaimed_victory") + " firing(s) - anything past the floor is"
                      + " the link-gated clause on top");
                Check(a.Count(StatusKind.HealSuppression) > 0,
                      "and Severance Paid, which named no status on its own stack gate and was inert"
                      + " for it, now lands with no talent selected at all: "
                      + a.Count(StatusKind.HealSuppression) + " application(s) of HealSuppression");
            }

            // ---- Aeron II: the ally Momentum Breaker pays is the ally that advances.
            // Five bodies on each side so the pending order has a tail both shifts can land in.
            if (!DarkPair("aeron_the_unbroken_stride", 2, "s_caster_tail", DarkFive, 1, false, out a, out b))
                Check(false, "aeron II arena built");
            else
                Check(b.AllyShifts == 1 && a.AllyShifts == 0
                      && b.AllyShiftTarget == b.AllyEnergyTarget,
                      "Aeron II advances the SAME ally Momentum Breaker just handed the energy to "
                      + "(shift on unit " + b.AllyShiftTarget + ", energy to unit " + b.AllyEnergyTarget
                      + ", " + b.AllyShifts + " ally shift against " + a.AllyShifts
                      + ") - appended after the grant it re-resolved LowestEnergyAlly and advanced "
                      + "whichever OTHER ally was now poorest");

            // ---- Merek I: five extra Energy each time Anticipated answers a resolved active.
            if (!DarkPair("merek_the_sequence_thief", 1, "s_caster_tail", "", 1, false, out a, out b))
                Check(false, "merek I arena built");
            else
            {
                int fires = b.Fires("merek_anticipated");
                Check(fires > 0 && a.SubjectPlus(5) == 0 && b.SubjectPlus(5) > 0,
                      "Merek I pays him 5 Energy per Anticipated firing (" + fires + " firing(s), "
                      + b.SubjectPlus(5) + " payment(s) of exactly 5 against " + a.SubjectPlus(5)
                      + ") - nothing else in this fight moves his bar by 5, and the firings that "
                      + "do not show up here arrived at a bar already full");
            }

            // ---- Nysera I: Vanishing Mark also takes a buff off the body that aimed at her.
            if (!DarkPair("nysera_the_missing_arrow", 1, "s_buffer", "", 1, false, out a, out b))
                Check(false, "nysera I arena built");
            else
                Check(b.BuffsStripped > 0 && a.BuffsStripped == 0,
                      "Nysera I strips one positive status per Vanishing Mark trigger ("
                      + b.BuffsStripped + " against " + a.BuffsStripped + ") - appended after the "
                      + "host's own RemoveStatus it read a Mark that was already gone");

            // ---- Nysera III: the Armor Break she gains on going unseen has to meet armour to matter.
            if (!DarkPair("nysera_the_missing_arrow", 3, "s_cloaker_armored", "", 1, false, out a, out b))
                Check(false, "nysera III arena built");
            else
                Check(b.SubjectDamage > a.SubjectDamage,
                      "Nysera III lifts her damage against a 900-Defense body once she has gone "
                      + "unseen (" + b.SubjectDamage + " against " + a.SubjectDamage
                      + ") - the 15% Armor Break is worth nothing against the 0-Defense bodies the "
                      + "sweep fields");

            // ---- Vaelis I: Departure also lowers the previous target's Effect Resist.
            if (!DarkPair("vaelis_the_unfixed_blade", 1, "s_soft_soft_big", "isara_the_second_chance",
                          2, false, out a, out b))
                Check(false, "vaelis I arena built");
            else
                Check(b.Count(StatusKind.EffectResistDown) > 0 && a.Count(StatusKind.EffectResistDown) == 0,
                      "Vaelis I puts Effect Resist Down on the body Departure is bound to ("
                      + b.Count(StatusKind.EffectResistDown) + " against "
                      + a.Count(StatusKind.EffectResistDown) + ") and takes it off again when "
                      + "Departure triggers");

            // ---- Vaelis II: both bodies the swap touches are opened before it strikes them.
            //
            // WHAT THIS CHECK USED TO ASSERT WAS THE TALENT BEING A RESTRICTION. Stolen Position
            // capped Passed Position at two positive effects moved each way instead of every one,
            // and moving fewer buffs is strictly less than moving all of them - the card said so in
            // as many words, and the reading was an exact zero in every room. The talent buys the
            // opening the swap creates now, and this reads that.
            if (!DarkPair("vaelis_the_unfixed_blade", 2, "s_soft4_triple", "", 4, false, out a, out b))
                Check(false, "vaelis II arena built");
            else
                Check(b.Count(StatusKind.Vulnerable) > a.Count(StatusKind.Vulnerable)
                      && b.SubjectDamage > a.SubjectDamage,
                      "Vaelis II opens both bodies Passed Position moves between before either is "
                      + "struck (" + b.Count(StatusKind.Vulnerable) + " opening(s) against "
                      + a.Count(StatusKind.Vulnerable) + ", " + b.SubjectDamage + " damage against "
                      + a.SubjectDamage + ") - the Vulnerable is source-keyed, so it is his own "
                      + "blows it moves and nobody else's");

            // ---- Vaelis III: twelve Energy when the ally that triggered Departure is a Mender.
            if (!DarkPair("vaelis_the_unfixed_blade", 3, "s_soft_soft_big", "isara_the_second_chance",
                          2, false, out a, out b))
                Check(false, "vaelis III arena built");
            else
            {
                int fires = b.Fires("vaelis_departure");
                Check(fires > 0 && b.SubjectPlus(12) - a.SubjectPlus(12) == fires,
                      "Vaelis III pays him 12 Energy per Departure triggered by a Mender ally ("
                      + fires + " firing(s), " + (b.SubjectPlus(12) - a.SubjectPlus(12))
                      + " payment(s) of exactly 12) - his own SubjectRoleIs clause needs an ally "
                      + "of that role to land the hit");
            }

            // ---- Dahlia II: Broken Rhythm's heal reaches the second-lowest ally too.
            if (!DarkPair("dahlia_the_wayward_hymn", 2, "s_caster_bruiser_tail", DarkFive, 1, false,
                          out a, out b))
                Check(false, "dahlia II arena built");
            else
                Check(b.HealToOthers > a.HealToOthers,
                      "Dahlia II heals the second-lowest ally for 40% of Attack whenever Broken "
                      + "Rhythm answers a cast (" + b.HealToOthers + " against " + a.HealToOthers
                      + " healed onto other bodies)");

            // ---- Brenna I: the cap on what a Lasting Guard may record, where the cap binds.
            //
            // MOVED OFF s_bruiser_healer beside DarkWall by ENGINE-GAPS pass 2 (content C7). That room
            // raised the binding cap only while Darian's Unseen Guard answered every Ward on an ally,
            // Brenna's included; the Guard it laid shares one entry with the Lasting Guard beside it.
            // Answering only his own Ward, it stopped doing that and the cap stopped binding (675
            // either way). Of every room and seed the section fields, this is the one where it binds.
            //
            // AND THEN MOVED OFF DarkFive, because DarkFive holds Brenna and this subject IS Brenna:
            // the room fielded two of her, which PlayerProfile.AssignToTeam never allows. With the
            // copy removed (Isara, Kael, Darian, same stage) the cap never binds - 675 released
            // either way at seeds 1 to 4 - so what this check proved it proved with the copy. A search of legal rooms - every stage of the matrix arena, both clocks,
            // every squad of up to three from Isara, Kael, Darian, Eira, Nereia, Rovan, Caldus and
            // Dahlia, six seeds each - found the cap binding in 43 of 29,016 fights. This room
            // binds at five of its six seeds, the most of any; the talent is real and narrow.
            if (!DarkPair("brenna_the_remaining_wall", 1, "s_caster_bruiser_tail", DarkBrennaCap, 1, false,
                          out a, out b))
                Check(false, "brenna I arena built");
            else
                Check(b.BiggestHealToOther > a.BiggestHealToOther,
                      "Brenna I lets one ally's Lasting Guard release " + b.BiggestHealToOther
                      + " where the 8% ceiling stopped it at " + a.BiggestHealToOther
                      + " - the Guard prevented more than 8% of Max HP, so the cap was what was "
                      + "binding and the talent raising it let the rest through");

            // ---- Altheon III: LIT, and it is now a check rather than a note.
            //
            // THE NOTE THIS REPLACES IS DEAD AND SAID SO FOR A PASS TOO LONG. It read "it needs
            // one blow of about 5700 on the Ledger holder inside two rounds and the roster's
            // biggest is about 3600", which was true of the Subject the five-star review found
            // and false of the Subject it left: the record's ceiling is 50% of Altheon's Attack
            // now rather than 120%, the entry lives three rounds rather than two, and
            // ledgerBankFromCaster means it banks HIS blows instead of whichever hit landed
            // first. No blow of 5700 is wanted by anything any more. The Ledger closes eight
            // times in this arena and OnLedgerCapped is raised every time, which is the trigger
            // both Fixed in Place and this talent wait on.
            //
            // WHAT IT PAYS IS NEGATIVE, AND THAT IS THE READING RATHER THAN A FAULT IN THE CHECK.
            // Final Record is oncePerBattle: it fires once, pays 20% of Attack per Record held,
            // and then consumes every Record - which is the sentence Pinoy wrote. But Preserved
            // Moment spends those same Records as a standing +5% on EVERY blow Altheon lands on a
            // marked body, so the talent buys at most three 20% blows and sells a 15% output
            // modifier for as long as it takes him to earn them back. Over thirty rounds that
            // trade costs more than it pays. The check asserts that it FIRES and that the record
            // closes, because those are what the five-star review made reachable, and prints the
            // sign of the trade rather than asserting it: a talent nobody would select is a
            // balance question for Pinoy, not a broken wire.
            if (!DarkPair("altheon_the_first_witness", 3, "s_buffer_tail", DarkStrikers, 1, false,
                          out a, out b))
                Check(false, "altheon III arena built");
            else
            {
                Check(b.Fires("altheon_fixed_in_place") > 0 && b.Fires("altheon_final_record") > 0
                      && b.SubjectDamage != a.SubjectDamage,
                      "Altheon III fires on a record that closes (" + b.Fires("altheon_fixed_in_place")
                      + " cap(s) raised, talent fired " + b.Fires("altheon_final_record")
                      + " time) - the five-star review's 3-round Subject, 50%-of-Attack ceiling and"
                      + " caster-only banking are what made OnLedgerCapped reachable at all");
                Line("  [note] on this one seed the firing reads " + b.SubjectDamage + " against "
                     + a.SubjectDamage + " damage. One seed is one crit draw: TALENTS WORTH PICKING"
                     + " reads the same room over " + TalentValueSeeds + " seeds, and that is where the"
                     + " trade's sign lives.");
            }

            // ---- Isolde III: Revelation expiring on four Traces.
            if (!DarkPair("isolde_the_slow_fading", 3, "s_buffer", "", 1, false, out a, out b))
                Check(false, "isolde III arena built");
            else
                Check(b.Fires("isolde_final_revelation") > 0 && b.SubjectDamage > a.SubjectDamage
                      && b.ResolveSpent > a.ResolveSpent,
                      "Isolde III fires on Revelation's expiry and consumes the Traces ("
                      + b.Fires("isolde_final_revelation") + " firing(s), "
                      + (b.ResolveSpent - a.ResolveSpent) + " extra Traces spent, "
                      + b.SubjectDamage + " damage against " + a.SubjectDamage + ")");

            // ---- Mireth I: the same landings, each one erasing twice as much.
            //
            // THE TRAP THIS CHECK USED TO PIN IS GONE, and it was pinned exactly right:
            // firesPerSubject is a WHOLE-BATTLE budget where the sentence meant one Focus's
            // duration, so buying two landings per enemy bought FEWER than the once-a-round limit
            // it replaced, and the talent paid a fifth of the strike's damage for the privilege.
            // Turning the limit off instead was measured and buys nothing at all - against one body
            // that buffs every turn the passive already lands once a round, so an unlimited version
            // lands the same fourteen times and the reading was an exact zero. What the talent
            // deepens now is the erasure itself: the Dispel takes two entries instead of one, so
            // Absence banks twice as fast, and Absence is what makes her hit a marked body harder.
            if (!DarkPair("mireth_the_erased_name", 1, "s_buffer", "", 1, false, out a, out b))
                Check(false, "mireth I arena built");
            else
            {
                int fa, fb;
                a.Fired.TryGetValue("mireth_the_missing_page", out fa);
                b.Fired.TryGetValue("mireth_the_missing_page", out fb);
                Check(fb > 0 && fb == fa && b.SubjectDamage > a.SubjectDamage,
                      "Mireth I takes two entries off the page per landing instead of one, on the "
                      + "same " + fb + " landing(s) as without it (" + fa + " without), and the "
                      + "Absence that banks is worth " + b.SubjectDamage + " damage against "
                      + a.SubjectDamage);
            }

            // ---- Mireth II: the Energy either side of the third Page.
            if (!DarkPair("mireth_the_erased_name", 2, "s_buffer", "", 1, false, out a, out b))
                Check(false, "mireth II arena built");
            else
                Check(b.SubjectPlus(15) > a.SubjectPlus(15) && b.EnemyMinus(10) > a.EnemyMinus(10),
                      "Mireth II gives her 15 Energy and takes 10 off the Focused enemy when The "
                      + "Missing Page spends three Pages (" + (b.SubjectPlus(15) - a.SubjectPlus(15))
                      + " payment(s) of exactly 15 to her, " + (b.EnemyMinus(10) - a.EnemyMinus(10))
                      + " drain(s) of exactly 10 off it)");

            // ---- Mireth III: the same firing against a wounded body.
            // MOVED ROOMS WITH C13 (ENGINE-GAPS pass 3). The Missing Page hears real buffs only now,
            // and neither body in s_frail_big ever grants itself one; it had been firing on
            // Mireth's own Mark. TSoft buffs itself every turn and is small enough to fall under
            // the talent's line.
            if (!DarkPair("mireth_the_erased_name", 3, "s_soft_big", DarkPairUp, 1, false, out a, out b))
                Check(false, "mireth III arena built");
            else
                Check(b.SubjectDamage > a.SubjectDamage,
                      "Mireth III adds damage when The Missing Page lands on a wounded Focused "
                      + "enemy (" + b.SubjectDamage + " against " + a.SubjectDamage + ")");

            // ---- Rheia I: the rewrite's own blow, far heavier.
            //
            // WHAT THIS USED TO ASSERT WAS THE PRICE, AND THE PRICE WAS THE FAULT. Endless
            // Revision took two Energy off EVERY Applied Revision - her whole cast rate - and
            // bought twenty percent of Attack on one conditional clause of one cast. It read
            // -7961, t -22.9, and its KnownCostlyTalents entry called that "fewer casts that
            // each hit harder", which is true and is not a purchase. The Energy is gone and the
            // rider is the whole talent, so what is asserted is the rider.
            if (!DarkPair("rheia_the_revision_scribe", 1, "s_selfdown", DarkStrikers, 1, false,
                          out a, out b))
                Check(false, "rheia I arena built");
            else
                Check(b.SubjectCasts > 0 && a.SubjectCasts > 0 && b.SubjectDamage > a.SubjectDamage
                      && b.SubjectDamage / b.SubjectCasts > a.SubjectDamage / a.SubjectCasts,
                      "Rheia I makes Rewrite the Outcome's blow on a rewritten enemy far heavier ("
                      + (b.SubjectDamage / b.SubjectCasts) + " damage per cast against "
                      + (a.SubjectDamage / a.SubjectCasts) + ", " + b.SubjectDamage + " in total"
                      + " against " + a.SubjectDamage + ") - she needs a body that buffs AND"
                      + " debuffs itself for the rewrite to have an Attack Down to rewrite at all");

            // ---- Rheia II: the rider Second Draft carries at four Revision.
            if (!DarkPair("rheia_the_revision_scribe", 2, "s_selfdown", DarkStrikers, 1, false,
                          out a, out b))
                Check(false, "rheia II arena built");
            else
                Check(b.Count(StatusKind.DefenseUp) > a.Count(StatusKind.DefenseUp)
                      || b.Count(StatusKind.AttackDown) > a.Count(StatusKind.AttackDown),
                      "Rheia II lands its Second Draft rider at four Revision (DefenseUp "
                      + b.Count(StatusKind.DefenseUp) + " against " + a.Count(StatusKind.DefenseUp)
                      + ", AttackDown " + b.Count(StatusKind.AttackDown) + " against "
                      + a.Count(StatusKind.AttackDown) + ")");

            // ---- Rheia III: Revision is no longer spent, and the blow is bigger.
            if (!DarkPair("rheia_the_revision_scribe", 3, "s_selfdown", DarkStrikers, 1, false,
                          out a, out b))
                Check(false, "rheia III arena built");
            else
                // The damage half is no longer asserted. Since ENGINE-GAPS pass 2 every cast of
                // hers refills Revision (Applied Revision counts the statuses she changes), so
                // keeping it buys less than the 10 Energy each full-Revision strike costs, and the
                // talent reads as a trade in TALENTS WORTH PICKING rather than as a gain.
                Check(b.ResolveSpent < a.ResolveSpent,
                      "Rheia III stops Second Draft consuming Revision (" + b.ResolveSpent
                      + " Revision spent against " + a.ResolveSpent + "); the bigger strike it buys is "
                      + "paid for in Energy, " + b.SubjectDamage + " damage against " + a.SubjectDamage);

            // ---- Rovan II: the Shield he passes is worth Energy to whoever catches it.
            if (!DarkPair("rovan_the_adaptive_commander", 2, "s_bruiser", "isara_the_second_chance",
                          1, false, out a, out b))
                Check(false, "rovan II arena built");
            else
                Check(b.AllyPlus(8) > 0 && a.AllyPlus(8) == 0 && b.AllyPlus(8) % 2 == 0,
                      "Rovan II pays the ally that catches the Shield 8 Energy per 10% of Max HP "
                      + "moved, to a ceiling of 16 (" + b.AllyPlus(8) + " payment(s) of exactly 8 "
                      + "against " + a.AllyPlus(8) + ", two per cast, which is the ceiling) - "
                      + "LastMovedAboveHpFraction needs a Shield that big to have moved at all");

            // ---- Seraphine I: a deeper Footnote reaches its own cap sooner.
            //
            // THE SQUAD MOVED OFF DarkPairUp, and for the reason the check's own tail names. The
            // difference between recording 25% and recording 35% only survives while the record
            // is still under its 80%-of-Attack cap when it is read; beside Brenna and Kael the
            // Footnote saturates on every round it is written, so both arms closed the book the
            // same fourteen times and a deeper record bought nothing. Four Strikers fill it
            // faster than Seraphine alone but leave the early rounds under the ceiling, which is
            // where the ten points are worth a closing.
            if (!DarkPair("seraphine_the_closed_volume", 1, "s_soft_big", DarkStrikers, 1, false,
                          out a, out b))
                Check(false, "seraphine I arena built");
            else
                Check(b.Count(StatusKind.BuffSuppression) > a.Count(StatusKind.BuffSuppression),
                      "Seraphine I records 35% instead of 25%, so Volume Closed shuts the book a "
                      + "round earlier (" + b.Count(StatusKind.BuffSuppression) + " suppression(s) "
                      + "against " + a.Count(StatusKind.BuffSuppression)
                      + ") - the record has to stay under its 80%-of-Attack cap for the difference "
                      + "to survive");

            // ---- Seraphine II: the Footnote that moves starts with something written in it.
            // The record has to stay well UNDER its cap for the extra 30% to survive to the
            // release, which is why this is the one stage where nothing hits hard: against the
            // bodies the other checks field, the Footnote is at its ceiling either way and the
            // talent's gift is swallowed by the cap rather than paid out.
            //
            // MOVED OFF s_triple/DarkPairUp, AND THE REASON IS THE POINT. That arena met the
            // "stay under the cap" precondition only while Volume Closed could not run: with the
            // passive live, a Footnote that reaches its ceiling is now CLOSED - Mark and Ledger
            // both removed - before the next Contradiction Filed can release it, so both arms of
            // the pair released nothing and the talent measured an exact zero. It is the same
            // precondition this comment already named, tightened by a passive that now fires: the
            // record has to stay under the cap, and under a live Volume Closed that also means the
            // book must not close. A slow clock against a frail line does it - no book closes in
            // thirty rounds - and the talent pays the same 1870 it paid before the repair, which
            // is what says this is the same measurement in a different room rather than a weaker
            // one. THAT CROSS REFERENCE NOW DESTROYS ITS OWN PAYOUT IN A FAST FIGHT IS A FINDING
            // about Seraphine, not a fault in this check: it loads the record toward the ceiling
            // that Volume Closed converts into a buff-lock and 15 Energy instead of into damage.
            //
            // AND IT MOVED AGAIN, FOR THE SAME PRECONDITION, when Dispel learned to skip the
            // bookkeeping kinds. Contrary Evidence stopped eating the MarkAlt and the Mark, so
            // Volume Closed now closes books it could not reach on s_frail_healer, and the extra
            // 30% Cross Reference writes is converted into a buff-lock and 15 Energy rather than
            // released as damage - that arm ran 105319 against 110012 and the talent measured as
            // a LOSS. One body that buffs itself every turn is the smallest room where the
            // record is read before it is closed, and there the talent pays 2859 over seven
            // casts, which is the 30% of her Attack its text promises arriving as damage.
            //
            // AND A THIRD TIME, OFF DarkWall, by ENGINE-GAPS pass 2: Kael's Unusable Cover now keeps
            // its Rubble for a firing that moves a Ward and Darian answers only his own Ward, and
            // the wall that stood in front of her let the book close again (85259 against 85331).
            // The same one body that buffs itself, beside the Strikers, reads the record before it
            // closes.
            if (!DarkPair("seraphine_the_closed_volume", 2, "s_buffer", DarkStrikers, 1, true,
                          out a, out b))
                Check(false, "seraphine II arena built");
            else
                Check(b.SubjectDamage > a.SubjectDamage,
                      "Seraphine II hands the Footnote it moves an immediate record worth 30% of "
                      + "her Attack, and that record is released as damage (" + b.SubjectDamage
                      + " against " + a.SubjectDamage + ")");

            // ---- Seraphine III: the turn progress the suppressed body loses.
            if (!DarkPair("seraphine_the_closed_volume", 3, "s_buffer_tail", DarkStrikers, 1, false,
                          out a, out b))
                Check(false, "seraphine III arena built");
            else
                Check(b.EnemyShifts > a.EnemyShifts,
                      "Seraphine III costs the body Volume Closed silences 10% turn progress ("
                      + b.EnemyShifts + " enemy shift(s) against " + a.EnemyShifts
                      + ") - the authored shift is a 0 that does nothing until the talent gives it "
                      + "a magnitude");

            // ---- Sylven III: the Healing Reduction that rides Wounds Remember.
            if (!DarkPair("sylven_the_unfading_blade", 3, "s_triple", "", 1, false, out a, out b))
                Check(false, "sylven III arena built");
            else
                Check(b.Count(StatusKind.HealingReduction) > 0
                      && a.Count(StatusKind.HealingReduction) == 0,
                      "Sylven III puts Healing Reduction on the body whose recorded effect came "
                      + "back (" + b.Count(StatusKind.HealingReduction) + " against "
                      + a.Count(StatusKind.HealingReduction)
                      + ") - appended after the host's own Dispel it read a record whose status the "
                      + "Dispel had just taken away, and the record has to be a LONG buff or "
                      + "nothing is being carried when it is read");

            // ---- Velis III: the healing the third Remnant denies.
            //
            // MOVED ROOMS IN ENGINE-GAPS PASS 3, alone against a small enemy that mends itself. A
            // Remnant comes from a conversion now, Hollowed converts once, and Hollowed only lands
            // on a body under half HP at the cast - so What Was Taken needs three separate
            // Hollowed, each landed low and each healed. With four strikers beside her the frail
            // enemy died after two; beside its healer the sturdy one never dipped below half.
            if (!DarkPair("velis_the_hollow_vow", 3, "s_mender", "", 1, false,
                          out a, out b))
                Check(false, "velis III arena built");
            else
                // THE HEAL SUPPRESSION THIS USED TO ASSERT IS GONE FROM THE TALENT, and the reason
                // is what the talent had to become to be worth picking. Final Denial hung a
                // suppression off What Was Taken, which waits on three Remnants, and the talent
                // read an exact zero everywhere the sweep could see it. Given an opening on her
                // basic it reads +1314, t 20.6 - and that opening kills the body before three
                // Remnants are ever banked, so the suppression became a clause on the card that
                // the fight never runs. It was taken off the card rather than left on it.
                // The damage is PRINTED and not asserted, and s_mender is why. A room built around
                // a body that mends itself is one the talent shortens: the opening kills faster,
                // a shorter fight is fewer blows, and the total falls while every blow in it hit
                // harder. That is the same property that took Velis II and III off the TalentRoom
                // list, and TALENTS WORTH PICKING reads this talent in the sweep arena, which has
                // no such body and reads +1314, t 20.6.
                Check(b.Count(StatusKind.Vulnerable) > a.Count(StatusKind.Vulnerable)
                      && a.Count(StatusKind.Vulnerable) == 0,
                      "Velis III opens the body Denied Return cuts ("
                      + b.Count(StatusKind.Vulnerable) + " opening(s) against "
                      + a.Count(StatusKind.Vulnerable) + ") - the Vulnerable is source-keyed, so it "
                      + "is hers alone. Her total in this room reads " + b.SubjectDamage
                      + " against " + a.SubjectDamage + " because the opening ends the fight sooner");

            // ---- Isara II: the second body a Seedling heals.
            if (!DarkPair("isara_the_second_chance", 2, "s_wash", "darian_the_hidden_bulwark,"
                          + "kael_the_unyielding", 2, true, out a, out b))
                Check(false, "isara II arena built");
            else
                Check(b.SubjectHeal > a.SubjectHeal,
                      "Isara II heals a second ally each time a Seedling triggers ("
                      + b.SubjectHeal + " against " + a.SubjectHeal
                      + ", the difference being 70% of her Attack) - appended after What Survives "
                      + "cleared its own bookkeeping mark it read a mark that was already gone");

            // ---- Elyra III: the stacks Slow Growth can finally hold, spent by Stillness Pays.
            //
            // One self-buffing body and the five-hero line. Her Patience is banked by a passive
            // gated on ConditionSubject.LastTarget, so before the depth-0 repair she reached the
            // end of every fight with none and the four her third talent asks for were
            // unreachable by construction. This was one of the two the arena could not raise.
            if (!DarkPair("elyra_the_patient_warden", 3, "s_buffer", DarkFive, 1, false, out a, out b))
                Check(false, "elyra III arena built");
            else
                Check(b.SubjectShield > 0 && a.SubjectShield == 0 && b.SubjectDamage > a.SubjectDamage,
                      "Elyra III pays out at four Patience (" + b.SubjectShield + " Shield against "
                      + a.SubjectShield + ", and " + b.SubjectDamage + " damage against "
                      + a.SubjectDamage + ") - her Slow Growth banks nothing at all until a passive"
                      + " can read the body its basic struck");

            // ---- Edrin III: the same repair on the other side of it, plus the Record's lifetime.
            if (!DarkPair("edrin_the_distant_bell", 3, "s_buffer", DarkFive, 1, false, out a, out b))
                Check(false, "edrin III arena built");
            else
                // WHAT THIS USED TO ASSERT WAS THE SPEND, AND THE SPEND WAS THE FAULT. Nothing Is
                // Lost sold Guardian of What Remains' standing modifier - 4% of his damage against
                // a marked body per Record held - for one blow, and the parity study priced that
                // sale: -2.9pp of win rate in the duel and -1.7 on the ladder. It raises the
                // ceiling instead, so nothing he banks is lost and no blow is added to feed an
                // enemy bar.
                Check(b.SubjectDamage > a.SubjectDamage && b.ResolveSpent == a.ResolveSpent,
                      "Edrin III banks Record past where Guardian of What Remains used to stop, and"
                      + " every one of them still raises his damage against a marked body ("
                      + b.SubjectDamage + " against " + a.SubjectDamage + ", with " + b.ResolveSpent
                      + " Record spent either way)");

            // ---- Hale II: the clause that decides something once its host stops answering itself.
            //
            // SOLO, and the loneliness is the point: with no ally on the line nobody but Hale can
            // have attacked the Quarry, so the AND branch is false by construction and everything
            // the talent adds is the OR branch its own text describes. Against the old host - which
            // asked only whether the body had been damaged at all, and had damaged it itself one
            // effect earlier - the two runs were identical.
            if (!DarkPair("hale_the_relentless_hunter", 2, "s_buffer", "", 1, false, out a, out b))
                Check(false, "hale II arena built");
            else
                Check(b.SubjectHits > a.SubjectHits,
                      "Hale II lands Closing Radius's missing-HP damage with no ally to have hit the"
                      + " Quarry, once he is under half health (" + b.SubjectHits + " blow(s) against "
                      + a.SubjectHits + ", one extra per cast) - COUNTED rather than summed, because"
                      + " the rider is bounded at 120% of his Attack now and a battle-long total"
                      + " cannot see it: an extra blow draws its own crit and variance, so the"
                      + " stream it shifts moves more damage than the blow itself carries ("
                      + b.SubjectDamage + " against " + a.SubjectDamage + ")");

            // ---- Kael II: Fault Line applied where Take Down the Wall took something away.
            //
            // MOVED OFF s_buffer, AND THE MOVE IS THE FINDING. Take Down the Wall's Dispel is
            // gated on HasMyMark and takes one status walking newest first, and until Dispel
            // learned to skip the bookkeeping kinds the newest thing on a marked body was Kael's
            // own Fault Line. So the talent's SubjectLostStatusThisFiring was answering a strip
            // of the Mark it then re-applied, and it separated against a body that carries no
            // real buff at all: t_buffer's AttackUp lasts one round and has expired by the time
            // he casts, so that arena reads "stripped 0" in both arms and the old separation was
            // the defect measuring itself.
            //
            // t_triple keeps four buffs for nine rounds, so the Dispel has something a player
            // would call a buff to take. Six casts, six strips, six Fault Lines that the arm
            // without the talent does not lay.
            if (!DarkPair("kael_the_unyielding", 2, "s_triple", "", 1, false, out a, out b))
                Check(false, "kael II arena built");
            else
                Check(b.BuffsStripped > 0 && b.BuffsStripped == a.BuffsStripped
                      && b.Count(StatusKind.Mark) - a.Count(StatusKind.Mark) == b.BuffsStripped,
                      "Kael II applies Fault Line to the body his active stripped ("
                      + b.Count(StatusKind.Mark) + " against " + a.Count(StatusKind.Mark)
                      + " Fault Lines, one per strip over " + b.BuffsStripped
                      + ") - the Dispel takes the same buffs either way, so the difference is the"
                      + " talent and nothing else");

            // ---- Nysera III: the second concealment, which nothing authored before this pass.
            //
            // Two soft bodies she can actually kill. The ArmorBreakUp half of the talent is checked
            // in the armoured arena above; this is the clause that follows it - "if that attack
            // defeats the target, Nysera immediately becomes Untargetable again" - and it is worth
            // exactly two extra Stealth applications here, one per kill made while the mark-up is
            // still on her.
            if (!DarkPair("nysera_the_missing_arrow", 3, "s_soft_soft_big", "", 1, false, out a, out b))
                Check(false, "nysera III kill arena built");
            else
                Check(b.Count(StatusKind.Stealth) > a.Count(StatusKind.Stealth),
                      "Nysera III goes unseen again on a kill made while Last Known Position is up ("
                      + b.Count(StatusKind.Stealth) + " concealment(s) against "
                      + a.Count(StatusKind.Stealth) + ")");

            Line("");
        }

        // ------------------------------------------------- talents worth picking

        /// <summary>
        /// Seeds per reading, and far more than the talent sweep's five, because this asks a
        /// different question. The sweep asks whether a talent CHANGED the fight, and one changed
        /// seed answers that. This asks which WAY it changed the hero's output, and the sweep
        /// arena rolls damage variance, so a talent that shifts the dice stream moves a five-seed
        /// total by more than most talents are worth. Measured rather than assumed: Isara I summed
        /// to -48 over five seeds and to +99,947 over thirty; Altheon III read -3,972 on the one seed
        /// THE DARK TALENTS section fields it at, and +1,025 averaged over 150 seeds in the same
        /// room. At forty the set of talents that lose beyond two standard errors is the same set
        /// 150 seeds finds, and the whole check costs about three seconds.
        /// </summary>
        private const int TalentValueSeeds = 40;

        /// <summary>
        /// How far below zero a paired mean has to sit, in standard errors, to count as a loss.
        /// Two is the ordinary line between a reading and a coin toss, and every talent on the list
        /// below sits beyond it at both 40 and 150 seeds, the nearest at -2.8.
        /// </summary>
        private const double TalentValueLossT = -2.0;

        /// <summary>
        /// A talent that costs its own hero output, and why it stays anyway.
        ///
        /// A TRAP loses output and gives nothing back; it is on this list only because it cannot
        /// be repaired from content, and its note says what it is waiting on. A TRADE loses output
        /// and buys something the output total cannot see, and its note names what.
        /// </summary>
        private sealed class CostlyTalent
        {
            public readonly string Pair, Kind, Why;
            public CostlyTalent(string pair, string kind, string why) { Pair = pair; Kind = kind; Why = why; }
        }

        private static readonly CostlyTalent[] KnownCostlyTalents = {
            new CostlyTalent("nysera_the_missing_arrow I", "TRADE",
                "utility: the Dispel strips a buff off the body that targets her, which in the sweep is"
                + " the Warden's Provoke, freeing the whole line's single-target aim. Her own output"
                + " falls because her basic then leaves the body that was feeding Vanishing Mark") };

        private static CostlyTalent CostlyTalentFor(string pair)
        {
            for (int i = 0; i < KnownCostlyTalents.Length; i++)
                if (KnownCostlyTalents[i].Pair == pair) return KnownCostlyTalents[i];
            return null;
        }

        /// <summary>One paired reading: the hero's own output with a talent against the same hero
        /// with none, seed for seed, as a per-battle mean.</summary>
        private sealed class TalentValue
        {
            public long Without, With;
            public double Mean, T;
            public bool Loses { get { return Mean < 0 && T <= TalentValueLossT; } }

            public string Show(string where)
            {
                return where + " " + Without + " -> " + With + " ("
                     + (Mean >= 0 ? "+" : "") + Mean.ToString("0", CultureInfo.InvariantCulture)
                     + ", t " + T.ToString("0.0", CultureInfo.InvariantCulture) + ")";
            }
        }

        private static TalentValue PairUp(List<long> without, List<long> with)
        {
            TalentValue v = new TalentValue();
            int n = without.Count;
            long a = 0, b = 0;
            double mean = 0;
            for (int i = 0; i < n; i++) { a += without[i]; b += with[i]; mean += with[i] - without[i]; }
            mean /= n;
            double ss = 0;
            for (int i = 0; i < n; i++)
            {
                double d = with[i] - without[i] - mean;
                ss += d * d;
            }
            double se = n > 1 ? Math.Sqrt(ss / (n - 1) / n) : 0;
            v.Without = a / n;
            v.With = b / n;
            v.Mean = mean;
            // A loss with no spread at all is a deterministic loss, not a zero reading.
            v.T = se > 0 ? mean / se : (mean < 0 ? -99 : mean > 0 ? 99 : 0);
            return v;
        }

        private static long OutputOf(BattleResult r, string defId)
        {
            if (r == null) return 0;
            long[] terms = new long[3];
            SubjectOutput(r, defId, terms);
            return terms[0] + terms[1] + terms[2];
        }

        private static BattleResult RunSweepBattle(ContentDatabase arena, StageDef stage, List<HeroDef> fillers,
                                                   HeroDef def, int talent, int seed)
        {
            List<HeroInstance> team = new List<HeroInstance>();
            HeroInstance me = MakeInstance(def, HeroSweepLevel);
            me.SelectedTalent = talent;
            team.Add(me);
            for (int f = 0; f < fillers.Count; f++) team.Add(MakeInstance(fillers[f], HeroSweepLevel));
            return RunWith(arena, stage, HeroSweepSeed(def.Id, seed), team);
        }

        /// <summary>The same battle RunDark fights, returned whole rather than reduced to a probe.</summary>
        private static BattleResult RunDarkBattle(string heroId, int talent, TalentRoom room, int seed)
        {
            ContentDatabase db = DarkArena(room.Slow);
            if (db == null) return null;
            HeroDef subject = db.GetHero(heroId);
            StageDef stage = db.GetStage(room.Stage);
            if (subject == null || stage == null) return null;
            List<HeroInstance> team = new List<HeroInstance>();
            HeroInstance me = MakeInstance(subject, 40);
            me.SelectedTalent = talent;
            team.Add(me);
            if (!string.IsNullOrEmpty(room.Allies))
            {
                string[] ids = room.Allies.Split(',');
                for (int i = 0; i < ids.Length; i++)
                {
                    HeroDef d = db.GetHero(ids[i].Trim());
                    if (d == null) return null;
                    team.Add(MakeInstance(d, 40));
                }
            }
            return RunWith(db, stage, seed, team);
        }

        /// <summary>
        /// A TALENT A PLAYER PICKS SHOULD NOT MAKE THEIR HERO WORSE, and this is where that is
        /// measured rather than hoped.
        ///
        /// Every authored talent is read against the same hero with nothing picked, seed for seed,
        /// in every arena that actually reaches it: the sweep arena when the talent changes a sweep
        /// fight at all, and its room in THE DARK TALENTS section when it has one - which is the
        /// only reading there is for a talent the sweep leaves dark. The quantity is the star band's
        /// own: damage dealt, healing paid and shielding granted, credited by source.
        ///
        /// A talent LOSES when its paired mean sits below zero by more than two standard errors in
        /// any arena that reaches it. Every talent that loses is on KnownCostlyTalents with its
        /// reason, and the check fails both ways: a talent that starts losing and is not on the list
        /// is a new trap until somebody writes down what it buys, and a listed talent that stops
        /// losing has left the list and has to be taken off it, so the list never outlives the
        /// reading that put a talent on it.
        ///
        /// What it does not claim. Output is one currency. A talent that buys survival, control or
        /// somebody else's damage can lose here and be the right pick, which is exactly what a
        /// TRADE entry records; the check only guarantees that nobody has to discover that the hard
        /// way, one talent at a time.
        /// </summary>
        private static void CheckTalentsAreWorthPicking(ContentDatabase live)
        {
            Line("TALENTS WORTH PICKING (each talent's hero, output with it against output without, paired over "
                 + TalentValueSeeds + " seeds");
            Line("                       in every arena that reaches it: per-battle mean, change, t)");

            ContentDatabase arena = BuildHeroSweepArena(live);
            List<HeroDef> fillers = BuildHeroSweepFillers();
            StageDef stage = arena == null ? null : arena.GetStage("sweep_arena");
            if (arena == null || fillers == null || stage == null)
            { Check(false, "talent-value arena built"); Line(""); return; }

            List<HeroDef> authored = new List<HeroDef>();
            for (int i = 0; i < live.Heroes.Count; i++)
            {
                HeroDef h = arena.GetHero(live.Heroes[i].Id);
                if (h != null && h.Talents.Count > 0) authored.Add(h);
            }
            authored.Sort(delegate (HeroDef a, HeroDef b) { return string.CompareOrdinal(a.Id, b.Id); });

            int measured = 0, gains = 0, flat = 0;
            List<string> losing = new List<string>();
            List<string> unlisted = new List<string>();
            List<string> left = new List<string>();

            for (int h = 0; h < authored.Count; h++)
            {
                HeroDef def = authored[h];
                List<long> bare = new List<long>();
                string[] bareHash = new string[TalentValueSeeds + 1];
                for (int s = 1; s <= TalentValueSeeds; s++)
                {
                    BattleResult r = RunSweepBattle(arena, stage, fillers, def, 0, s);
                    bare.Add(OutputOf(r, def.Id));
                    bareHash[s] = r == null ? "NULL" : HeroSweepHash(r);
                }

                for (int t = 1; t <= def.Talents.Count; t++)
                {
                    string pair = def.Id + " " + RomanOf(t);
                    List<long> with = new List<long>();
                    bool moved = false;
                    for (int s = 1; s <= TalentValueSeeds; s++)
                    {
                        BattleResult r = RunSweepBattle(arena, stage, fillers, def, t, s);
                        with.Add(OutputOf(r, def.Id));
                        if (r != null && HeroSweepHash(r) != bareHash[s]) moved = true;
                    }

                    List<string> parts = new List<string>();
                    bool loses = false, gainsSomewhere = false;
                    if (moved)
                    {
                        TalentValue v = PairUp(bare, with);
                        parts.Add(v.Show("sweep"));
                        if (v.Loses) loses = true;
                        if (v.T >= -TalentValueLossT) gainsSomewhere = true;
                    }
                    TalentRoom room = DarkRoomFor(pair);
                    if (room != null)
                    {
                        List<long> a = new List<long>(), b = new List<long>();
                        for (int s = 0; s < TalentValueSeeds; s++)
                        {
                            a.Add(OutputOf(RunDarkBattle(def.Id, 0, room, room.Seed + s), def.Id));
                            b.Add(OutputOf(RunDarkBattle(def.Id, t, room, room.Seed + s), def.Id));
                        }
                        TalentValue v = PairUp(a, b);
                        parts.Add(v.Show(room.Stage));
                        if (v.Loses) loses = true;
                        if (v.T >= -TalentValueLossT) gainsSomewhere = true;
                    }
                    if (parts.Count == 0) parts.Add("unreached");

                    measured++;
                    if (loses) losing.Add(pair);
                    else if (gainsSomewhere) gains++;
                    else flat++;

                    CostlyTalent known = CostlyTalentFor(pair);
                    if (loses && known == null) unlisted.Add(pair);
                    if (!loses && known != null) left.Add(pair);

                    string reading = string.Join("; ", parts.ToArray());
                    Line("  " + def.Name + " " + RomanOf(t) + "  " + reading
                         + (loses ? "  <- LOSES" + (known != null ? ", " + known.Kind : ", NOT ON THE LIST") : ""));
                }
            }

            Line("  " + measured + " talents: " + gains + " gain beyond two standard errors, " + flat
                 + " sit within the noise or change nothing the output total can see, " + losing.Count
                 + " lose.");
            for (int i = 0; i < KnownCostlyTalents.Length; i++)
            {
                CostlyTalent k = KnownCostlyTalents[i];
                Line("  [" + k.Kind.ToLowerInvariant() + "] " + k.Pair + ": " + k.Why + ".");
            }

            Check(unlisted.Count == 0,
                  unlisted.Count == 0
                    ? "every talent that costs its hero output is on the list with what it buys ("
                      + losing.Count + " of " + measured + ")"
                    : unlisted.Count + " talent(s) now cost their hero output and are not on"
                      + " KnownCostlyTalents - each is a trap until somebody writes down what it buys: "
                      + string.Join(", ", unlisted.ToArray()));
            Check(left.Count == 0,
                  left.Count == 0
                    ? "no talent on the list has stopped costing its hero output"
                    : left.Count + " talent(s) on KnownCostlyTalents no longer lose output and have left"
                      + " the list: " + string.Join(", ", left.ToArray()));
            Line("");
        }

        private const string TalentSweepBaselineFile = "talent-sweep-baseline.txt";

        /// <summary>
        /// Seeds per talent, and deliberately more than the hero sweep's five.
        ///
        /// The hero sweep asks whether a kit MOVED, and five seeds answer that: a kit that changed
        /// changes them all. This asks whether a talent does anything at all, and many of them are
        /// gated - on a kill, on a mark the hero has to land first, on an ally dropping below a
        /// threshold - so a seed where the gate never opens says nothing about the talent. More
        /// seeds would be the obvious way to raise that, and it was measured rather than assumed:
        /// at 5 seeds 31 talents show no effect, at 15 it is still 31, at 30 it is 30 - one talent
        /// bought for 2,250 extra baseline lines and 0.6s. The gates these talents wait on are
        /// structural, not statistical; an arena that never raises OnLedgerCapped never raises it.
        /// So this stays at five, matching the hero sweep line for line, and the way to light the
        /// dark ones is a better arena or a repaired talent rather than more dice.
        /// </summary>
        private const int TalentSweepSeeds = 5;

        /// <summary>
        /// EVERY AUTHORED TALENT, EXECUTED, in the arena the hero sweep already uses.
        ///
        /// WHY A SECOND SWEEP RATHER THAN A WIDER FIRST ONE. The hero sweep fields each kit with
        /// SelectedTalent 0, and so does a fresh profile, so its 150 lines and the 72 stage
        /// fingerprints were all measurements of heroes with no talent chosen: 90 authored talents,
        /// 85 of them never once executed, and a talent appended to the wrong passive index moved
        /// nothing anywhere. Both Clone defects found this month were in exactly that blind spot -
        /// they only reached players who had picked a talent.
        ///
        /// Folding the talents into the hero sweep - each hero once per selection - would have
        /// rewritten all 150 existing lines into a 600-line file, and a rewritten baseline cannot
        /// tell "the new selection did this" from "content moved underneath us". Keeping them apart
        /// means the old 150 stay byte-identical and every line here is new by construction, so the
        /// cause of a difference is never in question. It also keeps the two questions separate:
        /// the hero sweep asks whether a KIT moved, this asks whether a TALENT does anything.
        ///
        /// THE COMPARISON IS THE TEST. Each talent runs on the same hero, the same arena and the
        /// SAME SEED as that hero's no-talent line, so a talent that changes nothing produces the
        /// same fingerprint as not picking it. That is the one failure the old instrument could not
        /// see, and it is a plain inequality here rather than an inspection of wiring.
        /// </summary>
        private static void CheckAuthoredTalentSweep(ContentDatabase live)
        {
            Line("AUTHORED-TALENT SWEEP (every talent executed, against the same hero with none selected)");

            List<HeroDef> authored = new List<HeroDef>();
            for (int i = 0; i < live.Heroes.Count; i++)
            {
                HeroDef h = live.Heroes[i];
                if (h.BasicAttack != null && h.BasicAttack.Id.Contains("placeholder")) continue;
                authored.Add(h);
            }
            authored.Sort(delegate (HeroDef a, HeroDef b) { return string.CompareOrdinal(a.Id, b.Id); });

            ContentDatabase arena = BuildHeroSweepArena(live);
            List<HeroDef> fillers = BuildHeroSweepFillers();
            StageDef stage = arena == null ? null : arena.GetStage("sweep_arena");
            if (arena == null || fillers == null || stage == null)
            { Check(false, "talent-sweep arena built"); Line(""); return; }

            int talentCount = 0;
            for (int h = 0; h < authored.Count; h++)
            {
                HeroDef def = arena.GetHero(authored[h].Id);
                if (def != null) talentCount += def.Talents.Count;
            }
            Check(talentCount > 0,
                  talentCount + " authored talent(s) across " + authored.Count + " hero(es), each run at "
                  + TalentSweepSeeds + " seeds");
            if (talentCount == 0) { Line(""); return; }

            List<string> lines = new List<string>();
            List<string> gated = new List<string>();
            List<string> twins = new List<string>();
            Dictionary<string, bool> isLive = new Dictionary<string, bool>();
            _talentExercise = new List<string>();

            for (int h = 0; h < authored.Count; h++)
            {
                HeroDef def = arena.GetHero(authored[h].Id);
                if (def == null) continue;

                // The hero with nothing picked, once per seed, kept to compare against. Same arena,
                // same seed and same squad as the hero sweep's own line for this hero.
                string[] bare = new string[TalentSweepSeeds + 1];
                for (int s = 1; s <= TalentSweepSeeds; s++) bare[s] = RunTalentLine(arena, stage, fillers, def, 0, s);

                string report = def.Name;
                for (int t = 1; t <= def.Talents.Count; t++)
                {
                    PassiveDef talent = def.TalentAt(t);
                    int moved = 0;
                    int fires = 0;
                    for (int s = 1; s <= TalentSweepSeeds; s++)
                    {
                        string hash = RunTalentLine(arena, stage, fillers, def, t, s);
                        lines.Add(def.Id + "|" + t + "|" + s + "|" + hash);
                        if (hash != bare[s] && hash != "NULL") moved++;
                        fires += _lastTalentFires;
                    }
                    isLive[def.Id + "|" + t] = moved > 0;
                    if (moved == 0 && !TalentIsStructurallyDead(def, talent))
                        gated.Add(def.Id + " " + RomanOf(t) + " needs " + TalentGate(talent));
                    report += " | " + RomanOf(t) + " " + TalentShape(talent)
                            + (TalentIsPassiveShaped(talent) ? " fires " + fires : "")
                            + " moved " + moved + "/" + TalentSweepSeeds
                            + (moved == 0 ? " <- DARK: " + (TalentIsStructurallyDead(def, talent)
                                                            ? "cannot land" : TalentGate(talent)) : "");
                }

                // Two talents of one hero producing the same fight is not proof of a defect, but it
                // is never what three distinct descriptions are supposed to do.
                for (int a = 1; a <= def.Talents.Count; a++)
                    for (int b = a + 1; b <= def.Talents.Count; b++)
                    {
                        if (!isLive[def.Id + "|" + a] || !isLive[def.Id + "|" + b]) continue;
                        bool same = true;
                        for (int s = 1; s <= TalentSweepSeeds && same; s++)
                            if (FindTalentLine(lines, def.Id, a, s) != FindTalentLine(lines, def.Id, b, s)) same = false;
                        if (same) twins.Add(def.Id + " " + RomanOf(a) + "/" + RomanOf(b));
                    }

                _talentExercise.Add(report);
            }

            // WHAT THIS ONE ARENA LEAVES DARK, printed as the reading it is. It USED to be the
            // assertion, and for weeks it was the build's standing red - "N of 90 talents are
            // EXECUTED but never observed doing anything here" - which everyone learned to read as
            // the one expected failure, so a real regression would have arrived looking exactly
            // like the noise. The number was never the problem; the instrument was. One squad,
            // one enemy line and five seeds cannot raise a kill at the right moment, a Taunt, an
            // enemy that casts or an ally of the right role, and the note under the old red said
            // so itself. The reading stays, because what one shared line cannot raise is still
            // worth knowing; the ASSERTION moved to the matrix below, which is stricter, not
            // quieter.
            Line("  [note] the sweep arena alone leaves " + gated.Count + " of " + talentCount
                 + " talents with a fingerprint identical to leaving them unpicked"
                 + (gated.Count == 0 ? "." : ": " + string.Join(", ", gated.ToArray())));

            // COVERAGE ACROSS THE WHOLE MATRIX, and stricter than the reading above in two ways.
            //
            // It counts a talent only when it CHANGED a fight - the matrix hashes each fight with
            // the talent's own PassiveTrigger announcements taken out, and the reading above does
            // not. Eight talents passed the old check on nothing but announcing themselves: they
            // fired, the announcement moved the fingerprint, and the fight was otherwise the fight
            // they were not picked in. Aeron I fires 154 times across the five sweep seeds and
            // changes nothing.
            //
            // And a talent the sweep cannot raise counts only when a NAMED ROOM proves it under the
            // house pattern: the same seed twice is byte-identical, the control (not picked) fights
            // a different fight, and the room states what moved as a count or an amount the
            // talent's own sentence names. A room fielding a lineup no player can field - a hero
            // twice - is refused, so a talent seen only there has not been seen.
            //
            // What it does not do is go green by counting less. Every talent is in scope, the
            // structurally dead ones included; each one still dark is named with what it waits on,
            // and a stated reason is re-measured on this build rather than remembered.
            List<MatrixRule> matrix = MatrixResults(live);
            List<string> nowhere = new List<string>();
            int sweepSeen = 0, roomSeen = 0;
            if (matrix == null) Check(false, "the arena matrix was built for the talent coverage check");
            else
            {
                for (int i = 0; i < matrix.Count; i++)
                {
                    MatrixRule r = matrix[i];
                    if (r.Kind != MatrixRuleKind.Talent) continue;
                    if (r.InSweep) sweepSeen++;
                    else if (r.RoomPassed) roomSeen++;
                    else nowhere.Add(MatrixDarkLine(r));
                }
                Check(nowhere.Count == 0,
                      nowhere.Count == 0
                        ? "every one of the " + talentCount + " talents is observed changing a fight: " + sweepSeen
                          + " in the sweep arena, " + roomSeen + " only in a named room of THE ARENA MATRIX"
                        : nowhere.Count + " of " + talentCount + " talents are observed changing a fight NOWHERE in"
                          + " the matrix (" + sweepSeen + " in the sweep arena, " + roomSeen + " only in a named room),"
                          + " each with what it waits on: " + string.Join("; ", nowhere.ToArray()));
            }

            // Only among talents that DO something. Two dead talents being identical is the dead
            // check's finding, not this one's, and counting it twice would make this red decorative.
            Check(twins.Count == 0,
                  twins.Count == 0
                    ? "no two LIVE talents of one hero produce the same fight at every seed"
                    : twins.Count + " live talent pair(s) are indistinguishable from each other: "
                      + string.Join(", ", twins.ToArray()));

            string dir = FindToolDir("DevHarness");
            string path = dir == null ? null : Path.Combine(dir, TalentSweepBaselineFile);
            bool regen = !string.IsNullOrEmpty(Environment.GetEnvironmentVariable("EMBERFALL_REGEN_TALENT_SWEEP"));
            if (path == null)
            {
                Line("  [note] Tools/DevHarness not found next to this binary, so the talent sweep could"
                     + " not be compared against its baseline. The " + lines.Count
                     + " fingerprints were still produced.");
                Line("");
                return;
            }
            if (regen || !File.Exists(path))
            {
                WriteTalentSweepBaseline(path, lines);
                Line("  [note] " + (regen ? "EMBERFALL_REGEN_TALENT_SWEEP is set" : "no baseline existed")
                     + " - wrote " + lines.Count + " fingerprints to " + TalentSweepBaselineFile
                     + ". A regenerate is a CLAIM that every moved line was intended.");
                Line("");
                return;
            }
            CompareTalentSweepBaseline(path, lines);
            Line("");
        }

        /// <summary>One run, and the talent's own fire count from it, left in _lastTalentFires.</summary>
        private static int _lastTalentFires;
        private static List<string> _talentExercise;

        private static string RunTalentLine(ContentDatabase arena, StageDef stage, List<HeroDef> fillers,
                                            HeroDef def, int talent, int seed)
        {
            _lastTalentFires = 0;
            List<HeroInstance> team = new List<HeroInstance>();
            HeroInstance subject = MakeInstance(def, 40);
            subject.SelectedTalent = talent;
            team.Add(subject);
            for (int f = 0; f < fillers.Count; f++) team.Add(MakeInstance(fillers[f], 40));
            BattleResult r = RunWith(arena, stage, HeroSweepSeed(def.Id, seed), team);
            if (r == null) return "NULL";

            PassiveDef picked = talent >= 1 ? def.TalentAt(talent) : null;
            if (picked != null && !string.IsNullOrEmpty(picked.Id))
                for (int i = 0; i < r.Events.Count; i++)
                    if (r.Events[i].Type == BattleEventType.PassiveTrigger
                        && r.Events[i].AbilityId == picked.Id) _lastTalentFires++;
            return HeroSweepHash(r);
        }

        private static string FindTalentLine(List<string> lines, string heroId, int talent, int seed)
        {
            string key = heroId + "|" + talent + "|" + seed + "|";
            for (int i = 0; i < lines.Count; i++)
                if (lines[i].StartsWith(key)) return lines[i].Substring(key.Length);
            return null;
        }

        private static string RomanOf(int n) { return n == 1 ? "I" : n == 2 ? "II" : n == 3 ? "III" : n.ToString(); }

        /// <summary>
        /// What a talent IS, because "executed" means three different things across the roster: a
        /// talent carrying its own trigger fires like any passive and can be counted; one carrying
        /// appends or overrides never fires at all and is only visible in the fight it changes.
        /// </summary>
        private static string TalentShape(PassiveDef t)
        {
            if (t == null) return "[missing]";
            List<string> parts = new List<string>();
            if (t.Trigger != PassiveTrigger.None && t.Effects.Count > 0) parts.Add("passive");
            if (t.Overrides.Count > 0) parts.Add("overrides");
            if (t.Appends.Count > 0) parts.Add("appends");
            if (parts.Count == 0) return "[EMPTY]";
            return "[" + string.Join("+", parts.ToArray()) + "]";
        }

        private static bool TalentIsPassiveShaped(PassiveDef t)
        {
            return t != null && t.Trigger != PassiveTrigger.None && t.Effects.Count > 0;
        }

        private static void WriteTalentSweepBaseline(string path, List<string> lines)
        {
            List<string> outp = new List<string>();
            outp.Add("# Authored-talent sweep. One line per hero, talent and seed, in the same arena");
            outp.Add("# and at the same seeds as hero-sweep-baseline.txt, with that talent SELECTED.");
            outp.Add("# heroId|talent|seed|fingerprint");
            outp.Add("#");
            outp.Add("# A line moving is a behaviour change in that talent and needs a stated reason in");
            outp.Add("# the commit that moves it, NOT a regenerate. Regenerate with");
            outp.Add("# EMBERFALL_REGEN_TALENT_SWEEP=1.");
            for (int i = 0; i < lines.Count; i++) outp.Add(lines[i]);
            File.WriteAllLines(path, outp.ToArray());
        }

        private static void CompareTalentSweepBaseline(string path, List<string> lines)
        {
            Dictionary<string, string> baseline = new Dictionary<string, string>();
            string[] raw = File.ReadAllLines(path);
            for (int i = 0; i < raw.Length; i++)
            {
                string t = raw[i].Trim();
                if (t.Length == 0 || t[0] == '#') continue;
                int cut = t.LastIndexOf('|');
                if (cut <= 0) continue;
                baseline[t.Substring(0, cut)] = t.Substring(cut + 1);
            }
            List<string> moved = new List<string>();
            List<string> added = new List<string>();
            Dictionary<string, bool> seen = new Dictionary<string, bool>();
            for (int i = 0; i < lines.Count; i++)
            {
                int cut = lines[i].LastIndexOf('|');
                string key = lines[i].Substring(0, cut);
                string hash = lines[i].Substring(cut + 1);
                seen[key] = true;
                string was;
                if (!baseline.TryGetValue(key, out was)) { added.Add(key); continue; }
                if (was != hash) moved.Add(key);
            }
            List<string> gone = new List<string>();
            foreach (KeyValuePair<string, string> kv in baseline)
                if (!seen.ContainsKey(kv.Key)) gone.Add(kv.Key);

            Check(moved.Count == 0,
                  moved.Count == 0
                    ? "all " + lines.Count + " talent fingerprints match " + TalentSweepBaselineFile
                    : moved.Count + " of " + lines.Count + " talent fingerprints MOVED: "
                      + string.Join(", ", moved.ToArray()));
            Check(added.Count == 0,
                  added.Count == 0
                    ? "no talent entry is missing from the baseline"
                    : added.Count + " talent entr(ies) are not in the baseline: "
                      + string.Join(", ", added.ToArray()));
            Check(gone.Count == 0,
                  gone.Count == 0
                    ? "no baseline entry has lost its talent"
                    : gone.Count + " baseline entr(ies) no longer exist: "
                      + string.Join(", ", gone.ToArray()));
        }

        /// <summary>
        /// The talent half of the exercise report, printed rather than summarised: one line per
        /// hero naming each talent's SHAPE, how often it fired if it is the kind that can fire, and
        /// how many of the five seeds it changed. A talent reading "moved 0/5" did nothing.
        /// </summary>
        private static void ReportTalentExercise()
        {
            Line("AUTHORED-TALENT EXERCISE (what each talent IS, and what it did when it was picked)");
            Line("                         [passive] fires on its own trigger and is counted; [appends]");
            Line("                         and [overrides] never fire - they are only visible in the");
            Line("                         fight they change, which is what 'moved' counts.");
            if (_talentExercise == null) { Line("  [note] the talent sweep did not run"); Line(""); return; }
            for (int i = 0; i < _talentExercise.Count; i++) Line("  " + _talentExercise[i]);
            Line("");
        }

      private static void CheckAuthoredHeroSweep(ContentDatabase live)
        {
            Line("AUTHORED-HERO SWEEP (every authored kit in one fixed arena, against a committed baseline)");

            List<HeroDef> authored = new List<HeroDef>();
            int placeholders = 0;
            for (int i = 0; i < live.Heroes.Count; i++)
            {
                HeroDef h = live.Heroes[i];
                if (h.BasicAttack != null && h.BasicAttack.Id.Contains("placeholder")) { placeholders++; continue; }
                authored.Add(h);
            }
            authored.Sort(delegate (HeroDef a, HeroDef b) { return string.CompareOrdinal(a.Id, b.Id); });
            Check(authored.Count > 0,
                  authored.Count + " authored hero(es) in the sweep, " + placeholders + " placeholder(s) skipped");
            if (authored.Count == 0) { Line(""); return; }

            ContentDatabase arena = BuildHeroSweepArena(live);
            if (arena == null) { Check(false, "hero-sweep arena built"); Line(""); return; }
            List<HeroDef> fillers = BuildHeroSweepFillers();
            if (fillers == null) { Check(false, "hero-sweep neutral fillers built"); Line(""); return; }
            StageDef stage = arena.GetStage("sweep_arena");
            if (stage == null) { Check(false, "hero-sweep stage resolved"); Line(""); return; }

            List<string> lines = new List<string>();
            int runsWithAKill = 0;
            int stragglerProbe = -1;
            List<string> noKill = new List<string>();
            for (int h = 0; h < authored.Count; h++)
            {
                for (int s = 1; s <= HeroSweepSeeds; s++)
                {
                    List<HeroInstance> team = new List<HeroInstance>();
                    team.Add(MakeInstance(authored[h], 40));
                    for (int f = 0; f < fillers.Count; f++) team.Add(MakeInstance(fillers[f], 40));
                    BattleResult r = RunWith(arena, stage, HeroSweepSeed(authored[h].Id, s), team);
                    lines.Add(authored[h].Id + "|" + s + "|" + (r == null ? "NULL" : HeroSweepHash(r)));
                    if (r != null && EnemyDeaths(r) > 0) runsWithAKill++;
                    else if (r != null) noKill.Add(authored[h].Id + "|" + s);
                    if (r != null && stragglerProbe < 0) stragglerProbe = DamageTo(r, "SweepStraggler");
                }
            }

            // AND SOMETHING HAS TO DIE IN IT. Until the straggler was added nothing ever did:
            // every body in the line had 180,000 HP or more, so OnEnemyDefeated was raised in none
            // of these runs and three shipped passives were unreachable. Asserted per run rather
            // than in aggregate, because one hero failing to finish it is exactly the failure mode
            // the straggler's HP is tuned against.
            Check(noKill.Count == 0,
                  noKill.Count == 0
                    ? "an enemy dies in all " + runsWithAKill + " sweep runs, so every authored kit "
                      + "is measured against a defeat as well as against a fight"
                    : noKill.Count + " sweep run(s) killed nothing [first run put "
                      + stragglerProbe + " damage into the straggler], so the defeat-triggered "
                      + "clauses are unreachable in them: " + string.Join(", ", noKill.ToArray()));

            // THE SWEEP HAS TO MEASURE ITS SUBJECT, not the four bodies standing next to it. If
            // two heroes produced the same fingerprint for the same seed, their lines would be
            // reporting on the fillers and the arena rather than on either kit, and a kit could
            // change without its line moving. Asserted per seed rather than across the whole file,
            // because two seeds of one hero SHOULD differ and comparing them all together would
            // confuse the two questions.
            int collisions = 0;
            List<string> collided = new List<string>();
            for (int s = 1; s <= HeroSweepSeeds; s++)
            {
                Dictionary<string, string> seenHash = new Dictionary<string, string>();
                for (int i = 0; i < lines.Count; i++)
                {
                    string[] parts = lines[i].Split('|');
                    if (parts.Length != 3 || parts[1] != s.ToString()) continue;
                    string owner;
                    if (seenHash.TryGetValue(parts[2], out owner))
                    {
                        collisions++;
                        collided.Add(owner + " / " + parts[0] + " (seed " + s + ")");
                        continue;
                    }
                    seenHash[parts[2]] = parts[0];
                }
            }
            Check(collisions == 0,
                  collisions == 0
                    ? "every authored hero fingerprints differently from every other at the same seed"
                      + " - each line measures its own subject rather than the squad around it"
                    : collisions + " hero pair(s) share a fingerprint at the same seed, so those lines"
                      + " are not measuring their subject: " + string.Join(", ", collided.ToArray()));

            string dir = FindToolDir("DevHarness");
            string path = dir == null ? null : Path.Combine(dir, HeroSweepBaselineFile);
            bool regen = !string.IsNullOrEmpty(Environment.GetEnvironmentVariable("EMBERFALL_REGEN_HERO_SWEEP"));

            if (path == null)
            {
                Line("  [note] Tools/DevHarness not found next to this binary, so the sweep could not"
                     + " be compared against its baseline. The " + lines.Count + " fingerprints were"
                     + " still produced.");
                Line("");
                return;
            }

            if (regen || !File.Exists(path))
            {
                WriteHeroSweepBaseline(path, lines);
                Line("  [note] " + (regen ? "EMBERFALL_REGEN_HERO_SWEEP is set" : "no baseline existed")
                     + " - wrote " + lines.Count + " fingerprints to " + HeroSweepBaselineFile
                     + ". A regenerate is a CLAIM that every moved line was intended; the diff is the"
                     + " record of what was claimed.");
                Line("");
                return;
            }

            CompareHeroSweepBaseline(path, lines);
            Line("  [note] This covers each hero's behaviour IN THIS ARENA - one squad, one enemy"
                 + " line, five seeds. A clause that needs a Taunt enemy, a particular aspect"
                 + " matchup, a second copy of its own hero or an ally it does not have here is"
                 + " still unmeasured. It raises coverage from the three starters the stage sweep"
                 + " fields to all " + authored.Count + " authored kits; it is not proof that a kit"
                 + " does everything its description says.");
            Line("");
        }


        // ---- the two donor picks: who GIVES, rather than who receives -------------------------

        /// <summary>
        /// A REDISTRIBUTION NEEDS TWO NAMES AND THE ENUM ONLY HAD ONE OF THEM.
        ///
        /// `LowestEnergyAlly` has been here since the stat-status pass and says who RECEIVES.
        /// Nothing said who gives, so "transfer Energy from the fullest bar to the emptiest" could
        /// not be authored at all - not tuned down, not approximated, not expressible. The same
        /// hole on the other resource: `ShieldTransfer` moves a pool between the caster and its
        /// target, and "whichever ally happens to hold the most" had no name, so a kit that moves
        /// wards about rather than granting them had no donor to point at.
        ///
        /// `HighestEnergyAlly` and `LargestShieldAlly` close both, and they are the ONLY engine
        /// addition in this batch. Two checks each, and deliberately both kinds:
        ///
        ///   - the arena, which proves the mode reads what it claims to read. A mode that silently
        ///     resolved to the front body would satisfy every content scan ever written.
        ///   - the content confirmation, which names Celen. This is a confirmation rather than a
        ///     dormancy tripwire from the first day, because the modes and the kit that needs them
        ///     land together: the tripwire shape would be red on arrival. It goes red the day
        ///     nothing authors them, which is the standing line every other mechanic here carries.
        /// </summary>
        private static void CheckAllyDonorModes(ContentDatabase live)
        {
            Line("ALLY DONOR PICKS (the fullest Energy bar and the largest Shield pool)");

            Check((int)TargetMode.SwapDelayedUnit == 37,
                  "TargetMode.SwapDelayedUnit still at 37 (got " + (int)TargetMode.SwapDelayedUnit
                  + ") - the two new modes were APPENDED, so no TargetAnchored value moved");
            Check((int)TargetMode.HighestEnergyAlly == 38 && (int)TargetMode.LargestShieldAlly == 39,
                  "and the two new modes sit immediately after it at "
                  + (int)TargetMode.HighestEnergyAlly + " and " + (int)TargetMode.LargestShieldAlly);

            CheckHighestEnergyAllyPicks();
            CheckLargestShieldAllyPicks();
            CheckAllyDonorModesAreAuthored(live);

            Line("");
        }

        /// <summary>
        /// Three allies, the caster handed 80 Energy mid-ability, and one Shield aimed with each
        /// Energy mode. They must land on DIFFERENT bodies, or the new member is reading nothing.
        ///
        /// The grant happens inside the same ability as the two picks, for the reason
        /// RunEnergyPickArena records: StartEnergy in the JSON never reaches a CombatUnit, so an
        /// arena that expects content to set up its own difference measures nothing. And the
        /// ability's last effect kills the only enemy, so the whole fight is one turn - otherwise
        /// these wards accumulate over a dozen rounds while the bars fill on their own and the
        /// totals stop being a reading of anything.
        /// </summary>
        private static void CheckHighestEnergyAllyPicks()
        {
            BattleResult r = RunAllyEnergyPickArena();
            if (r == null) { Check(false, "highest-energy ally arena built"); return; }
            int caster = ShieldTo(r, "AeCaster");
            int front = ShieldTo(r, "AeFront");
            int back = ShieldTo(r, "AeBack");
            Check(caster == 4000,
                  "HighestEnergyAlly answers the fullest bar - the body handed 80 Energy takes the "
                  + "4000 ward (" + caster + "), and an ally mode resolving to the caster is "
                  + "correct rather than a miss, exactly as LowestHpAlly does");
            Check(front == 1500 && back == 0,
                  "and LowestEnergyAlly answers a DIFFERENT body in the same ability - the emptiest "
                  + "bar, with the front slot breaking the tie between two allies both at zero ("
                  + front + " forward, " + back + " behind)");
        }

        /// <summary>
        /// Two warded allies, 1000 on the front one and 5000 on the one behind it, and a
        /// ShieldTransfer aimed at LargestShieldAlly. The caster must end holding exactly 5000: a
        /// mode picking by slot, by iteration order or by "first body carrying a Shield" would
        /// hand it 1000, and one picking by HP would too.
        /// </summary>
        private static void CheckLargestShieldAllyPicks()
        {
            BattleResult r = RunLargestShieldArena();
            if (r == null) { Check(false, "largest-shield ally arena built"); return; }
            int moved = ShieldTo(r, "AsCaster");
            Check(moved == 5000,
                  "LargestShieldAlly answers the biggest POOL, not the first body carrying one - "
                  + "the 5000 ward moves and the 1000 one in front of it does not (" + moved + ")");
        }

        /// <summary>The standing line: both modes are reached by shipped content, and it says by
        /// whom. See <see cref="Used"/> for why this is a confirmation rather than a tripwire.</summary>
        private static void CheckAllyDonorModesAreAuthored(ContentDatabase db)
        {
            List<string> energy = new List<string>(), shield = new List<string>();
            List<UnitDef> units = new List<UnitDef>();
            for (int i = 0; i < db.Heroes.Count; i++) units.Add(db.Heroes[i]);
            for (int i = 0; i < db.Enemies.Count; i++) units.Add(db.Enemies[i]);

            for (int i = 0; i < units.Count; i++)
            {
                UnitDef def = units[i];
                List<EffectDef> all = new List<EffectDef>();
                List<string> where = new List<string>();
                if (def.BasicAttack != null)
                    AddWithNames(all, where, def.Id + "/" + def.BasicAttack.Name, def.BasicAttack.Effects);
                if (def.Active != null)
                    AddWithNames(all, where, def.Id + "/" + def.Active.Name, def.Active.Effects);
                for (int p = 0; p < def.Passives.Count; p++)
                    AddWithNames(all, where, def.Id + "/" + def.Passives[p].Name, def.Passives[p].Effects);
                HeroDef hero = def as HeroDef;
                if (hero != null)
                    for (int t = 0; t < hero.Talents.Count; t++)
                        AddWithNames(all, where, def.Id + "/" + hero.Talents[t].Name, hero.Talents[t].Effects);

                for (int e = 0; e < all.Count; e++)
                {
                    EffectDef eff = all[e];
                    if (eff.Target == TargetMode.HighestEnergyAlly
                        || eff.SecondaryTarget == TargetMode.HighestEnergyAlly) energy.Add(where[e]);
                    if (eff.Target == TargetMode.LargestShieldAlly
                        || eff.SecondaryTarget == TargetMode.LargestShieldAlly) shield.Add(where[e]);
                }
            }

            Check(energy.Count > 0, "shipped content targets HighestEnergyAlly" + Used(energy));
            Check(shield.Count > 0, "shipped content targets LargestShieldAlly" + Used(shield));
        }

        /// <summary>Total ShieldGain landed ON one unit, by name. HealTo's sibling: credited by
        /// TARGET rather than by source, because these two checks ask where a ward went.</summary>
        private static int ShieldTo(BattleResult r, string unitName)
        {
            int id = -1;
            for (int i = 0; i < r.Units.Count; i++)
                if (r.Units[i].Name == unitName) { id = r.Units[i].Id; break; }
            if (id < 0) return -1;
            int total = 0;
            for (int i = 0; i < r.Events.Count; i++)
            {
                BattleEvent e = r.Events[i];
                if (e.Type == BattleEventType.ShieldGain && e.TargetId == id) total += e.Value;
            }
            return total;
        }

