        ""effects"": [
          { ""kind"": ""ApplyStatus"", ""target"": ""Self"", ""status"": ""Burn"",
            ""magnitude"": 0.05, ""duration"": 20, ""chance"": 1 },
          { ""kind"": ""ApplyStatus"", ""target"": ""Self"", ""status"": ""Taunt"",
