      ""passive"": { ""id"": ""dr_react"", ""name"": ""Caught It"", ""trigger"": ""OnRedirectReceived"",
        ""oncePerBattle"": false,
        ""effects"": [ { ""kind"": ""EnergyGain"", ""target"": ""Self"", ""flat"": 0 } ] } }
