      ""effects"":[ { ""kind"":""ApplyStatus"", ""target"":""Self"", ""status"":""AttackUp"", ""magnitude"":0.01, ""duration"":1, ""chance"":1,
                      ""condition"":""HasStatus"", ""conditionStatus"":""Ledger"", ""conditionOn"":""BroadcastSubject"" } ] },
