  ""enemies"": [
    { ""id"": ""ri_bulwark"", ""name"": ""RoleBulwark"", ""aspect"": ""Ember"", ""kind"": ""boss"",
      ""hp"": 9000000, ""attack"": 1, ""defense"": 0, ""speed"": 10, ""critChance"": 0, ""critDamage"": 1.0,
      ""basic"": { ""id"": ""rib"", ""name"": ""Wait"",
