    { ""id"": ""ri_striker"", ""name"": ""RoleStriker"", ""aspect"": ""Ember"", ""role"": ""Striker"",
      ""hp"": 9000000, ""attack"": 1, ""defense"": 0, ""speed"": 9, ""critChance"": 0, ""critDamage"": 1.0,
      ""basic"": { ""id"": ""ris"", ""name"": ""Wait"",
        ""effects"": [ { ""kind"": ""Heal"", ""target"": ""Self"", ""flat"": 1 } ] } }
  ]
}";
