        // ================================================================== ACCOUNTS AND CLOUD

        /// <summary>
        /// The half of the accounts feature that can be proved without a network.
        ///
        /// Everything checked here is in Emberfall.Core.Cloud, and it is in Core precisely so it
        /// can be checked here: the conflict rule decides whether a player loses a week of
        /// progress, and a rule like that has to be exercised for every case by something that
        /// runs on every build, not demonstrated once against a live database.
        ///
        /// What is NOT here, and cannot be: whether the database enforces its own half. Row Level
        /// Security, the friend-code trigger and push_save's compare-and-swap are all facts about
        /// a Postgres instance, and Tools/supabase-rules-test.py is what measures those. This
        /// section proves the client cannot lose a save; that script proves the server cannot be
        /// talked into handing one over.
        /// </summary>
        private static void CheckAccounts(ContentDatabase db)
        {
            Line("");
            Line("ACCOUNTS, CLOUD SAVE AND SNAPSHOTS");
            CheckFriendCodeFormat();
            CheckCloudSaveRoundTrip(db);
            CheckSyncDecisions();
            CheckSnapshotFightsTheSame(db);
        }

        /// <summary>
        /// The friend code alphabet, and the two repairs Normalise is allowed to make.
        ///
        /// The interesting assertions are the negative ones. An O is NOT read as a 0 and an I is
        /// NOT read as a 1: those letters are absent from the alphabet because they are ambiguous,
        /// and a silent substitution would turn a mistyped code into a successful lookup of
        /// somebody else's account, which is the one failure this whole alphabet exists to stop.
        /// </summary>
        private static void CheckFriendCodeFormat()
        {
            Check(FriendCode.Alphabet.Length == 30,
                  "the friend code alphabet has 30 symbols (" + FriendCode.Alphabet.Length + ")");
            Check(FriendCode.Alphabet.IndexOf('0') < 0 && FriendCode.Alphabet.IndexOf('1') < 0
                  && FriendCode.Alphabet.IndexOf('I') < 0 && FriendCode.Alphabet.IndexOf('L') < 0
                  && FriendCode.Alphabet.IndexOf('O') < 0 && FriendCode.Alphabet.IndexOf('U') < 0,
                  "0, 1, I, L, O and U are all absent - the pairs that get misread out loud");

            Check(FriendCode.IsValid("ABC234"), "a six-character code from the alphabet is valid");
            Check(!FriendCode.IsValid("ABC23"), "five characters is not a code");
            Check(!FriendCode.IsValid("ABC2345"), "seven characters is not a code");
            Check(!FriendCode.IsValid("ABCO23"), "a code containing O is refused");
            Check(!FriendCode.IsValid(""), "an empty string is not a code");

            Check(FriendCode.Normalise("abc-234") == "ABC234",
                  "lower case and a dash are repaired (" + FriendCode.Normalise("abc-234") + ")");
            Check(FriendCode.Normalise("  ABC 234 ") == "ABC234", "spaces are dropped");
            Check(FriendCode.Normalise("ABCO23") == "",
                  "an O is REFUSED rather than read as a zero - a silent repair would look up the wrong account");
            Check(FriendCode.Normalise("ABC1234") == "", "too many characters normalises to nothing");
            Check(FriendCode.Format("ABC234") == "ABC-234", "a code is shown grouped");
            Check(FriendCode.Normalise(FriendCode.Format("ABC234")) == "ABC234",
                  "and what is shown can be typed straight back in");
        }

        /// <summary>
        /// A save survives the trip through the cloud row shape byte for byte.
        ///
        /// The trip is the whole point: the save is written by SaveSerializer, embedded as a
        /// PARSED value in the push_save body (the column is jsonb, and sending it as a string
        /// would store a JSON string that happens to contain JSON), returned inside a PostgREST
        /// row, and re-serialised out of it. Four format boundaries, any of which could re-order
        /// a key or drop a number's precision, and none of which is allowed to.
        ///
        /// Checked twice over: the document must come back IDENTICAL as text, and it must also
        /// still deserialise into the same profile. The first is the stronger claim and the
        /// second is what a player would actually notice, so neither stands in for the other.
        /// </summary>
        private static void CheckCloudSaveRoundTrip(ContentDatabase db)
        {
            PlayerProfile profile = GameSession.CreateNewProfile(db, 1700000000);
            GameSession session = new GameSession(db, profile);
            session.LevelUpHero(profile.Heroes[0], 6);
            session.GrantBattleResult(db.AllStages[0], true, 1700000100);
            session.Summon(9182, 1700000200);

            string local = SaveSerializer.Serialize(profile);

            // The body the client posts to push_save.
            string body = CloudSaveCodec.WritePushBody(3, SaveSerializer.CurrentVersion, "device-a", local);
            JsonValue parsedBody;
            string bodyError;
            bool bodyParses = JsonValue.TryParse(body, out parsedBody, out bodyError);
            Check(bodyParses && parsedBody != null && parsedBody.IsObject,
                  "the push_save body is a JSON object");
            Check(bodyParses && parsedBody["p_data"] != null && parsedBody["p_data"].IsObject,
                  "the save travels as a JSON OBJECT, not as a string containing JSON - the column is jsonb");
            Check(bodyParses && parsedBody.GetInt("p_expected_revision", -1) == 3,
                  "the expected revision is carried as sent");

            // The row PostgREST hands back, built the way the server would: `data` is a jsonb
            // VALUE, so it is the parsed document rather than a quoted string.
            JsonValue row = JsonValue.NewObject();
            row.Set("user_id", "00000000-0000-0000-0000-00000000beef");
            row.Set("save_version", SaveSerializer.CurrentVersion);
            row.Set("revision", 4);
            row.Set("device_id", "device-a");
            row.Set("updated_at", "2026-09-21T11:00:00+00:00");
            row.Set("data", parsedBody["p_data"]);
            JsonValue rows = JsonValue.NewArray();
            rows.Add(row);

            CloudSaveRecord record = CloudSaveCodec.ReadFirstRow(rows.ToJson(false));
            Check(record != null, "a PostgREST row reads back as a cloud save record");
            if (record == null) return;

            Check(record.Revision == 4 && record.SaveVersion == SaveSerializer.CurrentVersion,
                  "revision and save version survive the row (" + record.Revision + ", v" + record.SaveVersion + ")");
            Check(record.DeviceId == "device-a", "the device id survives the row");

            // NOT a text comparison, and the reason is worth stating because the obvious test is
            // the wrong one. SaveSerializer writes pretty-printed JSON, and `data` is jsonb: a
            // real Postgres column parses the document and re-renders it, discarding whitespace
            // and imposing its own key order. Textual identity is therefore not merely untrue
            // here, it is not a property the storage HAS - a test asserting it would fail against
            // a correct server and could only be satisfied by giving up jsonb for text, which
            // would give up the ability to ever query inside a save.
            //
            // What must survive is the SAVE, so that is what is measured: the document
            // deserialises, and the profile it produces re-serialises to the original byte for
            // byte. That tolerates exactly what jsonb legitimately does and catches everything
            // else - a dropped key, a truncated number, a mangled string - because the re-write
            // goes through the one writer whose key order is fixed.
            string error;
            PlayerProfile back = SaveSerializer.Deserialize(record.Data, db, out error);
            Check(back != null && error == null,
                  "the save deserialises out of the cloud row" + (error != null ? " (" + error + ")" : ""));
            if (back == null) return;

            string rewritten = SaveSerializer.Serialize(back);
            Check(rewritten == local,
                  "AND RE-SERIALISES TO THE ORIGINAL BYTE FOR BYTE - the round trip through jsonb is lossless ("
                  + rewritten.Length + " vs " + local.Length + " chars)"
                  + (rewritten == local ? "" : "; first difference: " + FirstDifference(local, rewritten)));
            Check(back.Gold == profile.Gold && back.PlayerLevel == profile.PlayerLevel
                  && back.Heroes.Count == profile.Heroes.Count && back.StagesCleared == profile.StagesCleared,
                  "into the same profile (gold " + back.Gold + ", level " + back.PlayerLevel
                  + ", " + back.Heroes.Count + " heroes)");

            // The lossless claim above is only worth anything if this comparison can fail. One
            // coin off the purse is the smallest thing a bad round trip could lose.
            back.Gold += 1;
            Check(SaveSerializer.Serialize(back) != local,
                  "and one gold piece changes the re-serialised text, so that comparison can fail");
            back.Gold -= 1;

            // An empty PostgREST array is what "no cloud save yet" actually looks like on the
            // wire - not a 404 - and reading it as anything but "no record" would turn a first
            // launch into a conflict.
            Check(CloudSaveCodec.ReadFirstRow("[]") == null, "an empty result reads as no cloud save");
            Check(CloudSaveCodec.ReadFirstRow("{ not json") == null,
                  "a malformed body reads as no cloud save rather than throwing");

            SaveSummary summary = SaveSummaryReader.From(local);
            Check(summary.Readable && summary.PlayerLevel == profile.PlayerLevel
                  && summary.StagesCleared == profile.StagesCleared
                  && summary.HeroesOwned == profile.Heroes.Count,
                  "the conflict card's summary reads the save without deserialising it ("
                  + summary.Describe() + ")");
            Check(!SaveSummaryReader.From("{ not json").Readable,
                  "and an unreadable document summarises as unreadable rather than as an empty account");
        }

        /// <summary>
        /// Every case of the conflict decision, including the ones that must NOT resolve
        /// themselves.
        ///
        /// This is the check the whole feature turns on. Two rules are being asserted: nothing is
        /// ever silently overwritten, and a save from a newer build is refused rather than read.
        /// The second is the same refusal SaveSerializer.Deserialize already makes locally, moved
        /// one step earlier so it happens before the document is parsed - which is why
        /// save_version is a column of its own in the database rather than a field inside the blob.
        /// </summary>
        private static void CheckSyncDecisions()
        {
            int reader = SaveSerializer.CurrentVersion;

            SyncInputs nothing = new SyncInputs();
            nothing.ReaderVersion = reader;
            Check(SyncPlanner.Decide(nothing).Action == SyncAction.NothingToDo,
                  "no local save and no cloud save: nothing to do");

            SyncInputs firstUpload = new SyncInputs();
            firstUpload.HasLocal = true;
            firstUpload.ReaderVersion = reader;
            Check(SyncPlanner.Decide(firstUpload).Action == SyncAction.UploadLocal,
                  "a local save and no cloud save: upload");
            Check(SyncPlanner.ExpectedRevisionForUpload(firstUpload) == 0,
                  "and it claims revision 0, which is push_save's 'there is no row yet'");

            SyncInputs freshDevice = new SyncInputs();
            freshDevice.ReaderVersion = reader;
            freshDevice.HasCloud = true;
            freshDevice.CloudSaveVersion = reader;
            freshDevice.CloudRevision = 7;
            Check(SyncPlanner.Decide(freshDevice).Action == SyncAction.DownloadCloud,
                  "a cloud save and no local save: download");

            SyncInputs inStep = new SyncInputs();
            inStep.HasLocal = true;
            inStep.ReaderVersion = reader;
            inStep.HasCloud = true;
            inStep.CloudSaveVersion = reader;
            inStep.CloudRevision = 7;
            inStep.BaseRevision = 7;
            Check(SyncPlanner.Decide(inStep).Action == SyncAction.UploadLocal,
                  "the cloud is at the revision this device last synced: upload, local descends from it");
            Check(SyncPlanner.ExpectedRevisionForUpload(inStep) == 7,
                  "and it claims revision 7, which push_save checks against what is stored");

            SyncInputs cloudMoved = new SyncInputs();
            cloudMoved.HasLocal = true;
            cloudMoved.ReaderVersion = reader;
            cloudMoved.HasCloud = true;
            cloudMoved.CloudSaveVersion = reader;
            cloudMoved.CloudRevision = 9;
            cloudMoved.BaseRevision = 7;
            Check(SyncPlanner.Decide(cloudMoved).Action == SyncAction.AskPlayer,
                  "the cloud has moved past this device: ASK, never merge and never pick");

            SyncInputs neverSynced = new SyncInputs();
            neverSynced.HasLocal = true;
            neverSynced.ReaderVersion = reader;
            neverSynced.HasCloud = true;
            neverSynced.CloudSaveVersion = reader;
            neverSynced.CloudRevision = 3;
            neverSynced.BaseRevision = 0;
            Check(SyncPlanner.Decide(neverSynced).Action == SyncAction.AskPlayer,
                  "local progress on a device that has never synced, against an existing cloud save: ASK");

            SyncInputs cloudBehind = new SyncInputs();
            cloudBehind.HasLocal = true;
            cloudBehind.ReaderVersion = reader;
            cloudBehind.HasCloud = true;
            cloudBehind.CloudSaveVersion = reader;
            cloudBehind.CloudRevision = 4;
            cloudBehind.BaseRevision = 9;
            Check(SyncPlanner.Decide(cloudBehind).Action == SyncAction.AskPlayer,
                  "the cloud went BACKWARDS - restored or rebuilt - so even though local looks newer: ASK");

            SyncInputs newerBuild = new SyncInputs();
            newerBuild.HasLocal = true;
            newerBuild.ReaderVersion = reader;
            newerBuild.HasCloud = true;
            newerBuild.CloudSaveVersion = reader + 1;
            newerBuild.CloudRevision = 7;
            newerBuild.BaseRevision = 2;
            Check(SyncPlanner.Decide(newerBuild).Action == SyncAction.RefuseCloudNewerVersion,
                  "a cloud save from a NEWER build is refused, not downloaded and not overwritten");

            // The ordering assertion, and it is not a formality. This device is in step with the
            // cloud, which on its own says "upload" - and uploading would destroy a save written
            // by a build that knows more than this one. The version gate has to be reached first.
            SyncInputs newerButInStep = newerBuild;
            newerButInStep.BaseRevision = newerButInStep.CloudRevision;
            Check(SyncPlanner.Decide(newerButInStep).Action == SyncAction.RefuseCloudNewerVersion,
                  "and the version refusal outranks the in-step upload, so a downgraded build cannot overwrite a newer save");

            SyncInputs olderCloud = new SyncInputs();
            olderCloud.HasLocal = true;
            olderCloud.ReaderVersion = reader;
            olderCloud.HasCloud = true;
            olderCloud.CloudSaveVersion = 1;
            olderCloud.CloudRevision = 2;
            olderCloud.BaseRevision = 2;
            Check(SyncPlanner.Decide(olderCloud).Action == SyncAction.UploadLocal,
                  "a cloud save from an OLDER build is readable, so the ordinary rules apply");
        }

        /// <summary>
        /// A line published to the cloud and fetched back fights EXACTLY the fight the same line
        /// fights locally.
        ///
        /// This is the claim the friendly duel rests on, and it is the reason a duel needs no
        /// server logic at all. CombatSimulation is a pure function of its request, so if the
        /// snapshot survives the trip without moving a number, then the fight resolved on this
        /// device against a fetched line is the same fight the other player's device would
        /// resolve - and the fingerprint is how that is measured rather than asserted.
        ///
        /// The comparison is the full event record, not the outcome: two fights that both end in
        /// a win can still differ in every blow, and it is the blows that would reveal a snapshot
        /// that dropped an armor substat or rounded a level.
        /// </summary>
        private static void CheckSnapshotFightsTheSame(ContentDatabase db)
        {
            PlayerProfile profile = GameSession.CreateNewProfile(db, 1700000000);
            GameSession session = new GameSession(db, profile);

            // A line worth taking a snapshot OF: levelled, and more heroes than the starters, so
            // the walk has real slots to resolve. A team of bare level-1 heroes would round-trip
            // trivially and prove much less.
            session.Summon(4242, 1700000200);
            session.Summon(9001, 1700000300);
            for (int i = 0; i < profile.Heroes.Count; i++) session.LevelUpHero(profile.Heroes[i], 4 + i);
            profile.NormaliseTeam();

            List<HeroInstance> team = profile.TeamHeroes();
            Check(team.Count > 0, "the snapshot test has a team to publish (" + team.Count + ")");
            if (team.Count == 0) return;

            // Talents, written straight onto the instances rather than through SelectTalent, which
            // is the selection RULE's path and not this check's subject.
            //
            // Not decoration, and not free. Thirty shipped heroes author three talents each, so
            // these selections are LIVE - they resolve through TalentAt on both sides and change
            // the fight. That is deliberate: the whole claim below is that a line published to the
            // cloud fights the fight it names, and a line where every unit agreed about zero would
            // have proved that claim for the one case where the new field cannot possibly be
            // wrong. With talents set, the round trip is carrying something, and the fingerprint
            // comparison is carrying it into a battle.
            int running = 0;
            for (int i = 0; i < team.Count; i++)
            {
                team[i].SelectedTalent = (i % HeroDef.MaxTalents) + 1;
                // Ascended far enough to run the slot it was handed, because a snapshot publishes
                // HeroInstance.LiveTalentSelection and a tier-0 body would publish a zero for
                // slots 2 and 3. The count below is of what ACTUALLY publishes, not of what the
                // def happens to author, so the gate cannot quietly empty this line and leave the
                // round trip agreeing about nothing again.
                team[i].Ascension = HeroInstance.TierUnlockingTalent(team[i].SelectedTalent);
                if (team[i].LiveTalentSelection != 0) running++;
            }
            Check(running > 0,
                  "at least one hero in the published line is running a talent that RESOLVES, so the round trip "
                  + "below is carrying something into a real fight rather than agreeing about zero ("
                  + running + " of " + team.Count + ")");

            TeamSnapshot published = TeamSnapshotBuilder.From(db, profile, "Pinoy");
            Check(published.Units.Count == team.Count,
                  "the snapshot carries every deployed hero (" + published.Units.Count + " of " + team.Count + ")");
            Check(published.PowerScore > 0, "and its power is resolved at publish time (" + published.PowerScore + ")");

            // Through the wire: the units array as the jsonb column would hold it, and back.
            JsonValue units = TeamSnapshotCodec.WriteUnits(published);
            TeamSnapshot fetched = TeamSnapshotCodec.Read(JsonValue.Parse(units.ToJson(false)),
                                                          published.Label, published.PowerScore);

            Check(fetched.Units.Count == published.Units.Count,
                  "every unit survives the column (" + fetched.Units.Count + ")");

            bool fieldsMatch = fetched.Label == published.Label && fetched.PowerScore == published.PowerScore;
            int armorPieces = 0;
            for (int i = 0; i < published.Units.Count && fieldsMatch; i++)
            {
                SnapshotUnit a = published.Units[i];
                SnapshotUnit b = fetched.Units[i];
                armorPieces += a.Armor.Count;
                if (a.DefId != b.DefId || a.Level != b.Level || a.Stars != b.Stars
                    || a.RelicId != b.RelicId || a.SelectedTalent != b.SelectedTalent
                    || a.Armor.Count != b.Armor.Count) fieldsMatch = false;
                for (int p = 0; p < a.Armor.Count && fieldsMatch; p++)
                {
                    if (SaveSerializer.WriteArmorPieceJson(a.Armor[p]).ToJson(false)
                        != SaveSerializer.WriteArmorPieceJson(b.Armor[p]).ToJson(false)) fieldsMatch = false;
                }
            }
            Check(fieldsMatch, "and every field of every unit, armor rolls included, is unchanged ("
                  + armorPieces + " armor piece(s) carried by value)");

            // And the selection reaches the type the SIMULATION consumes, which is the step the
            // field comparison above cannot see: SnapshotUnit and LoadoutUnit are different types
            // and ToLoadout is the only thing that joins them.
            BattleLoadout asFought = fetched.ToLoadout();
            bool talentsReachedTheLoadout = asFought.Units.Count == fetched.Units.Count;
            for (int i = 0; i < asFought.Units.Count && talentsReachedTheLoadout; i++)
                if (asFought.Units[i].SelectedTalent != fetched.Units[i].SelectedTalent)
                    talentsReachedTheLoadout = false;
            Check(talentsReachedTheLoadout,
                  "and every selection arrives on the LOADOUT the simulation consumes - ToLoadout is the only "
                  + "join between the snapshot's unit and the combat one, so a drop here would be invisible to "
                  + "every check above it");

            // The fight itself. Same stage, same seed, same player side - the only difference is
            // which object the far side was built from.
            StageDef arena = ProvingGenerator.BuildStage();
            const int Seed = 771144;
            BattleResult local = CombatSimulation.Run(session.BuildProvingRequest(arena, published.ToLoadout(), Seed));
            BattleResult remote = CombatSimulation.Run(session.BuildProvingRequest(arena, fetched.ToLoadout(), Seed));

            Check(local != null && remote != null && local.Events.Count > 0, "both duels resolved to a real record");
            if (local == null || remote == null) return;

            Check(FingerprintOf(local) == FingerprintOf(remote),
                  "A DUEL AGAINST A FETCHED LINE IS THE SAME FIGHT, EVENT FOR EVENT, as one against the local line ("
                  + local.Events.Count + " events, " + local.Rounds + " rounds)");

            // And the fingerprint is capable of noticing a difference, which is what stops the
            // check above from being satisfied by two empty records. One hero's level moved by
            // one is the smallest change a snapshot could get wrong.
            fetched.Units[0].Level += 1;
            BattleResult nudged = CombatSimulation.Run(session.BuildProvingRequest(arena, fetched.ToLoadout(), Seed));
            Check(FingerprintOf(nudged) != FingerprintOf(local),
                  "and moving ONE hero's level by one changes the record, so the comparison above can fail");

            Check(!published.ToLoadout().IsGhost,
                  "a duel line is not flagged as a ghost - that flag means 'your own former line', which this is not");
        }

        // ================================================================== GUILDS

        /// <summary>
        /// The guild rules that can be proved without a network, plus one that compares this side
        /// against the other.
        ///
        /// WHAT IS HERE IS EVERYTHING THAT DECIDES WHAT A SCREEN OFFERS. The permission matrix
        /// decides whether a member is shown a Promote button, the validators decide whether a
        /// message is sent at all, and the codec decides what a roster row says about who may
        /// remove whom - and every one of those is a decision made before a request exists, so
        /// every one of them is checkable here.
        ///
        /// WHAT IS NOT HERE, AND CANNOT BE: whether the database agrees. Row Level Security, the
        /// cap's row lock and the chat rate limit are facts about a Postgres instance, and
        /// Tools/supabase-guild-rules-test.py is what measures those against a real project. This
        /// section proves the client offers the right things; that script proves the server
        /// refuses the wrong ones with this code out of the way entirely.
        ///
        /// The LAST check is the join between the two, and it is the reason this takes a path: the
        /// client's copies of the cap, the name bounds, the message ceiling and the chat cooldown
        /// are duplicated from the migrations on purpose - neither can be the other's source - and
        /// a duplicate nobody compares is a lie waiting to happen. So it reads the SQL.
        /// </summary>
        private static void CheckGuilds(string contentDir)
        {
            Line("");
            Line("GUILDS - the client half, and whether it still agrees with the migrations");
            CheckGuildCodeFormat();
            CheckGuildRoleMatrix();
            CheckGuildTypedInput();
            CheckDisplayNameRules();
            CheckGuildChatWindow();
            CheckGuildRowReading();
            CheckGuildConstantsMatchTheMigrations(contentDir);
        }

        /// <summary>
        /// A guild code is a friend code's alphabet, and this asserts it rather than assuming it.
        ///
        /// The interesting assertion is that the two are the SAME function. GuildRules could have
        /// grown its own normaliser - the two codes are different things and live in different
        /// tables - and the moment it did, one of them would have been fixed without the other.
        /// The alphabet exists because of how people read six characters aloud, which is identical
        /// for both, so there is one reader and this is the check that says so.
        /// </summary>
        private static void CheckGuildCodeFormat()
        {
            Check(GuildRules.NormaliseCode("abc-234") == "ABC234",
                  "a guild code repairs case and a dash, exactly as a friend code does ("
                  + GuildRules.NormaliseCode("abc-234") + ")");
            Check(GuildRules.IsValidCode("ABC234"), "six characters from the alphabet is a guild code");
            Check(!GuildRules.IsValidCode("ABC23"), "five characters is not");
            Check(!GuildRules.IsValidCode("ABC2345"), "seven characters is not");
            Check(!GuildRules.IsValidCode("ABCO23"), "and a code containing O is refused");
            Check(GuildRules.NormaliseCode("ABC0I1") == "",
                  "0, I and 1 are NOT read as O, I and L - a mistyped guild code is an error, never "
                  + "a successful lookup of a different guild");
            Check(GuildRules.FormatCode("ABC234") == "ABC-234", "a guild code is shown grouped");
            Check(GuildRules.NormaliseCode(GuildRules.FormatCode("ABC234")) == "ABC234",
                  "and what is shown can be typed straight back in");

            // The one that matters if these ever fork.
            Check(GuildRules.NormaliseCode("qr-s789") == FriendCode.Normalise("qr-s789")
                  && GuildRules.IsValidCode("QRS789") == FriendCode.IsValid("QRS789"),
                  "guild codes and friend codes are read by ONE implementation, not two agreeing ones");
        }

        /// <summary>
        /// The whole permission matrix, as a table rather than as the cases a screen happens to
        /// use.
        ///
        /// Written as a fingerprint over every combination, because the failure this is guarding
        /// against is not "Promote is broken" - that would be noticed - but "somebody widened one
        /// clause and an officer can now remove an officer". A per-case list would have to
        /// anticipate which cell moved; a table notices any of them.
        ///
        /// The named checks under it are the cells whose value is load-bearing enough to be worth
        /// reading in the output, and each one restates a policy in 0004 by name.
        /// </summary>
        private static void CheckGuildRoleMatrix()
        {
            GuildRole[] roles = { GuildRole.None, GuildRole.Member, GuildRole.Officer, GuildRole.Leader };
            StringBuilder table = new StringBuilder();
            for (int m = 0; m < roles.Length; m++)
            {
                for (int t = 0; t < roles.Length; t++)
                {
                    for (int s = 0; s < 2; s++)
                    {
                        bool self = s == 1;
                        table.Append(GuildRules.CanRemove(roles[m], roles[t], self) ? '1' : '0');
                        table.Append(GuildRules.CanPromote(roles[m], roles[t], self) ? '1' : '0');
                        table.Append(GuildRules.CanDemote(roles[m], roles[t], self) ? '1' : '0');
                        table.Append(GuildRules.CanMakeLeader(roles[m], roles[t], self) ? '1' : '0');
                    }
                }
            }

            // None/Member/Officer/Leader x the same x not-self,self, four verbs each. Recorded as
            // a literal so ANY cell moving fails this line, not only the ones somebody thought of.
            const string Expected =
                "0000" + "0000" + "0000" + "0000" + "0000" + "0000" + "0000" + "0000" +
                "0000" + "0000" + "0000" + "0000" + "0000" + "0000" + "0000" + "0000" +
                "0000" + "0000" + "1000" + "0000" + "0000" + "0000" + "0000" + "0000" +
                "0000" + "0000" + "1101" + "0000" + "1011" + "0000" + "0000" + "0000";
            Check(table.ToString() == Expected,
                  "the whole role matrix is unchanged - 32 combinations, four verbs each"
                  + (table.ToString() == Expected ? "" : " (got " + table + ")"));

            Check(GuildRules.CanRemove(GuildRole.Officer, GuildRole.Member, false)
                  && !GuildRules.CanRemove(GuildRole.Officer, GuildRole.Officer, false),
                  "AN OFFICER MAY REMOVE A MEMBER AND NOT A PEER - guild_members_remove_by_officer's "
                  + "whole distinction");
            Check(!GuildRules.CanRemove(GuildRole.Leader, GuildRole.Leader, false)
                  && !GuildRules.CanRemove(GuildRole.Officer, GuildRole.Leader, false),
                  "and NOBODY may remove a leader, including a leader");
            Check(GuildRules.CanLeave(GuildRole.Member) && GuildRules.CanLeave(GuildRole.Officer)
                  && !GuildRules.CanLeave(GuildRole.Leader),
                  "a leader cannot leave - guild_members_leave_self carries role <> 'leader', which "
                  + "is the whole of 'transfer or disband first'");
            Check(GuildRules.CanSetRoles(GuildRole.Leader) && !GuildRules.CanSetRoles(GuildRole.Officer),
                  "only the leader changes a role");
            Check(GuildRules.CanDisband(GuildRole.Leader) && !GuildRules.CanDisband(GuildRole.Officer),
                  "only the leader disbands");
            Check(GuildRules.CanAnswerRequests(GuildRole.Leader)
                  && GuildRules.CanAnswerRequests(GuildRole.Officer)
                  && !GuildRules.CanAnswerRequests(GuildRole.Member),
                  "a leader or an officer answers requests, and a member does not");

            // THE ONE-GUILD RULE, this side of it. One answer for creating and joining because it
            // is one constraint: guild_members.user_id is a primary key.
            Check(GuildRules.CanJoinOrCreate(GuildRole.None)
                  && !GuildRules.CanJoinOrCreate(GuildRole.Member)
                  && !GuildRules.CanJoinOrCreate(GuildRole.Officer)
                  && !GuildRules.CanJoinOrCreate(GuildRole.Leader),
                  "A PLAYER IN A GUILD CAN NEITHER JOIN NOR CREATE ANOTHER - the same answer for "
                  + "both, because it is the same primary key");

            Check(GuildRules.ParseRole("leader") == GuildRole.Leader
                  && GuildRules.ParseRole("officer") == GuildRole.Officer
                  && GuildRules.ParseRole("member") == GuildRole.Member
                  && GuildRules.ParseRole("") == GuildRole.None
                  && GuildRules.ParseRole("Leader") == GuildRole.None,
                  "a role parses from the wire's own lower-case spelling and from nothing else");
            Check(GuildRules.RoleKey(GuildRole.Officer) == "officer"
                  && GuildRules.RoleKey(GuildRole.None) == "",
                  "and goes back out the way the CHECK constraint accepts it");
        }

        /// <summary>
        /// What a player typed, refused here so they are told before a round trip.
        ///
        /// Every bound is the column's, and the trim matters as much as the length: the guilds
        /// table carries `name = btrim(name)`, so a name with a trailing space is refused by the
        /// database for a reason the player cannot see on their own screen. Validating the TRIMMED
        /// string and sending that is what stops it ever being sent.
        /// </summary>
        private static void CheckGuildTypedInput()
        {
            string cleaned, problem;

            Check(GuildRules.ValidateName("  The Long Watch  ", out cleaned, out problem)
                  && cleaned == "The Long Watch",
                  "a guild name is trimmed before it is measured or sent (\"" + cleaned + "\")");
            Check(!GuildRules.ValidateName("ab", out cleaned, out problem),
                  "two characters is not a guild name");
            Check(!GuildRules.ValidateName("   ab   ", out cleaned, out problem),
                  "and padding it with spaces does not make it one");
            Check(GuildRules.ValidateName(new string('x', GuildRules.NameMax), out cleaned, out problem),
                  GuildRules.NameMax + " characters is the longest name there is");
            Check(!GuildRules.ValidateName(new string('x', GuildRules.NameMax + 1), out cleaned, out problem),
                  "and one more is refused");
            Check(!GuildRules.ValidateName("two\nlines", out cleaned, out problem),
                  "a name carrying a newline is refused - the column refuses [[:cntrl:]] and every "
                  + "label on these screens is single-line");

            Check(GuildRules.ValidateDescription("", out cleaned, out problem),
                  "a description may be empty");
            Check(!GuildRules.ValidateDescription(new string('x', GuildRules.DescriptionMax + 1),
                                                  out cleaned, out problem),
                  "and stops at " + GuildRules.DescriptionMax);

            Check(GuildRules.ValidateMessage("  hello  ", out cleaned, out problem) && cleaned == "hello",
                  "a chat line is trimmed, so what is measured is what is stored");
            Check(!GuildRules.ValidateMessage("   ", out cleaned, out problem),
                  "a line of nothing but spaces is not a message");
            Check(!GuildRules.ValidateMessage(null, out cleaned, out problem),
                  "and neither is nothing at all");
            Check(GuildRules.ValidateMessage(new string('x', GuildRules.MessageMax), out cleaned, out problem),
                  GuildRules.MessageMax + " characters sends");
            Check(!GuildRules.ValidateMessage(new string('x', GuildRules.MessageMax + 1),
                                              out cleaned, out problem),
                  "and " + (GuildRules.MessageMax + 1) + " does not");
            Check(!GuildRules.ValidateMessage("two\nlines", out cleaned, out problem),
                  "a message carrying a newline is refused before it is sent");
            Check(GuildRules.HasControlCharacter("a\tb") && !GuildRules.HasControlCharacter("a b"),
                  "a tab counts as a control character and a space does not");
        }

        /// <summary>
        /// A player's display name, which the server holds to the guild-name rule.
        ///
        /// The property that matters is that the client NEVER SENDS a name the server will refuse,
        /// so the checks below are about the sent string (`cleaned`), not just the verdict: it
        /// must carry no leading or trailing space, no control character and a character count the
        /// column accepts. And the verdict must be the guild name's verdict, input for input -
        /// the two share their constants and helpers, and this is what fails if one of them is
        /// ever given a private copy.
        /// </summary>
        private static void CheckDisplayNameRules()
        {
            string cleaned, problem;

            Check(DisplayNameRules.Min == GuildRules.NameMin && DisplayNameRules.Max == GuildRules.NameMax,
                  "a display name has the guild name's bounds (" + DisplayNameRules.Min + " to "
                  + DisplayNameRules.Max + ")");

            Check(DisplayNameRules.Validate("  Ash  ", out cleaned, out problem) && cleaned == "Ash",
                  "a name is trimmed before it is measured, and the trimmed one is what is sent (\""
                  + cleaned + "\")");
            Check(!DisplayNameRules.Validate("ab", out cleaned, out problem) && problem.Length > 0,
                  "two characters is refused, with a sentence to show");
            Check(!DisplayNameRules.Validate("   ab   ", out cleaned, out problem),
                  "and padding it with spaces does not make it three");
            Check(!DisplayNameRules.Validate("", out cleaned, out problem)
                  && !DisplayNameRules.Validate(null, out cleaned, out problem)
                  && cleaned == "",
                  "nothing, and null, are refused");
            Check(DisplayNameRules.Validate(new string('x', DisplayNameRules.Max), out cleaned, out problem),
                  DisplayNameRules.Max + " characters is the longest name there is");
            Check(!DisplayNameRules.Validate(new string('x', DisplayNameRules.Max + 1), out cleaned, out problem),
                  "and one more is refused");
            Check(!DisplayNameRules.Validate("two\nlines", out cleaned, out problem)
                  && !DisplayNameRules.Validate("tab\there", out cleaned, out problem),
                  "a newline or a tab inside a name is refused");
            Check(!DisplayNameRules.Validate("one\u2028two", out cleaned, out problem)
                  && !DisplayNameRules.Validate("one\u2029two", out cleaned, out problem),
                  "and so are the Unicode line and paragraph separators, which glibc's cntrl class "
                  + "counts and char.IsControl does not");

            // Two emoji are four UTF-16 units and two characters. char_length says two, so the
            // column refuses it as too short; counting units would have sent it.
            string twoEmoji = "\U0001F525\U0001F525";
            Check(twoEmoji.Length == 4 && !DisplayNameRules.Validate(twoEmoji, out cleaned, out problem),
                  "two emoji are two characters, not four, so they are too short - length is "
                  + "counted the way char_length counts it");
            Check(DisplayNameRules.Validate("\U0001F525\U0001F525\U0001F525", out cleaned, out problem),
                  "and three are enough");
            string twentyOneEmoji = "";
            for (int i = 0; i < DisplayNameRules.Max + 1; i++) twentyOneEmoji += "\U0001F525";
            Check(!DisplayNameRules.Validate(twentyOneEmoji, out cleaned, out problem),
                  "and twenty-one are too many");

            // The differential: one table of inputs, run through both rules. They must agree on
            // every row, because the server applies one rule to both columns.
            string[] table =
            {
                "", " ", "a", "ab", "abc", "  abc  ", "a b", " a b ", new string('z', 20), new string('z', 21),
                "ok\n", "\tok", "ok\u2028", "\u00A0abc\u00A0", "\u00A0\u00A0\u00A0", "\U0001F525\U0001F525",
                "\U0001F525\U0001F525\U0001F525", "caf\u00E9s", "Wayfarer"
            };
            int disagreements = 0;
            string firstDisagreement = "";
            for (int i = 0; i < table.Length; i++)
            {
                string guildCleaned, guildProblem, nameCleaned, nameProblem;
                bool guild = GuildRules.ValidateName(table[i], out guildCleaned, out guildProblem);
                bool name = DisplayNameRules.Validate(table[i], out nameCleaned, out nameProblem);
                if (guild != name || guildCleaned != nameCleaned)
                {
                    disagreements++;
                    if (firstDisagreement.Length == 0) firstDisagreement = "\"" + table[i] + "\"";
                }
            }
            Check(disagreements == 0,
                  "a display name and a guild name give the same verdict and the same cleaned string "
                  + "for all " + table.Length + " inputs in the table"
                  + (disagreements == 0 ? "" : " - first to differ: " + firstDisagreement));

            // What is SENT, over everything that passes: nothing the column's CHECK would refuse.
            int unsafeSends = 0;
            for (int i = 0; i < table.Length; i++)
            {
                if (!DisplayNameRules.Validate(table[i], out cleaned, out problem)) continue;
                int characters = GuildRules.CharacterCount(cleaned);
                if (cleaned != cleaned.Trim(' ') || GuildRules.HasControlCharacter(cleaned)
                    || characters < 3 || characters > 20) unsafeSends++;
            }
            Check(unsafeSends == 0,
                  "every input that is accepted is sent as a string with no edge spaces, no control "
                  + "character and 3 to 20 characters - the column's three conditions");
        }

        /// <summary>
        /// The chat window: what it keeps, in what order, and which end it drops.
        ///
        /// THE ORDER IS THE POINT. The read asks for newest first because that is the half an
        /// index can answer; a screen reads oldest at the top. If the log ever stopped sorting,
        /// the chat would render upside down and every message would still be present - which is
        /// exactly the kind of fault that survives a glance at a screenshot.
        ///
        /// And the drop is from the OLD end. A window that trimmed the newest would silently hide
        /// the message somebody just sent, which is the one line they are certain to look for.
        /// </summary>
        private static void CheckGuildChatWindow()
        {
            GuildChatLog log = new GuildChatLog();

            List<GuildMessageEntry> newestFirst = new List<GuildMessageEntry>();
            for (int i = 5; i >= 1; i--) newestFirst.Add(Msg(i, "line " + i));
            log.Replace(newestFirst);

            bool ascending = log.Count == 5;
            for (int i = 1; i < log.Count && ascending; i++)
                if (log.Messages[i].Id <= log.Messages[i - 1].Id) ascending = false;
            Check(ascending, "a newest-first fetch is stored oldest-first, which is how it is read");
            Check(log.Count == 5 && log.Messages[0].Body == "line 1"
                  && log.Messages[4].Body == "line 5",
                  "and every line survived the turn-around");
            Check(log.NewestId == 5, "the newest id is the last one (" + log.NewestId + ")");

            List<GuildMessageEntry> withDuplicates = new List<GuildMessageEntry>();
            withDuplicates.Add(Msg(9, "nine"));
            withDuplicates.Add(Msg(9, "nine again"));
            withDuplicates.Add(Msg(8, "eight"));
            log.Replace(withDuplicates);
            Check(log.Count == 2, "a window carrying one id twice keeps it once (" + log.Count + ")");

            List<GuildMessageEntry> overflowing = new List<GuildMessageEntry>();
            for (int i = 1; i <= GuildRules.ChatWindow + 20; i++) overflowing.Add(Msg(i, "m" + i));
            log.Replace(overflowing);
            Check(log.Count == GuildRules.ChatWindow,
                  "the window holds " + GuildRules.ChatWindow + " and no more (" + log.Count + ")");
            Check(log.Messages[log.Count - 1].Id == GuildRules.ChatWindow + 20,
                  "AND IT DROPS THE OLDEST, NOT THE NEWEST - the newest is the line somebody just "
                  + "sent and came back to read");
            Check(log.Messages[0].Id == 21, "so the window starts at 21 (" + log.Messages[0].Id + ")");

            log.Replace(null);
            Check(log.Count == 0 && log.NewestId == 0,
                  "a failed fetch that answered nothing empties nothing it should not");
        }

        private static GuildMessageEntry Msg(long id, string body)
        {
            GuildMessageEntry entry = new GuildMessageEntry();
            entry.Id = id;
            entry.Body = body;
            entry.UserId = "u" + id;
            return entry;
        }

        /// <summary>
        /// Reading a row off the wire, including the two things a hand-written parser gets wrong.
        ///
        /// The timestamp is the first: PostgREST renders `timestamptz` with an offset, and reading
        /// it as a local time slides every "last seen" by the reader's own time zone - a bug that
        /// is invisible in UTC and wrong by hours everywhere else. The check is that the same
        /// instant written two ways parses to the same second.
        ///
        /// The second is the embed. A roster row carries its member's profile nested, because
        /// PostgREST resolved the foreign key inline; a row whose embed is missing is still a
        /// member and must not be dropped, or a roster loses a line over a display name.
        /// </summary>
        private static void CheckGuildRowReading()
        {
            long utc = GuildCodec.ParseTimestamp("2026-09-21T15:04:05+00:00");
            long plusTwo = GuildCodec.ParseTimestamp("2026-09-21T17:04:05+02:00");
            Check(utc > 0 && utc == plusTwo,
                  "THE SAME INSTANT WRITTEN IN TWO ZONES PARSES TO ONE SECOND - the offset is read "
                  + "rather than assumed, so 'last seen' does not slide with the device's zone");
            Check(GuildCodec.ParseTimestamp("2026-09-21T15:04:05.123456+00:00") == utc,
                  "and fractional seconds do not move it");
            Check(GuildCodec.ParseTimestamp("") == 0 && GuildCodec.ParseTimestamp("not a date") == 0,
                  "an unreadable timestamp is 0, which every caller renders as 'no stamp'");

            const string roster = @"[
              { ""user_id"": ""u-1"", ""role"": ""leader"", ""joined_at"": ""2026-09-01T10:00:00+00:00"",
                ""last_seen"": ""2026-09-21T15:04:05+00:00"",
                ""profiles"": { ""display_name"": ""Matthias"", ""friend_code"": ""ABC234"" } },
              { ""user_id"": ""u-2"", ""role"": ""officer"", ""joined_at"": ""2026-09-02T10:00:00+00:00"",
                ""last_seen"": ""2026-09-21T15:04:05+00:00"" },
              { ""role"": ""member"" }
            ]";
            List<GuildMemberEntry> members = GuildCodec.ReadRows(roster,
                delegate (JsonValue row) { return GuildCodec.ReadMember(row, "u-2"); });

            Check(members.Count == 2,
                  "a roster row with no user_id is dropped and the rest survive (" + members.Count + ")");
            Check(members.Count == 2 && members[0].Role == GuildRole.Leader
                  && members[1].Role == GuildRole.Officer,
                  "each row's role arrives as the thing the permission matrix is asked about");
            Check(members.Count == 2 && members[0].DisplayName == "Matthias"
                  && members[0].FriendCode == "ABC234",
                  "the embedded profile is read out of the row PostgREST nested it in");
            Check(members.Count == 2 && members[1].DisplayName == "",
                  "AND A MEMBER WITH NO EMBED IS STILL A MEMBER - a roster does not lose a line "
                  + "over a missing display name");
            Check(members.Count == 2 && !members[0].IsSelf && members[1].IsSelf,
                  "and the reader works out which line is the caller's own");
            Check(members.Count == 2 && members[0].PowerScore == -1,
                  "power starts at -1, not 0 - 'no line published' and 'a line worth nothing' are "
                  + "different sentences and the roster says different things for them");

            const string chat = @"[
              { ""id"": 412, ""user_id"": ""u-2"", ""body"": ""ready when you are"",
                ""created_at"": ""2026-09-21T15:04:05+00:00"",
                ""profiles"": { ""display_name"": ""Rival"" } },
              { ""user_id"": ""u-1"", ""body"": ""no id, dropped"" }
            ]";
            List<GuildMessageEntry> lines = GuildCodec.ReadRows(chat,
                delegate (JsonValue row) { return GuildCodec.ReadMessage(row, "u-2"); });
            Check(lines.Count == 1 && lines[0].Id == 412 && lines[0].IsMine
                  && lines[0].DisplayName == "Rival",
                  "a chat row reads its id, its author and whether it is the caller's own");

            Check(GuildCodec.ReadRows("{ not json", GuildCodec.ReadGuild).Count == 0,
                  "and a response that is not an array reads as no rows rather than throwing");

            GuildSummary guild = GuildCodec.ReadGuild(JsonValue.Parse(
                @"{ ""id"": ""g-1"", ""name"": ""The Long Watch"", ""guild_code"": ""ABC234"",
                    ""is_open"": true, ""member_count"": 7 }"));
            Check(guild != null && guild.Name == "The Long Watch" && guild.IsOpen
                  && guild.MemberCount == 7,
                  "a guild from the code lookup carries how full it is, which is most of the "
                  + "decision to apply");
            GuildSummary noCount = GuildCodec.ReadGuild(JsonValue.Parse(
                @"{ ""id"": ""g-1"", ""name"": ""The Long Watch"", ""guild_code"": ""ABC234"" }"));
            Check(noCount != null && noCount.MemberCount == -1,
                  "and a guild read without one says -1 rather than claiming it is empty");

            Check(GuildRules.LastSeenLabel(1000, 1100) == "ONLINE"
                  && GuildRules.LastSeenLabel(0, 1100) == ""
                  && GuildRules.LastSeenLabel(1000, 1000 + 3600) == "1H AGO",
                  "last seen reads as a sentence, and a stamp of 0 says nothing rather than 1970");
        }

        /// <summary>
        /// THE JOIN BETWEEN THE TWO HALVES: the client's copies of four numbers, read back out of
        /// the SQL that makes them true.
        ///
        /// GuildRules duplicates the cap, the name bounds, the description ceiling, the message
        /// ceiling and the chat cooldown from 0004 and 0005, deliberately and for the reason
        /// FriendCode's alphabet is duplicated: the database is what guarantees a rule, and the
        /// client is what tells a player before a round trip, so neither can be the other's
        /// source. What that reasoning does NOT excuse is the two drifting apart, which nothing
        /// else in this project would notice - a cap of 30 on the server and 25 on the client
        /// looks like a working game right up until a guild has 26 members and the roster says it
        /// is full.
        ///
        /// So this reads the migration files and asserts the numbers appear in them. It is a
        /// grep, not a parse, and that is enough for the failure being guarded against: somebody
        /// changing one side without the other.
        /// </summary>
        private static void CheckGuildConstantsMatchTheMigrations(string contentDir)
        {
            string migrations;
            try
            {
                migrations = Path.GetFullPath(Path.Combine(contentDir,
                    Path.Combine("..", Path.Combine("..", Path.Combine("..",
                        Path.Combine("Server", Path.Combine("supabase", "migrations")))))));
            }
            catch (Exception)
            {
                migrations = "";
            }

            string tables = Path.Combine(migrations, "0004_guilds.sql");
            string calls = Path.Combine(migrations, "0005_guild_rpcs.sql");
            if (!File.Exists(tables) || !File.Exists(calls))
            {
                // Not a failure. The harness is handed a content directory and is run from a build
                // output; a checkout that has one without the other is a legitimate shape, and a
                // check that cannot read its subject reports that rather than failing it.
                Line("  [note] Server/supabase/migrations was not found beside the content directory,");
                Line("         so the client's constants were not compared against the SQL this run.");
                return;
            }

            string sql = File.ReadAllText(tables) + "\n" + File.ReadAllText(calls);

            Check(sql.Contains("select " + GuildRules.MemberCap + ";"),
                  "guild_member_cap() in the SQL is " + GuildRules.MemberCap
                  + ", which is what GuildRules.MemberCap says");
            Check(sql.Contains("char_length(name) between " + GuildRules.NameMin
                               + " and " + GuildRules.NameMax),
                  "the name bounds in the SQL are " + GuildRules.NameMin + " to " + GuildRules.NameMax);
            Check(sql.Contains("char_length(description) <= " + GuildRules.DescriptionMax),
                  "the description ceiling in the SQL is " + GuildRules.DescriptionMax);
            Check(sql.Contains("char_length(body) between 1 and " + GuildRules.MessageMax),
                  "the message ceiling in the SQL is " + GuildRules.MessageMax);
            Check(sql.Contains("interval '" + GuildRules.ChatCooldownSeconds + " seconds'"),
                  "the chat cooldown in the SQL is " + GuildRules.ChatCooldownSeconds + " seconds");
            Check(sql.Contains("'^[2-9A-HJKMNP-TV-Z]{6}$'"),
                  "and the guild code's CHECK restates the friend-code alphabet, so a stored code "
                  + "is always one FriendCode can read");

            string profiles = Path.Combine(migrations, "0001_profiles.sql");
            if (File.Exists(profiles))
                Check(File.ReadAllText(profiles).Contains("display_name text not null default '"
                                                          + DisplayNameRules.Default + "'"),
                      "a profile's display_name defaults to '" + DisplayNameRules.Default
                      + "' in the SQL, which is the value DisplayNameRules.Default treats as \"not "
                      + "chosen yet\"");
        }

        /// <summary>Where two documents first disagree, with enough either side to see what
        /// moved. A length-equal mismatch is almost always a reordering or a single value, and
        /// "they differ" without saying where costs an hour every time it happens.</summary>
        private static string FirstDifference(string expected, string actual)
        {
            int limit = Math.Min(expected.Length, actual.Length);
            int at = -1;
            for (int i = 0; i < limit; i++) { if (expected[i] != actual[i]) { at = i; break; } }
            if (at < 0) at = limit;
            int from = Math.Max(0, at - 30);
            int take = Math.Min(70, Math.Min(expected.Length, actual.Length) - from);
            if (take <= 0) return "at " + at + " (one document ends there)";
            char[] breaks = { '\n', '\r' };
            string wanted = expected.Substring(from, Math.Min(take, expected.Length - from));
            string found = actual.Substring(from, Math.Min(take, actual.Length - from));
            return "at " + at + " expected [" + Flatten(wanted, breaks) + "] got [" + Flatten(found, breaks) + "]";
        }

        private static string Flatten(string text, char[] breaks)
        {
            string[] parts = text.Split(breaks, StringSplitOptions.RemoveEmptyEntries);
            return string.Join(" ", parts).Trim();
        }
    }
}
